window.__CS249R_CHAPTERS__["vol2/11_edge_intelligence"] = {"key": "vol2/11_edge_intelligence", "sections": [{"id": "sec-1", "level": 2, "title": "Purpose"}, {"id": "sec-2", "level": 2, "title": "The Edge Learning Paradigm"}, {"id": "sec-3", "level": 2, "title": "Why Learn on the Device"}, {"id": "sec-4", "level": 3, "title": "Simpler alternatives first"}, {"id": "sec-5", "level": 3, "title": "Where adaptation pays"}, {"id": "sec-6", "level": 3, "title": "What crosses the device boundary"}, {"id": "sec-7", "level": 2, "title": "Design Constraints"}, {"id": "sec-8", "level": 3, "title": "Quantifying training overhead on edge devices"}, {"id": "sec-9", "level": 3, "title": "Model constraints"}, {"id": "sec-10", "level": 3, "title": "Data constraints"}, {"id": "sec-11", "level": 3, "title": "Compute constraints"}, {"id": "sec-12", "level": 3, "title": "Energy, heat, and background admission"}, {"id": "sec-13", "level": 3, "title": "Matching edge constraints to adaptation pillars"}, {"id": "sec-14", "level": 2, "title": "Model Adaptation"}, {"id": "sec-15", "level": 3, "title": "Transfer as the premise"}, {"id": "sec-16", "level": 3, "title": "Weight freezing"}, {"id": "sec-17", "level": 3, "title": "Structured parameter updates"}, {"id": "sec-18", "level": 3, "title": "Sparse updates"}, {"id": "sec-19", "level": 2, "title": "Data Efficiency"}, {"id": "sec-20", "level": 3, "title": "Few-shot learning and data streaming"}, {"id": "sec-21", "level": 3, "title": "Experience replay"}, {"id": "sec-22", "level": 3, "title": "Data compression"}, {"id": "sec-23", "level": 3, "title": "Data efficiency strategy comparison"}, {"id": "sec-24", "level": 2, "title": "Federated Learning Algorithms"}, {"id": "sec-25", "level": 3, "title": "Cross-device and cross-silo federations"}, {"id": "sec-26", "level": 3, "title": "Learning protocols"}, {"id": "sec-27", "level": 2, "title": "Federated Learning Systems at Scale"}, {"id": "sec-28", "level": 3, "title": "Client scheduling"}, {"id": "sec-29", "level": 3, "title": "Bandwidth-aware update compression"}, {"id": "sec-30", "level": 3, "title": "Federated personalization"}, {"id": "sec-31", "level": 3, "title": "Federated privacy"}, {"id": "sec-32", "level": 3, "title": "Large-scale device orchestration"}, {"id": "sec-33", "level": 2, "title": "Continual Adaptation Under Edge Budgets"}, {"id": "sec-34", "level": 3, "title": "Learning from unlabeled sensor streams"}, {"id": "sec-35", "level": 3, "title": "Continual adaptation and catastrophic forgetting"}, {"id": "sec-36", "level": 2, "title": "Integrating the Edge Intelligence Pillars"}, {"id": "sec-37", "level": 2, "title": "Production Integration"}, {"id": "sec-38", "level": 3, "title": "MLOps integration challenges"}, {"id": "sec-39", "level": 2, "title": "Engineering Challenges and Mitigations"}, {"id": "sec-40", "level": 3, "title": "Device and data heterogeneity management"}], "html": "<h1 id=\"sec-1\" class=\"cs-h1\">Edge Intelligence</h1>\n<h2 id=\"sec-1\" class=\"cs-h2\">Purpose</h2>\n<p><em>When does learning need to move from the data center to the devices it serves?</em></p>\n<p>A model trained in a data center encounters new conditions when deployed to a user's device. Vocabulary, lighting, acoustics, and usage patterns may differ from the distributions that shaped its parameters, and the gap can widen as behavior evolves. Centralized training cannot anticipate every context, while privacy constraints or limited connectivity may prevent local observations from reaching it. Learning where the data is produced can improve local behavior, but running predictions offline does not by itself justify training there. Adaptation must provide enough benefit to justify its memory, battery, and thermal costs without disrupting the device's primary work. A training job that fits on an idle phone may become unacceptable when the user starts another application. Even successful local learning leaves a fleet problem: improvements must be evaluated across devices whose capabilities, data, and availability differ. A policy that accepts updates only from well-connected devices may improve measured results while neglecting users whose devices rarely qualify. Making one device learn efficiently therefore does not establish that a population can learn reliably or that exchanging model updates protects private information. The engineering decision joins the value of local adaptation with the cost of participation and the evidence needed to trust shared improvements. In C³ terms, compute must fit each device, communication must carry useful updates within limited connectivity windows, and coordination must preserve a representative learning population despite dropout and unequal resources.</p>\n<div class=\"cs-callout\"><div class=\"cs-callout-title\">Learning Objectives</div>\n<ul class=\"cs-list\">\n<li>Contrast centralized cloud training, on-device learning, and federated learning by analyzing their data flow, privacy properties, and operational trade-offs</li>\n<li>Quantify edge-device training overhead relative to inference-only deployment across memory, compute, and energy</li>\n<li>Derive an admission condition for background adaptation from energy, thermal, and foreground-latency slack</li>\n<li>Select model-adaptation and data-efficiency methods by the memory term each shrinks, its forgetting risk, and its storage cost</li>\n<li>Analyze how client sampling, dropout, and non-IID data determine which population a federated model learns from and its time to target</li>\n<li>Design federated learning systems that aggregate privacy-preserving updates within uplink, secure-aggregation, and version-compatibility limits</li>\n<li>Explain the operational controls needed for on-device learning: device-aware deployment, distributed validation, privacy-preserving monitoring, and rollback across heterogeneous populations</li>\n</ul>\n</div>\n<h2 id=\"sec-2\" class=\"cs-h2\">The Edge Learning Paradigm</h2>\n<p>Imagine a voice assistant trained on millions of generic audio samples in a cloud data center. When deployed, it may struggle with a regional accent or household vocabulary. Without local adaptation, its performance can decline as usage diverges from the training distribution. <strong>Edge intelligence</strong> places inference, adaptation, and coordination on or near the devices that observe the data, allowing models to respond to local context under power, memory, privacy, and connectivity constraints.</p>\n<p>The serving fleet already has to meet latency targets despite failures and uneven demand. At the edge, the operator also loses control over when a device has power, connectivity, or spare memory. The unit of design remains the fleet, but its participants can disappear between selection and completion. Local adaptation matters here because its cost determines which users can contribute to population learning.</p>\n<p>↩ Serving fleets that hold latency service-level objectives (SLOs) through replica failures and uneven demand are established in @sec-inference-scale.</p>\n<p><em><strong>On-device learning</strong></em> is the local training or adaptation of machine learning models directly on deployed hardware, using data that remains on the device; a local update needs no server connection, although sharing its result does.</p>\n<ol class=\"cs-list\">\n<li><strong>Significance</strong>: It enables personalization and continued adaptation where connectivity is intermittent or raw data may not leave the device. In single-machine iron-law terms, each update adds backward and optimizer work to the compute term $\\Operations/(\\PeakRate \\cdot \\EfficiencyHw)$ that foreground inference also needs, and it draws on a separate battery and thermal budget that the admission test of @eq-edge-background-admission later makes explicit.</li>\n<li><strong>Distinction</strong>: Unlike edge inference, which only executes a fixed model, on-device learning runs a local optimization loop (forward and backward passes plus parameter updates) that requires more memory and compute than the forward pass alone.</li>\n<li><strong>Common pitfall</strong>: A frequent misconception is that on-device learning requires training from scratch. In reality, it is almost always <strong>on-device adaptation</strong>, which fine-tunes a small subset of a pretrained base model's parameters to fit the data distribution of a local environment.</li>\n</ol>\n<p>Consider one federated round for the voice assistant. A coordinator selects eligible devices and distributes a shared model version and a bounded training policy. Each selected device trains on local examples when its policy admits background work, then returns a model update tagged with the starting version. Some devices lose connectivity or exhaust their resource allowance. The coordinator closes the round according to its deadline and participation requirements, combines compatible updates, evaluates the candidate shared model, and publishes an accepted version for later download. Local personalization can remain on the device instead of entering that aggregate.</p>\n<p>This round has the shape of Archetype C (Federated MobileNet), with phone-class clients, private local data, and intermittent availability, and it exposes the C³ trade-off before any adaptation method is chosen. The Fleet Law (@eq-fleet-law) gives it a time budget, with one change of reading. In a data center the compute term divides one job's work across $\\DeviceCount$ devices. Here every selected device trains its own copy on its own data, so the term is set by local training on the slowest device the round still waits for rather than divided by $\\DeviceCount$. The communication term is the update transfer over a wide-area uplink. The synchronization term is the wait for enough participants to report. The overlap term credits whatever downloading and training proceed concurrently.</p>\n<p>More local compute can reduce the frequency of communication, but devices then need longer uninterrupted training windows and their models can drift toward different local distributions. Short deadlines improve coordination speed while excluding slow participants. The fleet must therefore account for whose updates complete, rather than merely how many devices were selected. Device budgets, adaptation methods, and data reuse determine the work inside the round; aggregation and scheduling determine whether that work improves the shared model. A round of this kind, repeated across a population, is federated learning.</p>\n<p>↩ Archetype C (Federated MobileNet), the phone-class federated workload with private local data and intermittent availability, is established in @sec-introduction-archetype-c-federated-mobilenet-65a3.</p>\n<p><em><strong>Federated learning</strong></em> is a decentralized training paradigm where distributed devices collaboratively train a shared model using local data while exchanging only model updates (gradients or weights).</p>\n<ol class=\"cs-list\">\n<li><strong>Significance</strong>: It transforms the constraint of data locality into a privacy feature. Within the Fleet Law (@eq-fleet-law), federated learning is constrained by wide-area bandwidth ($\\Bandwidth$) in its communication term and by the extreme heterogeneity of the fleet, where device-specific efficiency $(\\EfficiencyHw)$ and availability can vary by orders of magnitude.</li>\n<li><strong>Distinction</strong>: Unlike centralized training, where data is moved to the compute, federated learning moves compute to the data. Raw training examples can remain local, but model updates, participation metadata, and protocol messages still cross the device boundary and may carry personal information.</li>\n<li><strong>Common pitfall</strong>: A frequent misconception is that federated learning is \"inherently private.\" In reality, model updates themselves can leak information through gradient inversion attacks, which search for inputs whose gradient matches a submitted update and so reconstruct training examples, requiring additional protections like differential privacy or secure aggregation.</li>\n</ol>\n<p>Keeping raw examples local reduces one source of exposure, but an update can still reveal information about the examples that produced it. Secure aggregation lets the coordinator obtain a combined update without inspecting each client's contribution under the protocol's trust assumptions. Differential privacy bounds how much a specified user's or record's participation can change the released result, usually by limiting contributions and adding calibrated noise. Neither protection follows automatically from federation. Their costs and assumptions belong in the round design alongside dropout handling and communication.</p>\n<p>↪ Differential privacy definitions, noise mechanisms, and privacy accounting are developed in @sec-security-privacy-differential-privacy-8c2b.</p>\n<p>: <strong>Differential privacy</strong>: A mathematical framework that bounds information leakage by adding calibrated noise to computations. In edge learning, that noise becomes a systems cost because noisier updates usually require more rounds or more data to reach the same utility.</p>\n<p>Whether a deployment uses federated rounds or purely local updates, a smartphone predicting user text input, a smart home device responding to household routines, and an autonomous vehicle interpreting local driving conditions can all encounter variation that centralized training data underrepresents. The smartphone meets user-specific phrasing. The home device observes seasonal shifts in household routines. The vehicle faces local road conditions, weather patterns, and traffic habits that differ from its training environment. Such gaps make a case for on-device learning (definition \\ref{dfn-edge-intelligence-device-learning}), moving machine learning from centralized training to distributed learning across heterogeneous devices that operate under tight power, memory, and thermal limits. Because local training spends those scarce device budgets, a distribution gap is a case for adaptation rather than a verdict; an engineering analysis must first establish when local learning is necessary and whether a given update measurably improves behavior.</p>\n<h2 id=\"sec-3\" class=\"cs-h2\">Why Learn on the Device</h2>\n<p>A distribution gap justifies spending device resources only when centralized retraining cannot close it in time or within policy. A cloud-trained model that relies on a server round trip or a raw-data upload for every adjustment fails whenever a user has an unfamiliar accent, a remote sensor loses connectivity, a regulation forbids exporting personal traces, or millions of devices would overwhelm backend ingestion. Those four pressures (personalization, latency and availability, privacy, and infrastructure efficiency) motivate shifting learning to the edge [@li2020].</p>\n<p>Personalization matters when deployed models encounter usage patterns and data distributions that their training environments represent poorly. Local adaptation can refine behavior using user-specific data, including linguistic preferences, physiological baselines, sensor characteristics, or environmental conditions. High inter-user variability justifies changing weights only if the adapted model measurably beats a fixed model with local context.</p>\n<p>Latency and availability constraints determine where an update can run and how soon it can become useful. In edge computing scenarios, connectivity to centralized infrastructure may be unreliable, delayed, or intentionally limited to preserve bandwidth or reduce energy consumption. When adaptation is justified, local learning permits updates during disconnected periods. The update must still fit the device's resource budget, and its completion deadline is separate from the response deadline for foreground inference.</p>\n<p>Privacy is the third driver. Many applications involve sensitive or regulated data including biometric measurements, typed input, location traces, or health information. Local learning can reduce privacy exposure by keeping raw data on the device and limiting transmission to centralized systems. This can simplify compliance engineering, but it does not by itself establish adherence to regulations such as the General Data Protection Regulation (GDPR), the Health Insurance Portability and Accountability Act (HIPAA) [@hhs2026hipaaSecurity], or region-specific data sovereignty laws.</p>\n<p>Infrastructure efficiency is the economic driver. Centralized training pipelines require backend infrastructure to collect, store, and process user data from potentially millions of devices. Shifting learning to the edge distributes computation and can reduce raw-data ingestion. The resulting savings must be compared with device energy, repeated model transfers, and coordination overhead; whether moving work off the server lowers end-to-end cost depends on that whole sum, not on the server bill alone.</p>\n<h3 id=\"sec-4\" class=\"cs-h3\">Simpler alternatives first</h3>\n<p>Before paying that device and coordination cost, an engineering team should test whether a static model paired with local state already meets the requirement. Shipping an on-device gradient-training loop when a local feature store or lookup table suffices spends memory, battery, and rollback margin for no measurable gain, whereas simpler alternatives often achieve comparable quality with far lower operational overhead. Three such alternatives often satisfy personalization and adaptation requirements without the complexity of local training (@tbl-edge-ondevice-learning-alternatives).</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Alternative</strong></th><th><strong>Mechanism</strong></th><th><strong>When it fits</strong></th></tr></thead><tbody>\n<tr><td><strong>Feature-based personalization</strong></td><td>Store user preferences, interaction history, and behavioral features locally, then feed those features into a static model rather than adapting model weights.</td><td>News recommendation systems can store topic preferences and reading patterns locally, then combine those features with a centralized content model.</td></tr>\n<tr><td><strong>Cloud-based fine-tuning with privacy controls</strong></td><td>Fine-tune centrally on data authorized for transfer, with access controls and, where required, a specified differential-privacy mechanism. Federated analytics and secure aggregation [@bonawitz2017] can support aggregate statistics but do not themselves provide centralized training examples.</td><td>Centralized updates fit when authorized data transfer, update latency, and the specified privacy guarantees meet the application requirements.</td></tr>\n<tr><td><strong>User-specific lookup tables</strong></td><td>Combine global models with personalized retrieval mechanisms by maintaining a lightweight table for frequently accessed local patterns.</td><td>Personalization benefits are needed with minimal computational and storage overhead.</td></tr>\n</tbody></table></div>\n<p>: <strong>Alternatives to On-Device Learning</strong>: Simpler personalization mechanisms can satisfy many adaptation requirements without local gradient updates, so on-device learning should be reserved for cases where privacy, latency, connectivity, or measured quality requirements rule out these options. {#tbl-edge-ondevice-learning-alternatives tbl-colwidths=\"[24,44,32]\"}</p>\n<p>The decision to implement on-device learning should follow evidence that simpler alternatives cannot meet the deployment requirements, such as restrictions on transferring training data or unreliable connectivity when adaptation is needed. Latency is the requirement most often mistaken for such evidence. For applications whose foreground deadlines are shorter than the network round-trip time, cloud inference is architecturally infeasible. Camera processing under 33 ms, voice response under 500 ms, AR/VR motion-to-photon latency under 20 ms, or safety-critical control under 10 ms all face network round-trip times typically ranging from 50 to 200 ms. When the network cannot meet the foreground deadline, inference must remain local. A fixed model also executes offline, however, so the deadline settles where the model runs and leaves open where it learns. Local training earns its engineering investment only when a measured adaptation gain justifies its added resource and operational costs.</p>\n<h3 id=\"sec-5\" class=\"cs-h3\">Where adaptation pays</h3>\n<p>Every application domain must justify adaptation against its simpler alternatives, and the domains differ in which resource binds first. A smartphone keyboard encounters personal vocabulary and changing typing patterns that may be poorly represented in its released model. Local training can use those observations for personalization or contribute updates to a shared model; these are separate objectives. Google's Gboard, for instance, employs federated learning to improve shared models across a large population of users while keeping raw data local to each device [@hard2018federated].</p>\n<p>: <strong>Gboard (2017)</strong>: One of the first widely reported commercial federated learning deployments at mobile scale. Published reports showed that keyboard models could improve from aggregated on-device updates while raw typed text remained local. The systems consequence is durable. Compressed updates and privacy mechanisms make cross-fleet learning possible over constrained mobile networks without centralizing raw keystrokes.</p>\n<p>The same keyboard also runs two interactive prediction strategies at inference time (@fig-ondevice-gboard). Next-word prediction ranks discrete candidate tokens (\"favorite,\" \"address,\" \"schedule\") in the suggestion bar, whereas Smart Compose generates multi-word inline ghost text (\"ail address\") through on-the-fly rescoring directly inside the input buffer. Both mechanisms personalize the immediate interaction through local context; longer-lived model improvement occurs separately when federated training aggregates eligible on-device updates.</p>\n<p>Wearable health monitors, which track activity and physiology from accelerometers, heart rate sensors, and electrodermal activity monitors, face a different personalization problem. Individual physiological baselines and sensor placement can affect predictions, motivating calibration or local adaptation. Evaluation must distinguish useful personalization from learning away a change the application is meant to detect. A monitor that adapts to a user's steadily rising resting heart rate has normalized the very signal it exists to flag. Keeping observations local reduces raw-data transfer; whether the adapted model is more accurate is a separate measurement against held-out outcomes.</p>\n<p>Voice interfaces in smart speakers and earbuds must recognize commands quickly and accurately in noisy, changing acoustic environments, starting with wake-word detection. These systems face foreground latency requirements, such as an end-to-end response target under 500 ms and a wake-word detection target below 100 ms. Those targets constrain inference and the interference permitted from background learning. Local adaptation addresses a separate quality objective: reducing false activations and missed detections for a user's voice and acoustic environment. Far-field microphone configurations and room acoustics motivate that adaptation, but its value must be measured while preserving foreground response times.</p>\n<p>: <strong>Wake-word detection</strong>: An always-on detector incurs inference cost throughout the listening period, even when no keyword occurs. Published keyword-spotting results on dedicated neural processors, plotted in @fig-edge-inference-landscape, spend on the order of 30 to 160 $\\Glyph{\\mu}$J per evaluation, so the energy budget is set by how often the detector evaluates over the listening period as much as by the cost of any one evaluation. Local personalization adds a separate update cost and earns its place only if evaluation shows an acceptable trade-off between missed keywords, false activations, and energy use.</p>\n<p>Industrial IoT and remote monitoring systems expose the availability side of the decision. In agricultural sensing, pipeline monitoring, or environmental surveillance, connectivity to centralized infrastructure may be limited, expensive, or unavailable. Local inference permits continued detection while disconnected. Local learning adds the ability to adjust thresholds or track seasonal trends, provided the update preserves the distinction between expected variation and anomalies. The consequences of missed detections make validation and a recoverable baseline part of the adaptation design.</p>\n<p>Embedded computer vision systems, including robotics, AR/VR, and smart cameras, combine substantial visual processing with the tight foreground deadlines of @sec-edge-intelligence-alternative-approaches-decision-criteria-bd36, from a 33 ms frame interval down to a sub-10 ms control loop. On-device adaptation can recalibrate a model to new lighting conditions, object appearances, or motion patterns, but it spends resources needed by that foreground pipeline. A useful update must improve validated behavior without exhausting the latency margin that made local inference viable.</p>\n<p>Each domain turns a possible adaptation benefit into a resource decision. Mobile keyboards must fit update state alongside typing, wearables must budget energy across repeated updates, voice and vision systems must preserve foreground deadlines, and disconnected sensors must decide whether a fixed model remains adequate.</p>\n<h3 id=\"sec-6\" class=\"cs-h3\">What crosses the device boundary</h3>\n<p>Once a domain justifies local learning, the next question is whether each device learns in isolation or shares what it discovers with the fleet. Keeping all learning strictly inside each device prevents a fleet from sharing new words, road hazards, or acoustic patterns discovered across millions of users, yet uploading raw observations to a central cluster exposes private data and consumes wide-area bandwidth. Centralized training collects data on managed infrastructure and releases validated model versions to devices; local adaptation instead changes a device's model using observations that may be unavailable centrally. Hardware, software, power, and connectivity then vary across the learning population, so an operator must coordinate model versions and evaluate updates from intermittently participating clients [@bonawitz2019towards].</p>\n<p>A returning device may hold an old model or fail to apply a release. Signed updates, functional checks, deployment telemetry, and rollback therefore form part of the learning protocol [@bonawitz2019towards].</p>\n<p>The central decision is how much state to share across devices. Centralized training, local-only adaptation, and federated coordination are architectural choices that can coexist in one deployment. Local-only adaptation specializes a model to its user's observations, which are often non-IID and noisy, so sharing that specialization requires an explicit boundary between personal state and the parameters intended to improve the population model. Federated coordination adds population learning by periodically aggregating updates to shared parameters. A deployment must specify which parameters enter the aggregate and which remain personal; averaging every local adaptation would erase that distinction. Data locality limits raw-data transfer, while separate privacy controls govern the updates that leave each device. The three architectures therefore differ in what crosses the device boundary, not in how advanced they are (@fig-centralized-vs-decentralized): local-only learning sends nothing, centralized training sends raw examples, and federated learning sends only model updates $\\FiniteChange\\ModelParameters$ while receiving the shared weights $\\ModelParameters$.</p>\n<p>: <strong>Non-IID (not independent and identically distributed)</strong>: Samples may be dependent or drawn from different distributions; in a device fleet, user-specific label and feature distributions can make local updates conflict. Such distributions can degrade federated averaging relative to independent and identically distributed (i.i.d.) baselines [@zhao2018federated]. The observed failure determines whether to change local work, aggregation, or personalization rather than prescribing one remedy for every non-IID population.</p>\n<p>The choice of shared and personal state must fit the devices that execute it. Managed data centers can provision capacity and schedule training across dedicated resources; edge devices share limited power, memory, and cooling with foreground applications. Those local budgets determine which adaptation and coordination choices remain feasible.</p>\n<h2 id=\"sec-7\" class=\"cs-h2\">Design Constraints</h2>\n<p>Fine-tuning a neural network on a smartphone is constrained by power and heat: a GPU training cluster may consume megawatts in a controlled facility, whereas a smartphone sustains only a few watts before throttling. Across the edge spectrum, memory ranges from a few gigabytes on phones down to hundreds of kilobytes on microcontrollers, sustained power ranges from a few watts down to milliwatts, and network connectivity may be intermittent or entirely absent. On-device learning must therefore use compute, memory, and data sparingly, and when a local model operates in a safety-critical loop, these resource limits become life-safety engineering problems.</p>\n<p>These constraints run through Archetype C (Federated MobileNet), where learning happens on phone-class devices whose power budget spans roughly <code>[EdgeMobilePowerEnvelope.envelope_range_str]</code>, a few watts sustained with brief bursts toward <code>[EdgeMobilePowerEnvelope.burst_high_str]</code>, and which must share that budget with the user's foreground work. Privacy and policy constraints often forbid moving raw examples off the device, and even where transfer is permitted, a mobile uplink and battery rarely afford shipping raw data to the cloud. Data locality is therefore both a policy requirement and a bandwidth and energy constraint. Quantized training, sparse updates, and federated coordination are the strategies that let Archetype C learn within that envelope. Held at that burst ceiling, an idealized <code>[EdgeMobilePowerEnvelope.battery_wh_str]</code> battery would be exhausted in about <code>[EdgeMobilePowerEnvelope.burst_battery_hours_str]</code>, and thermal throttling would end the workload sooner. Microcontroller-class sensors with hundreds of kilobytes of memory and milliwatt budgets sit at an extreme below Archetype C, and this chapter treats them as such.</p>\n<p>The constraints on parameters, operations, and data interact. A larger batch can improve hardware utilization while exceeding memory capacity; a smaller trainable state can fit memory while extracting too little signal from local data. Compression provides one way to reach a feasible starting point. Quantization shrinks bytes per weight, pruning removes selected parameters, and knowledge distillation transfers behavior into a smaller architecture. Once the base model fits, local learning must also accommodate the state and work needed to adapt it.</p>\n<p>On-device learning adds training state and work to the inference workload. A full-model update requires forward propagation, gradient computation through backpropagation, and weight updates. Memory grows because the update must hold gradients, optimizer state, and the activations saved for the backward pass. Arithmetic grows because the backward pass computes gradients with respect to both activations and weights, up to roughly twice the work of the forward pass. The size of each increase depends on the model, batch, precision, and execution schedule. Compression and selective adaptation address different parts of that pressure, so feasibility requires accounting for the resulting working set rather than applying a universal multiplier.</p>\n<p>The relevant budget is the capacity available to the learning task. Centralized training can reserve resources and assemble datasets under a common management policy. A device must fit an update around the operating system, foreground applications, and locally available examples. Total installed memory or peak accelerator throughput therefore overstates what background learning can use.</p>\n<p>These constraints define eligibility for a federated round. Model footprint and trainable state determine which device tiers can participate. Sparse, nonuniform data determines how much signal each local update can extract. Limited compute determines when training can run at all. A policy that exceeds the budget on weaker devices changes the population represented in the aggregate, even if it improves throughput on stronger devices.</p>\n<h3 id=\"sec-8\" class=\"cs-h3\">Quantifying training overhead on edge devices</h3>\n<p>A compact 10M-parameter model whose <code>[EdgeTrainingMemoryStack.weights_mb_str]</code> of FP32 weights fit comfortably inside a smartphone's background-memory allowance can balloon to <code>[EdgeTrainingMemoryStack.total_mb_str]</code> as soon as backpropagation adds gradients, optimizer state, and saved activations. That total exceeds the background memory ceiling and crashes the process on its first backward pass. Training changes memory footprint, memory bandwidth, and hardware utilization through additional live state and backward operations. The illustrative increases in @tbl-training-amplification count different things from row to row, so each multiplier carries its own denominator. The <code>[EdgeTrainingMemoryStack.range_mult_str]</code> memory range compares a training working set with the inference weights alone, leaving inference activations and workspace out of the denominator. The 2--3$\\times$ compute range compares one update (forward plus a backward pass of one to two times the forward work) with one inference. The 10--50$\\times$ energy range compares a converged adaptation, which takes many gradient steps, with a single inference, so it is not a per-sample multiplier.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Constraint dimension</strong></th><th><strong>Inference</strong></th><th><strong>Training amplification</strong></th><th><strong>Impact on design</strong></th></tr></thead><tbody>\n<tr><td><strong>Memory Footprint</strong></td><td>Model weights + single activation map</td><td>Weights + full activation cache + gradients + optimizer state</td><td>4--12$\\times$ the inference weights alone; forces aggressive compression</td></tr>\n<tr><td><strong>Compute Operations</strong></td><td>Forward pass only</td><td>Forward + backward + weight update</td><td>2--3$\\times$ one inference, per update step; limits model complexity</td></tr>\n<tr><td><strong>Memory Bandwidth</strong></td><td>Sequential weight reads</td><td>Bidirectional data flow for gradients</td><td>Additional traffic depends on update scope and activation schedule</td></tr>\n<tr><td><strong>Energy per Adaptation</strong></td><td>Single inference operation</td><td>Multiple gradient steps with convergence</td><td>10--50$\\times$ one inference, per converged adaptation; requires opportunistic scheduling</td></tr>\n<tr><td><strong>Data Requirements</strong></td><td>Current inputs; no training labels required</td><td>Local update examples, often sparse or noisy</td><td>Necessitates sample-efficient methods</td></tr>\n<tr><td><strong>Hardware Utilization</strong></td><td>Optimized for forward passes</td><td>Different access patterns for backprop</td><td>Inference accelerators may not help training</td></tr>\n</tbody></table></div>\n<p>: <strong>Training Amplifies Inference Constraints</strong>: On-device learning operates under the same efficiency constraints as inference but with training-specific amplifications that make optimization dramatically more challenging. This table quantifies how each constraint dimension intensifies when transitioning from running pretrained models to adapting them locally. The factors are illustrative: memory and compute compare an update with inference, while the energy row includes repeated optimization steps toward convergence. These different counting units must not be treated as one universal per-sample multiplier. {#tbl-training-amplification}</p>\n<p>The memory row decomposes into four arrays (@fig-training-memory-amplifier). Panel (a) starts with <code>[EdgeTrainingMemoryStack.weights_mb_str]</code> of FP32 weights for a 10M-parameter model and adds <code>[EdgeTrainingMemoryStack.gradients_mb_str]</code> of gradients and <code>[EdgeTrainingMemoryStack.optimizer_mb_str]</code> of Adaptive Moment Estimation (Adam) state for its two moment arrays. Adding <code>[EdgeTrainingMemoryStack.activations_mb_str]</code> of assumed activation state brings the total to <code>[EdgeTrainingMemoryStack.total_mb_str]</code>, a <code>[EdgeTrainingMemoryStack.amplification_mult_str]</code> amplification over the weights. The same accounting spans the table's range. Weights, gradients, and Adam's two moments alone are four weight-sized arrays, the <code>[EdgeTrainingMemoryStack.floor_mult_str]</code> floor reached when saved activations are negligible. Activations between five and eight times the weight bytes carry the total from <code>[EdgeTrainingMemoryStack.amplification_mult_str]</code> to <code>[EdgeTrainingMemoryStack.ceiling_mult_str]</code>.</p>\n<p>Panel (b) holds the <code>[EdgeTrainingMemoryStack.amplification_mult_str]</code> proportions fixed across model scales from 1M to 100M parameters, so its constant ratio is an assumption rather than a finding. What it shows is the absolute cost of that ratio. The gap between weights and training stack grows from tens of megabytes at 1M parameters to gigabytes at 100M, so a model whose weights fit comfortably can still have a training stack that does not. Actual peak memory depends on optimizer choice, batch size, activation checkpointing, and how many layers are updated, and the <code>[EdgeTrainingMemoryStack.range_mult_str]</code> range describes these configurations rather than predicting any particular device.</p>\n<p>↪ The bytes per parameter that weights, gradients, and optimizer state occupy in mixed-precision Adam training are developed in @sec-appdx-dam-taxonomy-training-memory.</p>\n<h4 id=\"sec-9\" class=\"cs-h4\">Peak memory usage</h4>\n<p>Consider a smartphone keyboard that uses local gradient updates to adapt to a user's vocabulary and typing patterns. In the illustrative device profile, an update requires <code>[EdgeAdaptationTierProfile.keyboard_gradient_memory_low_mb_str]</code>--<code>[EdgeAdaptationTierProfile.keyboard_gradient_memory_high_mb_str]</code> for activations and optimizer state, against a background-memory allowance of <code>[EdgeAdaptationTierProfile.keyboard_background_budget_low_mb_str]</code>--<code>[EdgeAdaptationTierProfile.keyboard_background_budget_high_mb_str]</code>. The actual allowance depends on the operating system, device, and foreground workload. At the selected operating point, the update consumes <code>[EdgeAdaptationTierProfile.keyboard_memory_share_pct_str]</code> of that allowance before other application state is counted. The design decision is how much learning can fit in the remaining budget while preserving responsive typing; the device's total installed RAM does not answer it.</p>\n<p>Whether an update stays inside that allowance depends on peak live residency over the step, because tensors are allocated and released dynamically as execution proceeds. The peak occurs when weights, saved activations, gradients, optimizer state, and temporary workspace coexist, which need not happen at the same operation in every implementation. For the 10M-parameter model of @fig-training-memory-amplifier, <code>[EdgeTrainingMemoryStack.weights_mb_str]</code> of FP32 weights belong to a <code>[EdgeTrainingMemoryStack.total_mb_str]</code> training working set, of which <code>[EdgeTrainingMemoryStack.activations_mb_str]</code> is saved activations. Set against a smartphone's <code>[EdgeSmartphoneRamRecap.smartphone_ram_gb_str]</code> of installed RAM, that <code>[EdgeTrainingMemoryStack.total_mb_str]</code> working set looks modest, yet it exceeds even the top of the <code>[EdgeAdaptationTierProfile.keyboard_background_budget_low_mb_str]</code>--<code>[EdgeAdaptationTierProfile.keyboard_background_budget_high_mb_str]</code> allowance that the operating system grants a background task after itself and the foreground applications. Activation checkpointing (also called gradient checkpointing) discards selected intermediate activations and recomputes them during the backward pass [@chen2016training], the same trade that cuts activation memory in data-center training. It trades extra computation for lower activation storage, so its value depends on both the peak it removes and the additional time and energy the device can afford.</p>\n<p>↩ Activation checkpointing, which recomputes selected activations in the backward pass to cut activation memory at the cost of extra FLOPs, is established in @sec-distributed-training-systems-systems-compute-phase-forward-backward.</p>\n<p>That allowance, not installed RAM, is the ceiling for a working-memory budget that every adaptation strategy in this chapter must meet (@fig-tinytl-memory). The runtime stages frozen weights from nonvolatile flash into volatile working memory and reserves headroom below the physical device ceiling $\\DeviceMemoryCapacity$ for runtime and application state. Within the working-memory envelope $\\AdaptationPeakMemory$, four quantities contribute: let $\\ResidentWeightMemory$ be the backbone weights that must reside in working memory, $\\TrainableStateMemory$ the trainable parameters plus their gradients and optimizer state, $\\ActivationMemory(\\TimeInstant)$ the saved activation state, and $\\OperatorWorkspaceMemory(\\TimeInstant)$ operator workspace. With all terms counted in bytes and disjoint, the required working memory is</p>\n<p>$$ \\AdaptationPeakMemory= \\ResidentWeightMemory+ \\TrainableStateMemory+ \\max_t\\left[\\ActivationMemory(\\TimeInstant) + \\OperatorWorkspaceMemory(\\TimeInstant)\\right]. $$ {#eq-edge-adaptation-peak-memory}</p>\n<p>Admission then requires $\\AdaptationPeakMemory+ \\ReservedDeviceMemory\\le \\DeviceMemoryCapacity$, where $\\ReservedDeviceMemory$ holds the runtime, the operating system, and the foreground application; for a background task, $\\DeviceMemoryCapacity- \\ReservedDeviceMemory$ is the allowance just described. Weights stored in nonvolatile memory still consume deployment storage, and any staging buffers belong in $\\OperatorWorkspaceMemory(\\TimeInstant)$. The maximum must follow the actual execution schedule because activation and workspace peaks need not coincide. Each term is a separate lever, and the adaptation strategies of @sec-edge-intelligence-model-adaptation-6a82 differ in which term they shrink. Freezing weights removes their gradients and optimizer state from $\\TrainableStateMemory$, but it does not make the frozen base or every backward dependency disappear.</p>\n<p>An inference optimization therefore needs a second feasibility check before it is used for adaptation. Reducing stored weights may leave activations or optimizer state as the dominant cost. Selecting which parameters to train changes that accounting, linking the memory analysis to the adaptation choices that follow.</p>\n<p>Verify understanding of how training amplifies edge constraints:</p>\n<ul class=\"cs-list\">\n<li>[ ] Training memory blowup: Explain where the <code>[EdgeTrainingMemoryStack.floor_mult_str]</code> floor of the chapter's <code>[EdgeTrainingMemoryStack.range_mult_str]</code> training-memory range comes from, and which term pushes a configuration toward the upper end.</li>\n<li>[ ] Timing of the peak: Explain why peak training memory depends on when weights, saved activations, gradients, optimizer state, and workspace coexist, rather than on the sum of every tensor the update ever touches.</li>\n<li>[ ] Backward-pass OOM: Explain why a 10M parameter model can still trigger out-of-memory errors during the backward pass on a smartphone with <code>[EdgeAdaptationTierProfile.smartphone_ram_gb_str]</code> of RAM.</li>\n<li>[ ] Checkpointing energy: Evaluate the claim that activation checkpointing reduces the total energy consumed by on-device training.</li>\n</ul>\n<h3 id=\"sec-9\" class=\"cs-h3\">Model constraints</h3>\n<p>A model that fits comfortably on a smartphone can fail before a single backward pass on a smaller edge tier. MobileNetV2 requires approximately <code>[EdgeMobilenetSizing.mobilenetv2_alpha10_mb_str]</code> of storage in its standard configuration. That fits easily in smartphone RAM yet far exceeds the <code>[EdgeDeviceSpectrum.mcu_sram_kb_str]</code> of SRAM and <code>[EdgeDeviceSpectrum.arduino_flash_mb_str]</code> of flash storage on microcontrollers such as the Arduino Nano 33 BLE Sense. On such severely constrained platforms, even a single convolutional layer may exceed available RAM during training due to intermediate feature maps and gradient storage. Cloud-deployed models can span billions of parameters across multi-gigabyte memory budgets. Models intended for on-device learning must conform to tight limits on memory, storage, and compute, each tightened further by the factors of @tbl-training-amplification.</p>\n<p>: <strong>Arduino Nano 33 BLE Sense</strong>: With <code>[EdgeDeviceSpectrum.mcu_sram_kb_str]</code> SRAM, roughly <code>[EdgeDeviceSpectrum.memory_ratio_mult_str]</code> smaller than a flagship smartphone's <code>[EdgeDeviceSpectrum.flagship_ram_gb_str]</code>, a single <code>[EdgeMobilenetSizing.imagenet_rgb_shape_math]</code> RGB image occupies <code>[EdgeMobilenetSizing.imagenet_rgb_image_kb_str]</code> and consumes roughly <code>[EdgeMobilenetSizing.imagenet_rgb_sram_pct_str]</code> of available memory; activation and gradient storage add several more live tensors, and optimizer state can push the training footprint far beyond the inference footprint. A convolutional neural network (CNN) layer can therefore exceed SRAM during backpropagation even when its weights fit. Quantization can reduce this footprint, but feasibility also depends on input size, saved activations, and which parameters are updated.</p>\n<p>Training adds state whose size cannot be inferred from layer count alone. Backpropagation retains or recomputes intermediate activations, with storage determined by tensor shapes, precision, batch size, and the update schedule. The arithmetic grows quickly. A 10-layer convolutional model processing $64{\\times}64$ images saves feature maps of $64{\\times}64$ values per channel when its layers keep the input resolution. At FP32, every channel of every retained map then costs <code>[EdgeFeatureMapBytes.channel_bytes_str]</code> bytes, about <code>[EdgeFeatureMapBytes.channel_kb_str]</code>. Ten layers of even a few channels each therefore outgrow the <code>[EdgeDeviceSpectrum.mcu_sram_kb_str]</code> of microcontroller SRAM before a single gradient or optimizer value is stored. The relevant comparison is that peak against the memory available to learning after runtime and application reserves, which is why the techniques later in this chapter attack saved activations as well as trainable parameters.</p>\n<p>Model complexity also affects runtime energy consumption and thermal limits. In smartwatches or battery-powered wearables, sustained training can deplete the energy allowance or trigger thermal throttling even when its tensors fit in memory. Arithmetic precision alone does not determine feasibility; the update duration and measured power determine its energy cost. Benchmarks such as MLPerf Tiny provide small quantized inference targets for constrained devices [@banbury2021mlperftiny]. On-device adaptation techniques address the additional training cost by freezing most parameters, reducing activation storage, or selecting sparse update sets [@cai2020tinytl; @kwon2024tinytrain].</p>\n<p>Battery and thermal constraints also determine when learning can run. The illustrative smartphone profile uses a sustained processing envelope of <code>[EdgeMobilePowerEnvelope.sustained_range_str]</code> and brief bursts of <code>[EdgeMobilePowerEnvelope.burst_range_str]</code>. An update that fits during an idle interval may exceed the available headroom when foreground work starts. Charging supplies energy, but the runtime must still monitor heat and contention, reducing the update duty cycle or suspending learning when limits are approached. An overnight idle-and-charging policy provides one candidate window; measured device conditions determine whether that window remains usable.</p>\n<p>These constraints make adaptation feasibility part of architecture selection. When the base model exceeds device capacity, partitioning, quantization, offloading, or a smaller architecture can change the deployment footprint, each with its own execution cost. INT8 or INT4 weights often decide whether the base model fits at all, and 1-bit weights cut weight bytes 16$\\times$ relative to FP16 (32$\\times$ relative to FP32) before scale metadata and activations are counted. Fitting the forward path is the starting point; quantization support and selective-update costs must then be established for the training path.</p>\n<h3 id=\"sec-10\" class=\"cs-h3\">Data constraints</h3>\n<p>Fitting the model and its update state into memory solves only the capacity side of the problem, because the available local data still sets how much a fitted update can actually learn. A fitness tracker that records thousands of accelerometer readings across a workout may receive only a single user-supplied activity label, or it may record from a sensor whose calibration has drifted. Unlike the curated datasets used in cloud training, edge data is locally collected, temporally sparse, and often unlabeled. Because sampling frequency, windowing, and temporal correlation can collapse an entire session of correlated sensor readings into a single independent observation, the learning policy must budget for usable supervision rather than raw stored bytes.</p>\n<p>On-device data is also frequently non-IID [@zhao2018federated], as when a voice assistant deployed across households encounters variation in accents, languages, speaking styles, and command patterns while smartphone keyboards observe individual typing patterns, autocorrect preferences, and multilingual usage. Because these local distributions are statistically skewed, sparse, and continually shifting, they violate the assumptions underlying many standard optimization techniques, so training on them without adjustment can lead to unstable convergence or degraded accuracy on earlier tasks.</p>\n<p>Label scarcity compounds the distribution problem. Most edge-collected data is unlabeled by default, requiring systems to learn from weak or implicit supervision signals. A smartphone camera may capture thousands of images throughout the day, but only a few are associated with meaningful user actions (tagging, favoriting, or sharing) that could serve as implicit labels. In many applications, including anomaly detection in sensor data and gesture recognition adaptation, explicit labels may be entirely unavailable, making traditional supervised learning infeasible without alternative methods for weak supervision or unsupervised adaptation.</p>\n<p>Data quality introduces further challenges. Environmental sensors or automotive ECUs can experience calibration changes, interference, or mechanical wear that corrupt or shift input signals. An adaptation loop may learn from those changes as if they represented useful new behavior. Local input checks and validated outcome signals must distinguish sensor faults from changes the model should learn, especially when raw observations are unavailable for central inspection.</p>\n<p>Privacy and security requirements can further restrict which examples may be retained or shared. Keeping health data, personal communications, or behavioral traces on the device narrows raw-data exposure, but local storage and transmitted updates remain sensitive. The learning design must specify access, retention, and permitted disclosures alongside the data needed for adaptation and validation.</p>\n<h3 id=\"sec-11\" class=\"cs-h3\">Compute constraints</h3>\n<p>Even when a compact model and validated local examples are in place, the processor that runs inference may not be able to train them: a mobile neural processing unit (NPU) advertised at tens of TOPS for INT8 inference can lack backward-pass or optimizer kernels entirely. An on-device update must then fall back to the CPU and can run far slower and hotter than the chip's inference rating suggests. Across the edge hardware spectrum, from microcontrollers like the STM32F4 and ESP32, through mobile processors with dedicated AI accelerators (Apple Neural Engine, Qualcomm Hexagon, Google Tensor), to high-capability edge modules, inference ratings measure forward-pass throughput on fixed weights. Training workloads add backward and optimizer operations with very different execution paths.</p>\n<p>Because an inference rating does not measure this backward path, feasibility depends on tracing where each update operator actually executes. Backpropagation reads saved or recomputed activations, produces gradients, and updates parameters and optimizer state. These operations add memory traffic, with the amount determined by the trainable subset and execution schedule. A specialized accelerator can expand the inference budget without executing any backward operator. The feasibility test is therefore the actual update path. It identifies which processor runs each backward and optimizer operator, including any fallback to the CPU or GPU, and measures time, memory, and energy for that path under foreground load. Each device class that follows gets this update-path test, applied to its own memory, operators, and power, rather than a verdict read from its inference rating.</p>\n<p>At the most constrained end, devices such as the STM32F4 or ESP32-S3 microcontrollers offer only a few hundred kilobytes of SRAM and limited compute and power budgets [@warden2020tinyml]. Although these families include single-precision floating-point support, practical ML deployments commonly rely on quantized or fixed-point kernels for efficiency. Libraries like CMSIS-NN [@lai2018cmsis] provide optimized neural network kernels for Arm Cortex-M processors, achieving 4.6$\\times$ runtime improvement through fixed-point arithmetic and single instruction, multiple data optimizations. These severe limitations preclude conventional deep learning libraries and require models designed for quantized arithmetic and minimal runtime memory allocation. Quantization-aware training can prepare models for efficient quantized inference. Executing local updates requires a separately supported training path, potentially with selective updates, quantized gradients, or a compact floating-point working set.</p>\n<p>: <strong>STM32F4 microcontroller</strong>: With <code>[EdgeMobilenetSizing.stm32_sram_kb_str]</code> SRAM, a <code>[EdgeMobilenetSizing.stm32_clock_mhz_str]</code> clock speed, and a single-precision floating-point unit, the main constraint is not the absence of floating point but the tiny memory and energy envelope. A dense layer with <code>[EdgeMobilenetSizing.stm32_hidden_inputs_str]</code> input features and <code>[EdgeMobilenetSizing.stm32_hidden_outputs_str]</code> hidden units requires approximately <code>[EdgeMobilenetSizing.stm32_hidden_kb_str]</code> for weights and biases in FP32, consuming about <code>[EdgeMobilenetSizing.stm32_hidden_sram_pct_str]</code> of total SRAM before accounting for activations or gradients. Local updates must therefore fit around the device's primary workload and power budget, and INT8 or fixed-point kernels remain preferable when accuracy allows.</p>\n<p>: <strong>Quantization-aware training (QAT)</strong>: Simulates quantization during training to adapt the model to low-precision inference [@jacob2018; @krishnamoorthi2018quantizing]. Fake-quantization operations commonly retain floating-point training tensors, so QAT does not itself imply integer backward kernels or a smaller training-state budget. On-device adaptation must separately establish supported update arithmetic, state storage, and measured energy costs.</p>\n<p>Microcontroller memory rules out training configurations whose live tensors exceed SRAM, rather than every convolutional model. Feasibility depends on tensor shapes, update scope, numerical representation, and the compiled execution schedule. Plain stochastic gradient descent (SGD) reduces optimizer state compared with methods that retain additional moment arrays. Non-neural adaptation, such as $\\ClusterCount$-means clustering, offers a different way to update local centroids for sensor analysis. The method and its arithmetic must still fit the available memory and produce a validated improvement; neither a simple optimizer nor integer execution establishes that result alone.</p>\n<p>: <strong>SGD (stochastic gradient descent)</strong>: Plain SGD keeps parameters and gradients, two parameter-sized arrays where Adam keeps four, so its lower state cost must still be weighed against the updates needed to reach the quality target.</p>\n<p>Moving up the computational hierarchy, mobile-class hardware represents improvement but still operates under severe constraints. Platforms including the Qualcomm Snapdragon, Apple Neural Engine, and the Google Tensor system-on-chip (SoC) provide significantly more compute power than microcontrollers, often featuring dedicated AI accelerators and optimized support for 8-bit or mixed-precision matrix operations. These accelerators offer dedicated matrix multiplication units, on-chip memory hierarchies, and power management features specifically designed for neural network inference, with varying support for local training workloads. While these platforms can support more sophisticated training routines, including full backpropagation over compact models, they still fall far short of the computational throughput and memory bandwidth available in centralized data centers. Training a lightweight transformer on a smartphone, for instance, is technically feasible but must be tightly bounded in both time and energy to avoid degrading the user experience.</p>\n<p>: <strong>Apple Neural Engine</strong>: Apple's dedicated neural accelerator, first shipped in the A11 Bionic in 2017; its rating growth through the A17 Pro is tracked in @fig-edge-npu-tops. Which of an update's operators actually reach it, rather than falling back to the CPU or GPU, is the runtime question worked through in @sec-edge-intelligence-mobile-ai-accelerator-optimization-67fe.</p>\n<p>Hardware capability contributes to on-device adaptation feasibility alongside the algorithm and runtime. The mobile accelerator scaling tracked in @fig-edge-npu-tops shows Apple's stated rating climbing from under 1 TOPS on the A11 Bionic to nearly 35 TOPS on the A17 Pro, a step in 2023 that may partly reflect a change in rating precision rather than in the hardware alone. These peak ratings concern forward inference. A training budget must also account for backward operators and the runtime that dispatches them.</p>\n<p>The gap between running a model on a generic mobile CPU and on a dedicated NPU is best understood as a \"silicon dividend\" rather than a marginal speedup. Published NPU profiles vary by silicon generation and workload, so this callout uses explicit scenario assumptions rather than a benchmark: a <code>[EdgeNpuSpeedup.npu_speedup_mult_str]</code> latency improvement and a <code>[EdgeNpuSpeedup.npu_energy_gain_mult_str]</code> energy-efficiency improvement relative to the modeled MobileNetV2 baseline (<code>[EdgeNpuSpeedup.npu_cpu_lat_ms_str]</code> per inference on the CPU).</p>\n<p>The dividend belongs to the operators the NPU actually executes. An update adds backward and optimizer work that costs roughly one to two more forward passes, because the backward pass computes gradients with respect to both activations and weights. If the runtime cannot place those operators on the NPU, they fall back to the CPU. The forward pass may still collect its <code>[EdgeNpuSpeedup.npu_speedup_mult_str]</code> dividend, but CPU backward work and transfers between processors can dominate the complete update. The resulting speed and energy depend on that mixed execution path. An inference-dominated product and an adaptation-dominated one can therefore see very different returns from the same silicon, and only the traced update path says which case a deployment is in.</p>\n<p>Even on the forward inference path that those ratings describe, published Syntiant Core 2 and STM32N6 results illustrate the cost of inference on dedicated neural processors in @fig-edge-inference-landscape [@syntiant2023mlperf; @bartoli2025benchmarking]. The plotted observations span approximately <code>[EdgeInferenceSpan.energy_span_mult_str]</code> in reported energy, from Syntiant keyword spotting to STM32N6 visual wake word detection. The workloads and measurement boundaries differ: the STM32N6 results include pre-inference and post-inference work, while Syntiant reports MLPerf Tiny benchmark results. The span therefore does not establish a matched-task hardware-efficiency ranking. Energy per inference does not determine battery lifetime on its own, because inference frequency, sleep power, sensing, radio use, and usable battery capacity also enter that budget.</p>\n<p>For a learning device the figure sets the scale against which an update must be judged. The plotted evaluations cost tens to hundreds of microjoules, while each second of training inside the <code>[EdgeMobilePowerEnvelope.sustained_range_str]</code> sustained envelope spends joules, more than a thousand keyword-spotting evaluations at the plotted 30 to 160 $\\Glyph{\\mu}$J. An update can therefore be a substantial energy cost, but its share of the device budget depends on how often training and inference run. Both paths need measurement over the same operating period.</p>\n<p>These computational limitations become especially acute in real-time or battery-operated systems. There, the foreground latency budgets of @sec-edge-intelligence-alternative-approaches-decision-criteria-bd36 bound how much interference local training may cause, although training itself need not finish within an inference deadline. Training also has different memory access patterns from inference. Gradient computation, activation storage, and optimizer updates add memory traffic whose magnitude depends on which parameters train and which intermediate states are retained. These transfers can create bottlenecks that pure computational metrics do not capture. Hardware designs can address these challenges with specialized support, but a particular device must expose that support through its training runtime. Mixed-precision datapaths may execute different formats in forward and backward kernels when those kernels exist. Sparse-update savings require an execution path that can actually skip the selected work; zero gradients alone do not establish reduced hardware cost (@sec-edge-intelligence-sparse-updates-879b). Near-memory compute architectures reduce data movement costs by performing gradient updates directly adjacent to weight storage, addressing the memory bandwidth bottleneck. Most edge accelerators, however, remain optimized for inference, which leaves the backward and optimizer operators of local adaptation as an open hardware-software co-design problem.</p>\n<p>: <strong>Near-memory computing</strong>: Places processing elements adjacent to or within memory arrays to cut the data movement that often dominates arithmetic energy [@horowitz2014; @kwon2019], which could make write-heavy on-device backpropagation more practical.</p>\n<h4 id=\"sec-12\" class=\"cs-h4\">The mobile memory wall</h4>\n<p>Rising NPU ratings tempt designers to read device capability from TOPS, but every byte a local update moves crosses the same memory interface as inference traffic, and an update moves far more bytes than an inference. Counting them for the 10M-parameter model of @fig-training-memory-amplifier, under the simplest assumption that each tensor crosses DRAM once per use with no cache reuse, shows how far. The forward pass reads the weights and writes the saved activations, and the backward pass rereads the activations and weights and writes the gradients. An Adam step then reads the weights, gradients, and both moments and writes the weights and moments back. One update step moves about <code>[EdgeUpdateTraffic.step_traffic_mb_str]</code>, <code>[EdgeUpdateTraffic.traffic_ratio_mult_str]</code> the weight bytes a single inference reads. At the <code>[EdgeH100BwRecap.a17_mem_bw_gb_per_s_str]</code> peak bandwidth of an A17 Pro, that traffic alone needs about <code>[EdgeUpdateTraffic.step_floor_ms_str]</code> per step before any arithmetic is counted.</p>\n<p>Mobile language-model decode, the case already met as the autoregressive bottleneck (principle \\ref{pri-autoregressive-bottleneck}), shows the same ceiling at its starkest, since decode pressure falls on memory and interconnect rather than peak arithmetic throughput [@ma2026challenges]. The interface itself is narrow by data-center standards. Data-center HBM3 on an H100 provides <code>[EdgeH100BwRecap.h100_mem_bw_gb_per_s_str]</code> of peak unidirectional DRAM memory bandwidth. Flagship mobile systems sit near <code>[EdgeH100BwRecap.a17_mem_bw_gb_per_s_str]</code> (A17 Pro, LPDDR5) to <code>[EdgeH100BwRecap.sd8g3_mem_bw_gb_per_s_str]</code> (Snapdragon 8 Gen 3, LPDDR5X), a gap of roughly <code>[EdgeH100BwRecap.ratio_low_str]</code>--<code>[EdgeH100BwRecap.ratio_high_mult_str]</code>.</p>\n<p>↩ The memory wall, the widening gap between arithmetic throughput and the memory bandwidth that feeds it, is established in @sec-compute-memory-wall.</p>\n<p>The ratio of bandwidth-bound times equals this bandwidth ratio only when both devices move the same bytes and sustain the same fraction of their peak bandwidth. Precision, batching, cache reuse, and runtime overhead all move the measured ratio. Low-precision weights attack that ceiling when weight traffic is what binds. Storing FP32 weights at 4 bits, for example, reduces weight bytes by 8$\\times$ and reduces that component of traffic by the same factor if the runtime consumes the compressed representation efficiently. It does not increase physical bandwidth or remove cache-state traffic and decoding overhead, and the precision choice must satisfy both quality and measured latency requirements. For an on-device update the relief is smaller still. In the count above, the three weight reads (forward, backward, and optimizer) are only about <code>[EdgeUpdateTraffic.weight_read_share_pct_str]</code> of the step's traffic, and a quantized base leaves the saved activations, gradients, and optimizer state that make up the rest untouched.</p>\n<p>Small-batch decode is the familiar memory-bound case. Each token rereads weights too large to stay in cache, so the data term $(\\DataVolume / \\Bandwidth)$ of the single-machine iron law sets its time, and sustained bandwidth and bytes per token predict it better than peak TOPS. The roofline recap in @sec-appdx-dam-taxonomy-roofline works that decode example. Local adaptation needs the same comparison applied to its own forward, backward, and optimizer traffic, counted per update step rather than per token, where the count above puts it at about <code>[EdgeUpdateTraffic.step_traffic_mb_str]</code>.</p>\n<h4 id=\"sec-12\" class=\"cs-h4\">Memory hierarchy optimization</h4>\n<p>Capacity is the question @eq-edge-adaptation-peak-memory already answers. Quantization, pruning, and distillation can each shrink the resident and trainable terms of that working set [@jacob2018; @han2015deep; @hinton2015distilling], but their gains are workload-specific and do not combine automatically, so they must be validated together against the same budget. Once the working set fits, capacity says nothing about the second question, which is how much traffic the update drives through the hierarchy and how much of that traffic the caches can absorb. Operator tiling and memory layout aim to reuse active tensor blocks before eviction, while batch size controls activation storage and available parallelism. Gradient accumulation can limit the microbatch working set, but it also retains accumulation state and adds accesses, so its effect on traffic must be measured.</p>\n<p>Training adds gradient and optimizer traffic to the tensor reads and writes already required by inference. When these transfers saturate memory bandwidth, additional arithmetic capacity cannot shorten the update. The activation checkpointing introduced with peak memory usage shows why capacity and traffic must be counted separately. Recomputing activations lowers the peak footprint while adding forward work and its memory reads, so capacity can improve as traffic and energy rise. Mixed-precision training changes bytes per stored tensor, but numerical stability and supported backward kernels determine whether the smaller representation is useful. Capacity, traffic, and update time therefore need separate measurements.</p>\n<h4 id=\"sec-12\" class=\"cs-h4\">Mobile AI accelerator optimization</h4>\n<p>Accelerator choice depends on the training primitives that the device's software stack exposes. Apple Neural Engine, Qualcomm Hexagon DSP, and Google Tensor devices have different compiler and runtime contracts, so the same update can follow different paths on each. A useful execution plan identifies where feature extraction, head or adapter training, and optimizer updates run. A dedicated engine may accelerate the frozen forward path while another processor handles learning, but transfers and duplicate representations then enter the cost. The supported operators and data movement must be established for the actual device and runtime version.</p>\n<p>A local update may therefore execute on a CPU or GPU even when inference uses the dedicated neural accelerator. On a real device, the update-path test that opened the discussion of compute constraints becomes a short procedure.</p>\n<ol class=\"cs-list\">\n<li>List the update's operators in execution order: the forward pass, each backward operator that the trainable subset requires, and the optimizer step.</li>\n<li>For each operator, record the processor the runtime actually places it on, noting every fallback from the neural engine to the CPU or GPU.</li>\n<li>At each change of processor, add the transfer and any duplicate tensor representation to the update's memory and traffic accounting.</li>\n<li>Measure time, peak memory, and energy for the complete traced path while a representative foreground workload runs.</li>\n<li>Feed those measurements into the peak-memory budget of @eq-edge-adaptation-peak-memory and the admission test of @eq-edge-background-admission that follows, which together decide whether the update may run.</li>\n</ol>\n<p>Mixed-precision datapaths, sparse-update support, and near-memory compute can reduce those costs, but none of them is a prerequisite for training. What matters is whether the available runtime can execute the required operators within the device envelope.</p>\n<h3 id=\"sec-12\" class=\"cs-h3\">Energy, heat, and background admission</h3>\n<p>An update path that fits in memory and runs on supported kernels still fails if 30 minutes of background backpropagation noticeably drains the battery, warms the handset in the user's pocket, or delays foreground touch responses. Because energy draw, thermal dissipation, and shared-processor contention reach the user directly, a mobile power budget constrains both the model complexity a device can train and the schedule on which background learning is admitted.</p>\n<p><strong>Problem</strong>: A team is designing a background fine-tuning job for a personalized voice assistant on a smartphone. Run unconstrained, the training job draws <code>[EdgeBattery.battery_power_w_str]</code>, above the <code>[EdgeMobilePowerEnvelope.sustained_range_str]</code> sustained envelope given earlier, and takes <code>[EdgeBattery.battery_duration_min_str]</code> to complete. If the phone has a <code>[EdgeBattery.battery_total_wh_str]</code> battery, how much of the user's battery will this \"invisible\" update consume?</p>\n<p><strong>Math</strong>:</p>\n<ol class=\"cs-list\">\n<li>Total energy: <code>[EdgeBattery.battery_power_w_str]</code> $\\times$ <code>[EdgeBattery.battery_duration_h_str]</code> = <code>[EdgeBattery.battery_energy_wh_str]</code>.</li>\n<li><strong>Battery impact</strong>: <code>[EdgeBattery.battery_energy_wh_str]</code>/<code>[EdgeBattery.battery_total_wh_str]</code> = <code>[EdgeBattery.battery_drain_pct_str]</code>.</li>\n</ol>\n<p><strong>Systems insight</strong>: Consuming <code>[EdgeBattery.battery_drain_pct_str]</code> of a user's battery for one background task makes update frequency a deployment decision. That energy cannot be translated into a fixed amount of screen-on time without specifying the foreground workload. A policy of <strong>opportunistic scheduling</strong> admits learning when device conditions permit it; a federated policy might require charging, Wi-Fi, and thermal headroom. Charging supplies energy but does not remove heat or foreground contention, so those constraints still need separate checks.</p>\n<p>This battery calculation is the local edge-learning version of a broader energy constraint. Training must satisfy the user's energy budget in addition to the model's accuracy target. A production design therefore has to account for energy at scheduling time, compare local computation against communication cost, and defer learning when the user's device cannot absorb the update.</p>\n<p>That decision can be expressed as a background-work admission condition. Let $\\AdaptationWindowEnergy$ be the predicted energy for one adaptation window, $\\AdaptationEnergyAllowance$ the energy the policy permits before the next charging opportunity, $\\DevicePower$ the current sustained power, $\\AdaptationPowerIncrement$ the adaptation increment, and $\\ThermalPowerLimit$ the thermally sustainable limit. Let $\\ForegroundLatency$ be measured foreground latency, $\\AdaptationLatencyIncrease$ the worst-case latency increase under concurrent adaptation, and $\\CompletionDeadline$ the foreground deadline. The runtime admits an update only if</p>\n<p>$$ \\AdaptationWindowEnergy\\le \\AdaptationEnergyAllowance\\quad \\land \\quad \\DevicePower+ \\AdaptationPowerIncrement\\le \\ThermalPowerLimit\\quad \\land \\quad \\ForegroundLatency+ \\AdaptationLatencyIncrease\\le \\CompletionDeadline. $$ {#eq-edge-background-admission}</p>\n<p>Charging can enlarge the energy allowance, but it does not waive the thermal or foreground-latency tests. The quantities must come from device- and workload-specific profiling, and the runtime must revoke admission when the measured envelope changes. Shorter update windows, a lower duty cycle, or a smaller trainable parameter set can make a rejected update feasible; allowing background learning to consume the foreground deadline cannot.</p>\n<p>The same test also decides who teaches a shared model. Passing it correlates with hardware class, charging habits, and connectivity, so devices that are old, rarely charged, or thermally tight contribute few updates. As a result, the population a federated model learns from is the admitted population rather than the deployed one (principle \\ref{pri-participation-selects-population}). The admission policy that protects each device is therefore also a sampling policy, and @sec-edge-intelligence-client-scheduling-f675 measures the skew it creates.</p>\n<p><strong>Scenario</strong>: Consider a mobile keyboard that trains its next-word predictor locally and contributes updates to a shared model through federated averaging [@mcmahan2017communication].</p>\n<p><strong>Diagnosis</strong>: In the keyboard profile of @sec-edge-intelligence-peak-memory-usage-a2ae, one local update needs <code>[EdgeAdaptationTierProfile.keyboard_gradient_memory_low_mb_str]</code>--<code>[EdgeAdaptationTierProfile.keyboard_gradient_memory_high_mb_str]</code> of working memory against a background allowance of <code>[EdgeAdaptationTierProfile.keyboard_background_budget_low_mb_str]</code>--<code>[EdgeAdaptationTierProfile.keyboard_background_budget_high_mb_str]</code>. At the selected operating point, the update alone therefore claims <code>[EdgeAdaptationTierProfile.keyboard_memory_share_pct_str]</code> of the allowance before the keyboard's own state is counted, and the resident weights in $\\AdaptationPeakMemory$ claim more. Exceeding the allowance risks process eviction mid-update. Energy is the second constraint. An unconstrained job like the one in notebook \\ref{nbk-edge-intelligence-battery-drain-cost-edge-learning} would take <code>[EdgeBattery.battery_drain_pct_str]</code> of the battery, more than a policy that protects the user's charge is likely to grant as $\\AdaptationEnergyAllowance$ in @eq-edge-background-admission while the phone runs on battery. The pipeline therefore admits training only when the device is idle, charging, and on Wi-Fi, and it quantizes update vectors to shrink the transmitted payload $\\DataVolume$.</p>\n<p><strong>Systems lesson</strong>: A federated keyboard must satisfy all three terms of @eq-edge-background-admission (energy $\\AdaptationWindowEnergy\\le \\AdaptationEnergyAllowance$, sustained power under $\\ThermalPowerLimit$, and typing latency under its deadline), fit $\\AdaptationPeakMemory$ within its memory allowance, respect uplink bandwidth $\\Bandwidth$, and meet its declared privacy guarantees together. Differential privacy adds a specific release guarantee and its associated costs; it is not implied by keeping raw text local.</p>\n<h3 id=\"sec-13\" class=\"cs-h3\">Matching edge constraints to adaptation pillars</h3>\n<p>Memory, data, compute, and admission constraints act on the same update window at once. Shrinking trainable parameters so an update fits in RAM still fails if local supervision is too sparse to guide the step or if intermittent connectivity drops the device from every federated round. The constraint analysis therefore yields three linked design decisions. The training amplification of @tbl-training-amplification motivates measuring the update footprint against @eq-edge-background-admission and choosing which parameters to adapt. Information scarcity, including limited local datasets, non-IID distributions, restrictions on data sharing, and minimal supervision, motivates data efficiency methods that reuse available evidence. When shared learning is useful, device heterogeneity and intermittent availability motivate federated coordination with explicit validation and privacy controls. Each pillar answers a different constraint within the same deployment budget and brings its own techniques to that answer (@tbl-constraint-solution-mapping).</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Constraint category</strong></th><th><strong>Key challenges</strong></th><th><strong>Solution approach</strong></th></tr></thead><tbody>\n<tr><td><strong>Resource Amplification</strong></td><td>• Training workloads (4--12$\\times$ memory)&lt;br&gt;• Memory limitations&lt;br&gt;• Power constraints</td><td><strong>Model Adaptation</strong>&lt;br&gt;• Parameter-efficient updates&lt;br&gt;• Selective layer fine-tuning&lt;br&gt;• Low-rank adaptations</td></tr>\n<tr><td><strong>Information Scarcity</strong></td><td>• Limited local datasets&lt;br&gt;• Non-IID distributions&lt;br&gt;• Privacy restrictions</td><td><strong>Data Efficiency</strong>&lt;br&gt;• Few-shot and streaming adaptation&lt;br&gt;• Experience replay&lt;br&gt;• Compressed representations</td></tr>\n<tr><td><strong>Coordination Challenges</strong></td><td>• Device heterogeneity&lt;br&gt;• Intermittent connectivity&lt;br&gt;• Distributed validation complexity&lt;br&gt;• Scalability requirements</td><td><strong>Federated Coordination</strong>&lt;br&gt;• Federated averaging and asynchronous aggregation&lt;br&gt;• Secure aggregation and differential privacy&lt;br&gt;• Client selection and straggler handling</td></tr>\n</tbody></table></div>\n<p>: <strong>Constraint-Solution Mapping</strong>: The three fundamental constraint categories in on-device learning each drive corresponding solution approaches through direct necessity. {#tbl-constraint-solution-mapping tbl-colwidths=\"[24,34,42]\"}</p>\n<h2 id=\"sec-14\" class=\"cs-h2\">Model Adaptation</h2>\n<p>The first pillar of that mapping is model adaptation, which bounds the trainable state before local data scarcity or fleet coordination even enters the budget. The 10M-parameter model of @fig-training-memory-amplifier is an inference candidate for a smartwatch with <code>[EdgeAdaptationTierProfile.wearable_system_memory_mb_str]</code> of total system memory, because its FP32 weights occupy <code>[EdgeTrainingMemoryStack.weights_mb_str]</code>. Training every parameter would need the full <code>[EdgeTrainingMemoryStack.total_mb_str]</code> stack, most of the watch's memory before its operating system and foreground application take their share. The weight footprint alone does not establish inference fit; activation buffers, runtime workspace, and foreground reserve must also fit. Full-model training leaves much less room for that remaining state. The system therefore trains only a compact, strategically placed parameter set and, where it can, also shrinks the activations that the backward pass must keep. Resource-efficient model adaptation then determines both the local work a device can complete and the shared update format the fleet can aggregate.</p>\n<p>The engineering choice balances adaptation expressivity against resource consumption. Full fine-tuning exposes all parameters to learning and can fit sufficiently small models; retaining a fixed model can be adequate when local context already supplies the needed personalization. Between these choices, selective updates offer smaller training state. The device resource envelope determines which candidates fit: a wearable-class device with <code>[EdgeAdaptationTierProfile.tiny_wearable_ram_mb_str]</code> RAM has a different budget from a smartphone with <code>[EdgeAdaptationTierProfile.smartphone_ram_gb_str]</code>. The local variation then determines how much trainable capacity is useful. Bias updates may capture calibration changes, while shifts requiring new features need a richer update space. Runtime support, inference cost, shared-update compatibility, and rollback determine whether the candidate can enter the deployed system.</p>\n<p>The selection of adaptation techniques follows this matching logic, from weight freezing (@sec-edge-intelligence-weight-freezing-3407) to structured and sparse updates (@sec-edge-intelligence-sparse-updates-879b). Their order of presentation is not a universal ranking of cost or expressivity; placement, update size, and runtime support determine those properties. Building on the resource accounting in @sec-edge-intelligence-design-constraints-c776, the target is the smallest update space that captures the local variation: <em>preserve what works globally, adapt what matters locally</em>. Weight freezing restricts training to selected existing parameters, such as bias terms or final layers, whereas structured updates add low-rank or residual components to a frozen base and sparse updates select existing parameters according to their adaptation value and measured cost. Each choice must preserve enough useful capacity while fitting the device's update budget.</p>\n<h3 id=\"sec-15\" class=\"cs-h3\">Transfer as the premise</h3>\n<p>All three adaptation families work only because the device does not learn its representation from scratch. Training a feature extractor from random initialization on a few dozen noisy phone interactions would overfit immediately and exhaust the energy allowance before learning anything generalizable. Instead, every local update that fits an edge budget relies on knowledge transfer, in which a cloud-pretrained model supplies representations useful for a new task or domain. Reusing those representations reduces what the device must learn from local examples, and the benefit depends on what the tasks share. A model pretrained in the cloud can adapt with limited local updates when its representations retain the distinctions the new task requires. If a new input modality or objective requires features the base model does not provide, a small local update may be insufficient.</p>\n<p>Transfer is therefore the premise of the adaptation methods that follow. When pretrained representations carry the distinctions a personal typing vocabulary, an individual gait, or a drifting sensor needs, bias-only updates, adapters, and head-only training (which retrains only the final classification layer) can learn a small correction while freezing most of the network. When that premise fails, head-only adaptation cannot recover distinctions absent from its fixed features. Earlier-layer adapters or broader updates may learn them, but their added state, computation, and data requirements must fit the device budget.</p>\n<h3 id=\"sec-16\" class=\"cs-h3\">Weight freezing</h3>\n<p>When pretrained features already capture the structure of the task, the most direct way to shrink $\\TrainableStateMemory$ in @eq-edge-adaptation-peak-memory is to freeze the majority of a model's parameters and adapt only a minimal subset. <strong>Bias-only adaptation</strong> holds all weights fixed and updates only the bias terms (scalar offsets applied after linear or convolutional layers). The constraint reduces trainable parameters by 100--1000$\\times$, removes the weight gradients and their optimizer state from $\\TrainableStateMemory$, and helps mitigate overfitting when training data is sparse or noisy.</p>\n<p>Consider a standard neural network layer: $$ \\LayerOutputVector= \\WeightMatrix\\LayerInputVector+ \\BiasVector$$ where $\\WeightMatrix\\in \\mathbb{R}^{\\WeightMatrixRowCount\\times \\WeightMatrixColumnCount}$ is the weight matrix, $\\BiasVector\\in \\mathbb{R}^\\WeightMatrixRowCount$ is the bias vector, and $\\LayerInputVector\\in \\mathbb{R}^\\WeightMatrixColumnCount$ is the input. In full training, gradients are computed and applied to both $\\WeightMatrix$ and $\\BiasVector$. In bias-only adaptation, the system freezes the weight tensor ($\\FiniteChange\\WeightMatrix= \\ZeroMatrix$) and computes gradients exclusively for the bias: $$ \\WeightMatrix\\leftarrow \\WeightMatrix, \\quad \\BiasVector\\leftarrow \\BiasVector- \\LearningRate\\frac{\\partial \\LossFunction}{\\partial \\BiasVector} $$</p>\n<p>This reduces the number of stored gradients and optimizer states, enabling training to proceed under memory-constrained conditions. The smaller trainable state helps only if the device also supports the arithmetic and activation schedule required by the update. In the bias-only setup of @lst-bias-adaptation, all convolutional and fully connected weights remain frozen, and only the bias terms adapt to local data.</p>\n<pre class=\"cs-code\"><code># Freeze all parameters\nfor name, param in model.named_parameters():\n    param.requires_grad = False\n\n# Enable gradients for bias parameters only\nfor name, param in model.named_parameters():\n    if &quot;bias&quot; in name:\n        param.requires_grad = True</code></pre>\n<p>This pattern restricts optimizer updates to bias terms. What it saves, and what it does not, follows from the two derivatives of the layer above. The weight gradient $\\partial \\LossFunction/\\partial \\WeightMatrix= (\\partial \\LossFunction/\\partial \\LayerOutputVector)\\,\\LayerInputVector^T$ needs the layer's saved input $\\LayerInputVector$, whereas the bias gradient $\\partial \\LossFunction/\\partial \\BiasVector= \\partial \\LossFunction/\\partial \\LayerOutputVector$ needs only the gradient arriving from above. A frozen linear layer therefore no longer has to keep its input for its own sake. Reaching a bias in an earlier layer, however, still sends the gradient back through every later layer. Each nonlinearity or normalization on that path needs its own saved state (a ReLU needs at least the mask of which inputs were positive). Freezing parameters thus shrinks $\\TrainableStateMemory$ without eliminating backward computation or all saved activation state. This is valuable when adapting pretrained models to user-specific or device-local data where the core representations remain relevant but require calibration.</p>\n<p>Tiny Transfer Learning (TinyTL) [@cai2020tinytl] targets the activation term of @eq-edge-adaptation-peak-memory as well as trainable state. It builds on the derivative argument above. Because frozen linear and convolutional layers drop their saved inputs, the remaining activation footprint comes from nonlinearities, normalization layers, and any trainable side-paths added to recover expressivity. Adding a standard residual adapter beside a frozen block would require saving that block's full-resolution input feature map to compute the adapter's weight gradients, undoing the memory saving. TinyTL avoids that trap with lite residual modules that downsample the input feature map and project it to a narrow channel width before applying trainable convolutions, so the backward pass caches only a small low-resolution tensor at each block alongside compact group-normalization and activation state.</p>\n<p>In a side-by-side architectural comparison of that mechanism, full fine-tuning (Panel A of @fig-tinytl-architecture) computes gradients for every intermediate layer weight and caches every block's full input map, whereas TinyTL (Panel B) freezes the convolutional backbone (gray blocks) and confines parameter updates to the downsampled lite residual side-paths and bias vectors $\\BiasVector$ (blue blocks). The dashed backward-pass arrow spans the full network depth in both architectures. TinyTL's memory reduction therefore stems not from truncating the backward pass, but from replacing full-resolution saved feature maps with the much smaller inputs of the lite residual modules.</p>\n<p>The memory reduction is useful only when the frozen backbone remains expressive enough for the downstream task. The bias terms allow for minor but meaningful shifts in model behavior, particularly for personalization tasks. When domain shift is more significant, TinyTL can optionally incorporate small residual adapters to improve expressivity, all while preserving the system's tight memory and energy profile.</p>\n<p>TinyTL demonstrates that reducing saved activation state can matter more than reducing the number of trainable parameters alone [@cai2020tinytl]. On its image-classification transfer benchmarks, TinyTL reports training-memory savings of up to <code>[EdgeTinyTlResults.memory_saving_mult_str]</code> relative to fine-tuning the full network with little accuracy loss, so the adaptation working set can shrink to roughly <code>[EdgeTinyTlResults.full_to_tinytl_pct_str]</code> of the full fine-tuning footprint. The lite residual modules that recover adaptation capacity add only about <code>[EdgeTinyTlResults.lite_residual_overhead_pct_str]</code> memory overhead in that study. Those savings depend on the selected feature extractor, input resolution, batch size, normalization, and residual-module configuration. A saving measured on those benchmarks says nothing about whether an arbitrary frozen backbone fits into microcontroller SRAM, and when a deployed model must learn richer feature combinations without custom downsampled side-paths, it needs general structured updates beside the frozen weights.</p>\n<h3 id=\"sec-17\" class=\"cs-h3\">Structured parameter updates</h3>\n<p>Adapting a smartphone camera pipeline to a new low-light sensor profile or a mobile language model to a user's technical vocabulary requires recombining features across channels, a change that scalar bias offsets $\\BiasVector$ cannot express while the weight matrices $\\WeightMatrix$ remain fixed. Unfreezing $\\WeightMatrix$ directly would restore the full gradient and optimizer arrays in $\\TrainableStateMemory$, so the system instead adds compact, structured trainable matrices beside the frozen backbone. Residual adaptation modules [@houlsby2019parameter] and low-rank parameterizations [@hu2021lora] implement this choice in different ways. Both restrict parameter updates to the added components, but their training cost still includes the backward path through the surrounding network. The comparison with bias-only or full fine-tuning therefore requires both a quality target and a peak-memory measurement.</p>\n<h4 id=\"sec-18\" class=\"cs-h4\">Adapter-based adaptation</h4>\n<p>A common implementation involves inserting residual adapters, which are small residual bottleneck layers, between existing layers in a pretrained model. Consider a hidden representation $\\HiddenActivation$ passed between layers. A residual adapter introduces a transformation: $$ \\AdaptedHiddenActivation= \\HiddenActivation+ \\ResidualAdapterFunction(\\HiddenActivation) $$ where $\\ResidualAdapterFunction(\\cdot)$ is a trainable function, typically composed of two linear layers with a nonlinearity: $$ \\ResidualAdapterFunction(\\HiddenActivation) = \\WeightMatrix_2 \\, \\AdapterActivationFunction(\\WeightMatrix_1 \\HiddenActivation) $$ with $\\WeightMatrix_1 \\in \\mathbb{R}^{\\AdapterRank\\times \\HiddenDimension}$ and $\\WeightMatrix_2 \\in \\mathbb{R}^{\\HiddenDimension\\times \\AdapterRank}$, where $\\AdapterRank\\ll \\HiddenDimension$. This bottleneck design ensures that only a small number of parameters are introduced per layer.</p>\n<p>The adapters act as learnable perturbations on top of a frozen backbone. Because they are small and sparsely applied, their weights add little storage, although their saved activations and optimizer state still count against the training budget. They let the model shift its predictions in response to new inputs.</p>\n<p>The residual bottleneck in @lst-lowrank-adapter maps onto the adapter equation term by term. Its down-projection plays the role of $\\WeightMatrix_1$, mapping width $\\HiddenDimension$ to the bottleneck width $\\AdapterRank$. A ReLU supplies $\\AdapterActivationFunction$, and the up-projection plays the role of $\\WeightMatrix_2$, restoring width $\\HiddenDimension$ before the input is added back. Such modules can be implemented efficiently on edge devices, particularly when the two projection matrices are small and fixed-point representations are supported.</p>\n<pre class=\"cs-code\"><code>import torch.nn as nn\n\n\nclass Adapter(nn.Module):\n    def __init__(self, dim, bottleneck_dim):\n        super().__init__()\n        # Project from full dimension to bottleneck (e.g., 768 -&gt; 16)\n        self.down = nn.Linear(\n            dim, bottleneck_dim\n        )  # W1: learns compression\n        # Project back to original dimension (e.g., 16 -&gt; 768)\n        self.up = nn.Linear(\n            bottleneck_dim, dim\n        )  # W2: learns expansion\n        self.activation = nn.ReLU()\n\n    def forward(self, x):\n        # Residual connection: original + nonlinear bottleneck\n        # Only adapter params trained; base model frozen\n        return x + self.up(self.activation(self.down(x)))</code></pre>\n<h4 id=\"sec-18\" class=\"cs-h4\">Low-rank techniques</h4>\n<p>Another efficient strategy is to constrain the weight update itself to low rank. Low-rank adaptation (LoRA) leaves a base matrix $\\WeightMatrix_0 \\in \\mathbb{R}^{\\WeightMatrixRowCount\\times \\WeightMatrixColumnCount}$ frozen and learns its change as the product of a down-projection $\\AdapterDownProjectionMatrix\\in \\mathbb{R}^{\\AdapterRank\\times \\WeightMatrixColumnCount}$ and an up-projection $\\AdapterUpProjectionMatrix\\in \\mathbb{R}^{\\WeightMatrixRowCount\\times \\AdapterRank}$, with $\\AdapterRank\\ll \\min(\\WeightMatrixRowCount,\\WeightMatrixColumnCount)$. The adapted layer adds $\\AdapterUpProjectionMatrix\\AdapterDownProjectionMatrix\\LayerInputVector$ to the frozen output $\\WeightMatrix_0 \\LayerInputVector$. Training cost follows from that structure. The update $\\FiniteChange\\WeightMatrix= \\AdapterUpProjectionMatrix\\AdapterDownProjectionMatrix$ has $\\AdapterRank(\\WeightMatrixRowCount+ \\WeightMatrixColumnCount)$ trainable parameters instead of $\\WeightMatrixRowCount \\WeightMatrixColumnCount$, and only those parameters carry gradients and optimizer state.</p>\n<p>↩ The low-rank adapter forward pass, in which a frozen base projection is summed with a trainable down- and up-projection, is established in @sec-inference-multi-lora-serving.</p>\n<p>The decomposition rests on a linear-algebra fact. Any matrix can be expressed as a sum of rank-one matrices through singular value decomposition. Constraining updates to low rank (typically $\\AdapterRank= 4$ to $16$) captures a restricted set of variation modes while reducing parameters. For a typical transformer layer with dimensions $768{\\times}768$, full fine-tuning requires updating <code>[EdgeLowRankParams.full_params_str]</code> parameters. With rank-4 decomposition, only $768{\\times}4{\\times}2 =$ <code>[EdgeLowRankParams.lora_params_str]</code> parameters are updated, a <code>[EdgeLowRankParams.lora_reduction_pct_str]</code> reduction. Whether this retains most of the adaptation quality depends on the task, rank, and base model; the LoRA authors report that low-rank adapters can match or approach full fine-tuning on several transformer adaptation benchmarks [@hu2021lora].</p>\n<p>LoRA was developed for transformer models but applies to any layer built on a weight matrix. From a systems engineering perspective, LoRA makes the trainable adapter the artifact that can be stored, transmitted, scheduled, and rolled back separately from the frozen base model.</p>\n<p>: <strong>LoRA (low-rank adaptation)</strong>: @hu2021lora learn rank-$\\AdapterRank$ decomposition matrices $\\AdapterDownProjectionMatrix$ and $\\AdapterUpProjectionMatrix$ instead of updating full weight matrices, reporting a 10,000$\\times$ reduction in trainable parameters for their GPT-3 comparison. That reduction does not apply to the full model footprint: a model with <code>[EdgeLoraParameterEfficiency.base_model_params_b_str]</code> parameters has about a <code>[EdgeLoraParameterEfficiency.fp16_weight_footprint_gb_str]</code> FP16 weight footprint before gradients, optimizer state, and activations. Even at rank <code>[EdgeAdaptationTierProfile.mid_tier_lora_rank_str]</code>, adapter storage depends on the dimensions and number of adapted matrices, and deployment must still accommodate the frozen base model.</p>\n<p>Drawn to proportion for a square layer of width $\\HiddenDimension$, the adapted layer shows where the saving comes from (@fig-adapter-lora-arch). Input $\\LayerInputVector\\in \\mathbb{R}^\\HiddenDimension$ passes through the frozen $\\HiddenDimension{\\times}\\HiddenDimension$ base matrix $\\WeightMatrix_0$ and, in parallel, through a thin $\\AdapterRank{\\times}\\HiddenDimension$ down-projection $\\AdapterDownProjectionMatrix$ and a $\\HiddenDimension{\\times}\\AdapterRank$ up-projection $\\AdapterUpProjectionMatrix$. The two paths sum to $\\HiddenActivation= \\WeightMatrix_0 \\LayerInputVector+ \\AdapterUpProjectionMatrix\\AdapterDownProjectionMatrix\\LayerInputVector$. The base weights need no parameter gradients or optimizer state, although backward computation may still traverse the base path. Folding the product into the base weights ($\\WeightMatrix_0 + \\AdapterUpProjectionMatrix\\AdapterDownProjectionMatrix$) removes separate adapter arithmetic for that merged model. Numerical compatibility, any requantization, and the cost of retaining merged copies determine whether this is the appropriate serving representation.</p>\n<p>Consider a mobile deployment where a language model with <code>[EdgeLoraParameterEfficiency.base_model_params_b_str]</code> parameters has a <code>[EdgeLoraParameterEfficiency.fp16_weight_footprint_gb_str]</code> FP16 weight footprint, before accounting for the additional gradients, optimizer states, and activations required by full fine-tuning. That footprint exceeds smartphones with about <code>[EdgeAdaptationTierProfile.smartphone_ram_gb_str]</code> total memory unless the base model is quantized, partitioned, or offloaded. Choosing LoRA rank <code>[EdgeAdaptationTierProfile.mid_tier_lora_rank_str]</code> restricts the update space, and this chapter's fleet examples budget a reference adapter update of <code>[EdgeAdaptationTierProfile.federated_lora_update_mb_str]</code>. That figure is a communication payload, not a training-memory estimate. The device must also fit the base model, gradients, optimizer state, and live activations under its execution plan.</p>\n<p>The smaller payload also matters under intermittent connectivity. Transferring the full FP16 model in this example requires <code>[EdgeLoraParameterEfficiency.fp16_weight_footprint_gb_str]</code>, while the reference adapter update is <code>[EdgeAdaptationTierProfile.federated_lora_update_mb_str]</code>. Transfer time depends on encoded bytes, effective link throughput, and interruptions. An adapter-only transfer provides the saving only when the receiving device already holds a compatible base model; base-version changes must be included in the communication budget. In both the residual bottleneck and LoRA, the width or rank $\\AdapterRank$ sets the trainable cost, so a deployment can size it to the memory each device class leaves for learning. The device-tier framework of @sec-edge-intelligence-performance-vs-resource-tradeoffs-2be2 decides which mechanism each class receives.</p>\n<h4 id=\"sec-18\" class=\"cs-h4\">Edge personalization</h4>\n<p>Adapters support multiple personalized contexts with one frozen backbone. For an input width $\\HiddenDimension$, a residual bottleneck of width $\\AdapterRank$ uses $2d\\AdapterRank$ matrix parameters, plus $\\AdapterRank+\\HiddenDimension$ biases when both projections include them. A deployment with several adapters must sum this count over their insertion sites; rank or bottleneck width alone does not determine the total. Stored bytes then equal parameter count times bytes per stored value. With $\\HiddenDimension= 768$ and $\\AdapterRank= 16$, one adapter holds <code>[EdgeAdapterRamRecap.adapter_params_str]</code> parameters, about <code>[EdgeAdapterRamRecap.adapter_kb_str]</code> in FP16; one adapter after each of 12 blocks totals <code>[EdgeAdapterRamRecap.adapter_total_params_str]</code> parameters, roughly <code>[EdgeAdapterRamRecap.adapter_total_mb_str]</code>. During training, gradients, optimizer state, and saved activations add to that storage footprint. A device can swap context-specific modules while sharing the much larger base model, provided it can hold the base and active adaptation state together.</p>\n<p>This <strong>adapter switching</strong> pattern lets a smartphone select context-specific behavior without replacing the entire backbone. When the user enters a low-light environment, the system can load a compatible adapter into the vision pipeline; selecting an existing adapter does not itself require learning. The modularity extends naturally to federated learning: transmitting only the adapted parameters can reduce upload traffic relative to a full-model update, with savings determined by the total adapter count and encoding. Residual-adapter studies show that small trainable modules can adapt a shared visual backbone across multiple visual domains [@rebuffi2017learning], making them a useful design point between personalization quality and system resources. Freezing the backbone preserves its parameters, while adapters provide a bounded place for user- or context-specific updates. The resulting model can still suffer catastrophic forgetting, the loss of previously learned behavior after new updates (defined in @sec-edge-intelligence-experience-replay-737e).</p>\n<p><strong>Problem</strong>: A team is deploying a 10M parameter vision model to a smartphone with support for <code>[StorageWall.ls_contexts_str]</code> different \"User Contexts\" (Home, Office, Car, etc.). If a full fine-tuned model requires <code>[StorageWall.ls_full_mb_str]</code>, how much storage does using residual adapters save instead?</p>\n<p><strong>Math</strong>:</p>\n<ol class=\"cs-list\">\n<li><strong>Full fine-tuning</strong>: <code>[StorageWall.ls_contexts_str]</code> contexts $\\times$ <code>[StorageWall.ls_full_mb_str]</code> = <code>[StorageWall.ls_total_full_mb_str]</code>.</li>\n<li><strong>Adapter approach</strong>: (1 $\\times$ <code>[StorageWall.ls_full_mb_str]</code> backbone) + (<code>[StorageWall.ls_contexts_str]</code> $\\times$ <code>[StorageWall.ls_adapter_kb_str]</code> adapters) $\\approx$ <code>[StorageWall.ls_total_adapter_mb_str]</code>.</li>\n<li><strong>Storage savings</strong>: <code>[StorageWall.ls_total_full_mb_str]</code>/<code>[StorageWall.ls_total_adapter_mb_str]</code> $\\approx$ <code>[StorageWall.ls_total_savings_ratio_mult_str]</code> total device storage reduction.</li>\n<li><strong>Per-context efficiency</strong>: <code>[StorageWall.ls_full_mb_str]</code>/<code>[StorageWall.ls_adapter_mb_str]</code> = <code>[StorageWall.ls_savings_ratio_mult_str]</code>.</li>\n</ol>\n<p><strong>Systems insight</strong>: Multiple personalized models create a storage cost even when only one runs at a time. Storing <code>[StorageWall.ls_contexts_str]</code> copies of a <code>[StorageWall.ls_full_mb_str]</code> model consumes <code>[StorageWall.ls_total_full_mb_str]</code>. In this example, sharing the frozen backbone and storing separate adapters reduces the marginal storage cost of a new context by <code>[StorageWall.ls_savings_ratio_mult_str]</code>. This comparison establishes storage savings; the device must still accommodate the active model, adaptation state, and context-switching cost.</p>\n<p>That separation between a shared backbone and context-specific adapters appears directly in smartphone camera pipelines, where environmental lighting, user preferences, and lens distortion vary between users. Residual modules can adapt a frozen shared model to these differences while leaving its base weights unchanged; the combined model's behavior still requires validation. In voice-based systems, adapters similarly provide a way to test personalized speech recognition without retraining the full acoustic model. Keeping the base and adapter versions compatible also supports rollback or switching between user-specific versions when adaptation degrades performance.</p>\n<h4 id=\"sec-18\" class=\"cs-h4\">Performance vs. resource trade-offs</h4>\n<p>Selecting an adaptation strategy requires accounting for both resource cost and expressivity. Bias-only updates retain a small trainable state but may lack the capacity to handle structural domain shifts. Full fine-tuning exposes every parameter to adaptation and adds corresponding gradient and optimizer state. LoRA and residual adapters offer intermediate choices whose cost depends on rank or width, insertion sites, and numerical representation. The same budget, @eq-edge-adaptation-peak-memory, governs each of these strategies. Because peak working memory $\\AdaptationPeakMemory$ must jointly contain resident weights, trainable state $\\TrainableStateMemory$, and the peak of live activations under the device ceiling $\\DeviceMemoryCapacity$, each strategy shrinks a different term. Bias-only and adapter methods shrink $\\TrainableStateMemory$, and TinyTL-style choices also shrink the activation term. Training only the final classifier, whose backward pass stops at the head, removes most of that term. Parameter storage alone therefore cannot determine whether background adaptation fits.</p>\n<p>LoRA and residual adapters impose different deployment costs. For a fixed adapter and compatible numerical representation, LoRA's linear update can be merged into the backbone before inference $(\\WeightMatrix_0 + \\AdapterUpProjectionMatrix\\AdapterDownProjectionMatrix)$, avoiding separate adapter arithmetic in the forward path. A quantized base may require requantization and renewed quality validation after merging. Keeping a separate merged backbone for every context also sacrifices the storage benefit of sharing one base. Residual adapters remain distinct modules ($\\LayerOutputVector= \\FrozenBackboneFunction(\\LayerInputVector) + \\text{Adapter}(\\LayerInputVector)$); their latency cost depends on shape, placement, and runtime, while switching contexts requires only the corresponding adapter state.</p>\n<p>The runtime must support the selected adapter's forward operators and its training path. These can use a dynamic graph or a statically compiled update schedule; dynamic graph construction is not itself a requirement. For an inference engine such as Open Neural Network Exchange (ONNX) Runtime Mobile, a runtime that executes an adapter's forward path may still lack its backward operators, optimizer, or state management. The deployment must verify both paths, including any transfers between the processor that runs inference and the processor that performs updates.</p>\n<p>For this multi-context personalization workload, where one device switches among several adapters, system architects can use a device-tier framework to organize candidate mechanisms. On flagship phones (Tier 1) with dedicated Neural Engines and <code>[EdgeAdapterRamRecap.smartphone_ram_gb_str]</code> of RAM or more, residual adapters provide a strong balance of modularity and speed, because switching contexts swaps only adapter state. On mid-range devices (Tier 2) with 1 GB up to <code>[EdgeAdapterRamRecap.smartphone_ram_gb_str]</code>, LoRA may fit when a fixed adapter can be merged into a compatible base representation before inference, trading switching flexibility for zero added inference arithmetic. For ultra-constrained IoT endpoints (Tier 3) with less than 1 GB RAM, bias-only updates may be the only practical option.</p>\n<p>Budget phones show that the tier follows the memory available to learning rather than installed RAM. Their <code>[EdgeAdaptationTierProfile.budget_phone_ram_gb_str]</code> places them in Tier 2, yet only <code>[EdgeAdaptationTierProfile.budget_phone_available_low_gb_str]</code>--<code>[EdgeAdaptationTierProfile.budget_phone_available_high_gb_str]</code> remains for ML work after the operating system. A background adaptation task may be granted less, so a deployment can reasonably hold them to the Tier 3 mechanism. The assignments follow from the workload as much as from the hardware. A workload that keeps one adaptation per user, rather than many switchable contexts, loses the reason to keep adapters separate and can favor merged LoRA even on flagship devices. The runtime must still verify the base-model footprint and admit training within the measured device envelope.</p>\n<p>Verify understanding of efficient on-device adaptation:</p>\n<ul class=\"cs-list\">\n<li>[ ] Adapter switching: Explain why Adapter Switching is more storage-efficient than maintaining separate full-model copies for different user contexts.</li>\n<li>[ ] Adapter size: Derive the parameter count of a residual adapter from its input width and bottleneck width, then identify the additional inputs needed to compare its storage with a full model.</li>\n<li>[ ] Residual vs. LoRA: For a multi-context workload, identify the deployment tier (Tier 1, 2, or 3) where residual adapters are preferred over LoRA and justify the choice, then explain why a workload with one adaptation per user changes the answer.</li>\n<li>[ ] Adapter bandwidth: Evaluate the claim that transmitting adapter weights in federated learning consumes more bandwidth than transmitting the entire model.</li>\n</ul>\n<h3 id=\"sec-18\" class=\"cs-h3\">Sparse updates</h3>\n<p>Bias-only updates and fixed adapters choose where the model may change before seeing local data, yet a local shift can alter specific convolutional filters or attention channels rather than every block uniformly. Sparse updates instead adapt selected existing parameters rather than adding modules. Their expressivity relative to adapters depends on the selected locations and parameter budget. A task-adaptive policy selects those locations using evidence about the current task or user. The resulting update space can target changes that a fixed subset misses, but selection itself consumes resources and does not guarantee that the complete training path fits the device.</p>\n<p>The useful savings depend on what the runtime can omit. Unselected parameters need no gradient or optimizer state, but their operations may still lie on the backward path to selected parameters. A policy must therefore compare the measured update cost with its adaptation benefit; the fraction of trainable parameters alone does not predict the reduction in compute. Because layers do not contribute equally to local performance gains, identifying the minimal subset with the highest adaptation value lets the system spend scarce training capacity where it changes the model's behavior most.</p>\n<h4 id=\"sec-19\" class=\"cs-h4\">Sparse update design</h4>\n<p>Let a neural network be defined by parameters $\\ModelParameters= \\{\\ModelParameters_1, \\ModelParameters_2, \\ldots, \\ModelParameters_{\\LayerCount}\\}$ across $\\LayerCount$ layers. In standard fine-tuning, gradients are computed and updates are performed on all parameters: $$ \\ModelParameters_i \\leftarrow \\ModelParameters_i - \\LearningRate\\frac{\\partial \\LossFunction}{\\partial \\ModelParameters_i}, \\quad \\text{for } \\LayerSelectionIndex= 1, \\ldots, \\LayerCount $$</p>\n<p>In task-adaptive sparse updates, the system selects a small subset $\\SelectedLayerSet\\subset \\{1, \\ldots, \\LayerCount\\}$ such that only parameters in $\\SelectedLayerSet$ are updated: $$ \\ModelParameters_i \\leftarrow \\begin{cases} \\ModelParameters_i - \\LearningRate\\frac{\\partial \\LossFunction}{\\partial \\ModelParameters_i}, &amp; \\text{if } \\LayerSelectionIndex\\in \\SelectedLayerSet\\\\ \\ModelParameters_i, &amp; \\text{otherwise} \\end{cases} $$</p>\n<p>The challenge lies in selecting the optimal subset $\\SelectedLayerSet$ given memory and compute constraints. A principled strategy is contribution analysis, an empirical method that estimates how much each layer contributes to downstream performance improvement. For example, one can measure the marginal gain from updating each layer independently:</p>\n<ol class=\"cs-list\">\n<li>Freeze the entire model.</li>\n<li>Unfreeze one candidate layer.</li>\n<li>Finetune briefly and evaluate improvement in validation accuracy.</li>\n<li>Rank layers by performance gain per unit cost (e.g., per KB of trainable memory).</li>\n</ol>\n<p>This layer-wise profiling yields a candidate ranking from which $\\SelectedLayerSet$ can be constructed subject to a memory budget. Gains measured one layer at a time need not add when layers train together, and shared backward dependencies change the combined cost. The selected set therefore needs a joint quality and resource check, with the profiling cost included in the adaptation budget.</p>\n<p>In a complete selective fine-tuning pipeline, that ranking is the middle of three stages (@fig-ondevice-pretraining). Stage 1 meta-trains the network in the cloud, which means training its initial weights so that a few later updates on new data adapt it well (the idea behind model-agnostic meta-learning, taken up in @sec-edge-intelligence-federated-personalization-3c73). Stage 2 ranks layers or channel groups by adaptation benefit per unit of device cost and lets the device budget set the cut, and Stage 3 updates only the units above the cut on local data. The backward pass still runs through any frozen layer that lies between the loss and a selected unit, so the selected set must be costed under the complete execution schedule.</p>\n<p>A concrete example is TinyTrain, a method designed to allow rapid adaptation on-device [@kwon2024tinytrain]. TinyTrain combines offline preparation with a task-adaptive sparse-update method that dynamically selects layers or channels to update using user data, memory limits, and compute limits. At runtime, the system updates only the selected subset rather than treating the whole network as trainable.</p>\n<p>In implementation, selective layer updating turns the ranking into <code>requires_grad</code> decisions or equivalent graph masks. In the profiling-driven version, contribution scores and the memory limit decide which layers are unfrozen (@lst-selective-update).</p>\n<pre class=\"cs-code\"><code># Selective layer update based on contribution analysis\n# Layers selected via profiling: conv2 and fc have highest\n# accuracy-per-KB impact for this task\n\nfor name, param in model.named_parameters():\n    if &quot;conv2&quot; in name or &quot;fc&quot; in name:\n        param.requires_grad = True  # Train high-impact layers\n    else:\n        param.requires_grad = False  # Freeze low-impact layers\n\n# Parameter fraction follows layer shapes; adaptation quality requires evaluation\n# Memory savings: gradient storage only for selected layers</code></pre>\n<p>Consider a user wearing an augmented reality headset that performs real-time object recognition. As lighting and environments shift, the system must adapt to maintain accuracy, but training must occur during brief idle periods or while charging. TinyTrain addresses this constraint with task-adaptive sparse updates, in which the deployment process selects a small update set that fits the device's memory and compute budget. The approach keeps adaptation fast, energy-efficient, and memory-aware when the target task and device profile match the method's assumptions.</p>\n<p>Task-adaptive sparse updates still introduce system-level trade-offs. Contribution analysis has a nontrivial computational cost even when it occurs during pretraining or initial profiling, so the deployment pipeline must budget for it. Stability also requires attention: if too few parameters are selected for updating, the model may underfit the target distribution, so teams need validation thresholds for the selected subset before deployment. The selection policy must also account for hardware-specific execution costs because some parameters show high contribution scores but prove expensive to update on certain architectures. Despite these trade-offs, task-adaptive sparse updates provide a practical mechanism to scale adaptation across deployment contexts from microcontrollers to mobile devices [@kwon2024tinytrain].</p>\n<h4 id=\"sec-19\" class=\"cs-h4\">Adaptation strategy comparison</h4>\n<p>The design target is the smallest update space that captures the local change. Whereas full fine-tuning pays every term of @eq-edge-adaptation-peak-memory, bias-only updates and head-only training fit minor calibration or new output categories, LoRA and residual adapters add bounded capacity beside a frozen backbone, and task-adaptive sparse updates spend profiling effort to select valuable existing parameters. Because each strategy shrinks a different budget term, a larger update space is justified only if its measured quality gain fits the device's training budget alongside expressivity, runtime support, and selection cost. @Tbl-adaptation-strategies sets these adaptation strategy trade-offs side by side.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Technique</strong></th><th><strong>Trainable parameters</strong></th><th><strong>Memory overhead</strong></th><th><strong>Expressivity</strong></th><th><strong>Use case suitability</strong></th><th><strong>System requirements</strong></th></tr></thead><tbody>\n<tr><td><strong>Full Fine-Tuning</strong></td><td>All parameters</td><td>Highest; every term of the peak budget</td><td>Highest</td><td>Large domain shift on capable devices</td><td>Full backward support and memory headroom</td></tr>\n<tr><td><strong>Bias-Only Updates</strong></td><td>Bias terms only</td><td>Minimal $\\TrainableStateMemory$; activations remain</td><td>Low</td><td>Simple personalization; low variance</td><td>Extreme memory/compute limits</td></tr>\n<tr><td><strong>Head-Only Training</strong></td><td>Final classifier</td><td>Minimal; backward pass stops at the head</td><td>Low</td><td>New output classes; custom wake words</td><td>Frozen encoder; reusable cached features</td></tr>\n<tr><td><strong>LoRA</strong></td><td>Low-rank factors per adapted matrix</td><td>Low $\\TrainableStateMemory$; activations remain</td><td>Moderate to High</td><td>One mergeable adaptation per user</td><td>Merge step and requantization check for serving</td></tr>\n<tr><td><strong>Residual Adapters</strong></td><td>Adapter modules</td><td>Low $\\TrainableStateMemory$; activations remain</td><td>Moderate to High</td><td>Switching among several contexts on mobile</td><td>Mobile-class SoCs with runtime support</td></tr>\n<tr><td><strong>Sparse Layer Updates</strong></td><td>Selective parameter subsets</td><td>Variable; depends on the selected layers</td><td>High (task-adaptive)</td><td>Real-time adaptation; domain shift</td><td>Requires profiling or meta-training</td></tr>\n</tbody></table></div>\n<p>: <strong>Adaptation Strategy Trade-Offs</strong>: Six approaches to model adaptation compared by trainable parameters, the term of the peak-memory budget (@eq-edge-adaptation-peak-memory) they shrink, expressivity, suitability, and system requirements. Methods that shrink only the trainable state $\\TrainableStateMemory$ still keep the activations their backward pass needs, while head-only training also removes most of the activation term by stopping the backward pass at the classifier. {#tbl-adaptation-strategies}</p>\n<p>Once an adaptation mechanism fits the device's memory and execution budget, it must still learn from the available examples. Reducing trainable state does not create labels or ensure that a user's recent observations represent future use. The next constraint is therefore statistical: extracting reliable learning signal from sparse local data while retaining useful prior behavior.</p>\n<h2 id=\"sec-19\" class=\"cs-h2\">Data Efficiency</h2>\n<p>A user corrects smartphone keyboard autocorrect perhaps three times a day. The system cannot require 10,000 labeled sentences to train a local language model. Data efficiency at the edge means learning aggressively from a sparse, noisy, and uncurated trickle of implicit user feedback, maximizing the signal extracted from each interaction.</p>\n<p>The systems trade-off is data collection cost against adaptation quality. Every retained example costs user friction, energy, storage, and privacy exposure. A voice assistant adapting to speech samples weighs model improvement against battery drain and user comfort with always-on recording, and a keyboard chooses between logging shallow keystroke statistics and keeping full typing sessions. Unlike a central pipeline, the device cannot reach into a larger dataset when its own evidence runs short, and an application that needs a decision before enough evidence accumulates may be better served by a validated fixed model than by immediate learning. Whatever the device does learn must also stay compatible with the adaptation mechanism of @sec-edge-intelligence-model-adaptation-6a82 and with any federated protocol that later consumes it.</p>\n<p>The strategy choice depends on which scarcity binds first, and practical systems usually combine several: few-shot learning handles cases where only a handful of labeled or weakly labeled examples must drive personalization, whereas streaming updates handle observations that arrive incrementally and cannot be batched in advance. Because continual streaming updates can overwrite earlier behavior, experience replay spends memory to retain and reuse scarce examples, while data compression shrinks those stored histories so that replay and lightweight training remain feasible within edge memory budgets. Data scarcity thus becomes an allocation problem, in which the device spends labels, memory, compute, and privacy budget where they produce the most reliable local signal.</p>\n<h3 id=\"sec-20\" class=\"cs-h3\">Few-shot learning and data streaming</h3>\n<p>A user enrolling a custom wake word will record five audio samples during setup, not five thousand, and subsequent corrections arrive one interaction at a time during ordinary use. Because local learning must proceed from either a tiny enrollment set or a passive trickle of user interactions and ambient sensor readings, it relies on two complementary adaptation strategies: few-shot learning, in which models generalize from a small, static set of examples, and streaming adaptation, where incremental observations support updates scheduled within device budgets.</p>\n<p>Few-shot adaptation uses limited labeled or weakly labeled evidence for a new task or user condition [@wang2020]. Bias-only updates, adapter modules, and prototype-based classification (which labels an input by the nearest per-class average embedding of the few labeled examples) restrict what must be learned, but each still needs validation against overfitting. Let $\\FewShotSupportSet= \\{(\\ModelInput_i, \\ExampleLabel_i)\\}_{i=1}^{\\SupportSetSize}$ denote the local support set; here $\\SupportSetSize$ counts all examples in the set, rather than examples per class. A candidate policy might permit few gradient steps ($\\FewShotStepCount\\ll 100$) and a small trainable subset ($|\\UpdatedParameterSubset| \\ll |\\ModelParameters|$). These are illustrative restrictions, not universal feasibility conditions. The actual step and parameter budgets follow from measured device cost and the quality target, including retained performance on earlier tasks.</p>\n<p>Those step and parameter budgets are especially tight in keyword spotting (KWS) systems, a common target for data-efficient on-device adaptation; Speech Commands provides a dataset for training and evaluating limited-vocabulary KWS models [@warden2018speech]. A detector must distinguish its target phrase from background speech while meeting latency and false-activation requirements. One design uses a pretrained acoustic encoder, such as a small convolutional or recurrent network, to map audio into embeddings for a lightweight classifier. A shared encoder supplies reusable features, while local examples can support a custom wake word or an underrepresented accent. Whether those examples justify local training depends on their coverage, transfer restrictions, and the improvement over the shared detector.</p>\n<p>Few-shot adaptation can train an output classifier or another small parameter subset from utterances collected directly on the device. A user might provide 5–10 recordings of a custom wake word while the acoustic encoder remains frozen. Those positive examples define what to recognize, but the false-activation rate on other speech and background noise is a separate measurement, and the personalized detector should not be accepted until it has been made.</p>\n<p>Head-only adaptation is cheap in a way the peak-memory budget of @eq-edge-adaptation-peak-memory makes precise. Because the backward pass stops at the classifier, the encoder's saved activations leave the activation term, and the encoder outputs for the support set can be computed once and reused across update steps. What remains is running the encoder forward, holding the support examples or their features, and evaluating the adapted classifier. Those costs, not the size of the head, decide whether the update fits a particular phone or microcontroller.</p>\n<p>Many on-device scenarios instead call for streaming adaptation, in which the model learns incrementally as data arrives over time rather than from a fixed support set [@hayes2020remind]. Although observations arrive continuously, the runtime admits training only when memory, energy, and foreground-latency budgets permit, so the update rule applies to each admitted step rather than to every arrival. Let $\\{\\ModelInput_t\\}<em>{t=1}^{\\infty}$ represent the observations selected from the stream for those admitted updates, with the index $\\OptimizerStepIndex$ counting the update steps. Using a computable loss drawn from implicit feedback, pseudo-labels, self-supervised objectives, reconstruction error, or a task-specific proxy rather than explicit human labels, the model update can be written generically as: $$ \\ModelParameters</em>{t+1} = \\ModelParameters_t - \\LearningRate_t \\nabla \\LossFunction(\\ModelInput_t; \\ModelParameters_t) $$ where $\\LearningRate_t$ is the learning rate at time $\\OptimizerStepIndex$. This form of adaptation is sensitive to noise and drift in the input distribution, and thus often incorporates mechanisms such as learning rate decay, meta-learned initialization, or update gating to improve stability.</p>\n<p>The same strategies apply beyond keyword spotting. In wearable health devices, a model that classifies physical activities may begin with a generic classifier and adapt to user-specific motion patterns using only a few labeled activity segments. In smart assistants, user voice profiles are fine-tuned over time using ongoing speech input, even when explicit supervision is unavailable. Local corrections, repetitions, or downstream task completion can provide implicit signals, but only after the system defines which event counts as feedback and tests its validity. A user may accept a suggestion because it is convenient rather than correct, abandon a task for reasons unrelated to the model, or correct an error that the model itself induced. Production adaptation should therefore separate observed events from inferred labels, retain a nonadapting control cohort, measure delayed outcomes when available, and gate learning when the proxy-to-outcome relationship drifts. A stream of such updates also raises a stability problem that few-shot and streaming rules do not address on their own.</p>\n<h3 id=\"sec-21\" class=\"cs-h3\">Experience replay</h3>\n<p>When a streaming update rule trains only on a user's newest interactions, gradient steps on recent examples overwrite the weights that recognized earlier classes, causing accuracy on prior tasks to collapse within a few updates. Retaining a small sample of earlier observations on the device reduces this failure mode without eliminating it.</p>\n<p><em><strong>Catastrophic forgetting</strong></em> is the phenomenon in which a neural network trained sequentially on new tasks or data distributions rapidly loses performance on previously learned tasks, because gradient updates that optimize the new objective overwrite weight configurations that supported the old ones.</p>\n<ol class=\"cs-list\">\n<li><strong>Significance</strong>: Without explicit mitigation, fine-tuning a deployed classifier on a new domain can sharply reduce prior-task accuracy, even when the new domain is closely related to the old one [@kirkpatrick2017]. This is the central failure mode of on-device and federated learning. Every device that adapts locally to its user's recent data risks erasing the general capabilities the centralized training run paid for, and the loss is invisible until inference encounters out-of-recent-context inputs.</li>\n<li><strong>Distinction</strong>: Unlike overfitting (a generalization failure on a single fixed task) and distribution shift (a deployment-time mismatch between training and inference data), forgetting is a training-time phenomenon caused by the sequential structure of the update stream itself. Updates for new data can interfere with earlier solutions even when a representation capable of supporting both tasks exists.</li>\n<li><strong>Common pitfall</strong>: A frequent misconception is that a small experience-replay buffer is sufficient protection. A small buffer can hold aggregate accuracy on a held-out set while rare classes, which it samples too seldom, continue to degrade. Forgetting must therefore be measured per class or per cohort, and the remedies range from capacity-proportional or prioritized buffers to weight-regularization methods such as elastic weight consolidation, which store no examples (@sec-edge-intelligence-lifelong-adaptation-without-forgetting-9200).</li>\n</ol>\n<p>Experience replay addresses forgetting by retaining examples from earlier learning episodes and reusing them during later updates. Replay also appears in reinforcement learning [@mnih2015]; here its role is to keep earlier local observations represented as new data arrives. Because retaining those observations is one stability mechanism with an explicit storage cost, @sec-edge-intelligence-lifelong-adaptation-without-forgetting-9200 returns to the problem with parameter-importance penalties, bounded update footprints, and rollback.</p>\n<p>Unlike server-side replay strategies that rely on large datasets and extensive compute, on-device replay must operate with extremely limited capacity, often with tens or hundreds of samples, and must avoid interfering with user experience [@rolnick2019experience]. Buffers may store only compressed features or distilled summaries, and updates must occur opportunistically (e.g., during idle cycles or charging). These system-level constraints reshape how replay is implemented and evaluated in the context of embedded ML.</p>\n<p>Let $\\ReplayBuffer$ represent a memory buffer that retains a fixed-size subset of training examples. At time step $\\OptimizerStepIndex$, the model receives a new data point $(\\ModelInput_t, \\ExampleLabel_t)$ and appends it to $\\ReplayBuffer$. A replay-based update then samples a batch $\\{(\\ModelInput_i, \\ExampleLabel_i)\\}<em>{i=1}^{\\BatchSize}$ of size $\\BatchSize$ from $\\ReplayBuffer$ and applies a gradient step: $$ \\ModelParameters</em>{t+1} = \\ModelParameters_t - \\LearningRate\\nabla_\\ModelParameters\\left[ \\frac{1}{\\BatchSize} \\sum_{i=1}^{\\BatchSize} \\LossFunction(\\ModelInput_i, \\ExampleLabel_i; \\ModelParameters_t) \\right] $$ This is the streaming update of @sec-edge-intelligence-fewshot-learning-data-streaming-566e with one change of data source, from the newest observation to a batch drawn from $\\ReplayBuffer$. The systems cost lies in what that change requires, namely buffer storage that competes with model state and forward and backward work on old examples in every admitted window. Over time, this replay mechanism allows the model to reinforce prior knowledge while incorporating new information.</p>\n<p>A practical on-device implementation might use a ring buffer to store a small set of compressed feature vectors rather than full input examples. The buffer has a fixed capacity and overwrites its oldest entry once full, so one parameter bounds its memory and sets the balance between retained history and new data (@lst-replay-buffer).</p>\n<pre class=\"cs-code\"><code>import random\n\n\n# Ring buffer for experience replay on memory-constrained devices\n# Stores compressed features (not raw inputs) to minimize footprint\nclass ReplayBuffer:\n    def __init__(self, capacity):\n        self.capacity = capacity  # Fixed size, e.g., 1000 examples\n        self.buffer = []\n        self.index = 0  # Circular write pointer\n\n    def store(self, feature_vec, label):\n        if len(self.buffer) &lt; self.capacity:\n            self.buffer.append((feature_vec, label))  # Fill phase\n        else:\n            self.buffer[self.index] = (\n                feature_vec,\n                label,\n            )  # Overwrite oldest\n        self.index = (self.index + 1) % self.capacity  # Wrap around\n\n    def sample(self, k):\n        # Uniform sampling within the retained buffer; older examples are absent\n        return random.sample(self.buffer, min(k, len(self.buffer)))</code></pre>\n<p>This implementation maintains a fixed-capacity cyclic buffer, storing compressed representations (e.g., last-layer embeddings) and associated labels. Uniform sampling here covers only the retained recent window; it does not remove the history bias introduced by overwriting old examples. Reservoir sampling, which keeps each new arrival with a probability that shrinks as the stream grows so that every observation seen so far is equally likely to remain in the buffer, is an alternative when the goal is to represent the full stream, though any finite buffer still requires coverage checks.</p>\n<p>In TinyML applications, experience replay has been applied to problems such as gesture recognition, where devices must continuously improve predictions while observing a small number of events per day. Instead of training directly on the streaming data, the device stores representative feature vectors from recent gestures and uses them to finetune classification boundaries periodically. Similarly, in on-device keyword spotting, replaying past utterances can improve wake-word detection accuracy without the need to transmit audio data off-device.</p>\n<p>Experience replay spends storage and additional update work to preserve earlier behavior. Raw inputs can exceed storage or retention budgets, especially in vision and audio applications. Cached feature vectors reduce that footprint, but an update starting from those vectors trains the downstream model without reconstructing the original encoder computation. If the encoder changes, old features may no longer match its current representation; the system must retain a compatible encoder, refresh the features from retained inputs, or expire incompatible entries. Persistent replay also consumes flash write cycles. Buffer contents, representation versions, and replay frequency therefore belong in the same resource and retention policy.</p>\n<h3 id=\"sec-22\" class=\"cs-h3\">Data compression</h3>\n<p>Experience replay is limited by how many examples fit in the buffer: storing raw $224{\\times}224$ camera frames or uncompressed audio waveforms inside an on-device replay buffer fills a wearable's or microcontroller's memory after only a few dozen observations. When raw training inputs are too large, noisy, or redundant to store and process directly, transforming them into lower-dimensional embeddings or compact encodings preserves task-relevant structure while shrinking memory and compute costs. Compressed representations serve two complementary goals. They reduce the footprint of stored data, allowing devices to maintain longer histories or replay buffers under tight memory budgets [@hayes2020remind]. They also simplify the learning task by projecting raw inputs into more structured feature spaces, often learned via pretraining or meta-learning, in which efficient adaptation is possible with minimal supervision.</p>\n<p>One common approach is to encode data points using a pretrained feature extractor and discard the original high-dimensional input. For example, an image $\\ModelInput_i$ might be passed through a CNN to produce an embedding vector $\\StoredEmbedding_i = \\FrozenFeatureEncoder(\\ModelInput_i)$, where $\\FrozenFeatureEncoder(\\cdot)$ is a fixed feature encoder. This embedding captures visual structure (e.g., shape, texture, or spatial layout) in a compact representation, usually ranging from 64 to 512 dimensions, suitable for lightweight downstream adaptation.</p>\n<p>Mathematically, training can proceed over compressed samples $(\\StoredEmbedding_i, \\ExampleLabel_i)$ using a lightweight classification or projection head. Let $\\ModelParameters$ represent the trainable parameters of this head, which is typically a small neural network that maps from compressed representations to output predictions. As each example is presented, the model parameters are updated using gradient descent: $$ \\ModelParameters_{t+1} = \\ModelParameters_t - \\LearningRate\\nabla_\\ModelParameters\\LossFunction\\big(\\PredictionHeadFunction(\\StoredEmbedding_i; \\ModelParameters), \\ExampleLabel_i\\big) $$ The rule is the same gradient step once more, now applied to stored embeddings $\\StoredEmbedding_i$ and a small head whose prediction is $\\PredictionHeadFunction(\\StoredEmbedding_i; \\ModelParameters)$, rather than to raw inputs. Only the head's parameters $\\ModelParameters$ change, so its memory is the head-only case of the budget in @eq-edge-adaptation-peak-memory, and the encoder runs once per example when the embedding is stored rather than on every update. This bounds the trainable portion of the model, but feasibility still depends on the head's activations and optimizer state alongside the replay buffer and runtime reserves.</p>\n<p>When replay storage rather than model compute binds, a device can go further and learn a dictionary of recurring sensor-trace patterns, storing each example as a few nonzero coefficients over that dictionary instead of as raw samples. A dataset of traces $\\SensorTraceMatrix$ then factorizes as $\\SensorTraceMatrix\\approx \\SensorPatternDictionary\\DictionaryCoefficientMatrix$, where the columns of $\\SensorPatternDictionary$ are the basis patterns and the block-sparse coefficient matrix $\\DictionaryCoefficientMatrix$ records which patterns are active in each example. The saving is real only if the dictionary plus all stored coefficients is smaller than the raw replay examples. Updating the dictionary changes the representation of every stored example, so reconstruction quality and compatibility become part of the replay policy.</p>\n<p>Compressed representations can reduce how long raw inputs remain stored, but an embedding is not anonymized merely because it is lower dimensional. It may preserve identity, attributes, or enough structure for inversion, and it must receive the same access-control, retention, and deletion analysis as the source data unless a separate privacy mechanism establishes a stronger guarantee. Compression can also act as an implicit regularizer, smoothing learning and mitigating overfitting when only a few training examples are available.</p>\n<p>In keyword spotting, raw audio can first be transformed into mel-frequency cepstral coefficients (MFCCs), a compact, lossy representation derived from the speech power spectrum. Storing these vectors instead of waveforms reduces the replay payload. The complete adaptation budget must still include feature extraction, model state, and the working memory needed for updates.</p>\n<p>: <strong>MFCCs (mel-frequency cepstral coefficients)</strong>: For a 320-sample audio window (20 ms at 16 kHz), 16-bit samples occupy 640 bytes, while 12--13 coefficients stored at 32 bits each occupy approximately 50 bytes. The roughly 13$\\times$ reduction compares one waveform window with one feature vector; overlapping windows, additional features, and metadata change the storage ratio for a complete recording. Replay capacity depends on that complete representation, and keyword detection quality must be evaluated separately from byte savings.</p>\n<h3 id=\"sec-23\" class=\"cs-h3\">Data efficiency strategy comparison</h3>\n<p>Few-shot adaptation, replay, and compression each spend a different scarce resource and fail in a different way. Few-shot adaptation spends scarce labels on a small informative support set, and weak pretrained features can defeat it. Replay spends memory and compute to preserve prior behavior; raw observations can overflow device storage when memory is the bottleneck, and a buffer can omit rare cases. Compressed representations extend the history that fits on the device, but compression can discard task-relevant information, and fixed embeddings freeze the wrong representation when the feature extractor itself needs to adapt. Combining mechanisms does not escape these on-device learning trade-offs (@tbl-ondevice-techniques), because every combination must fit the same memory, energy, and privacy budget.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Technique</strong></th><th><strong>Data requirements</strong></th><th><strong>Memory/compute overhead</strong></th><th><strong>Use case fit</strong></th></tr></thead><tbody>\n<tr><td><strong>Few-Shot Adaptation</strong></td><td>Small labeled set ($\\SupportSetSize$ examples)</td><td>Low</td><td>Personalization, quick on-device finetuning</td></tr>\n<tr><td><strong>Experience Replay</strong></td><td>Streaming data</td><td>Moderate (buffer &amp; update)</td><td>Non-stationary data, stability under drift</td></tr>\n<tr><td><strong>Compressed Representations</strong></td><td>Unlabeled or encoded data</td><td>Low to Moderate</td><td>Memory-limited devices; privacy-sensitive contexts</td></tr>\n</tbody></table></div>\n<p>: <strong>On-Device Learning Trade-Offs</strong>: Technique choice depends on the binding edge constraint: few-shot adaptation minimizes labeled-data needs, replay improves stability under drift at the cost of memory, and compressed representations extend retention when raw data is too large or too sensitive to keep. {#tbl-ondevice-techniques}</p>\n<p>These methods are complementary rather than mutually exclusive, and production systems often combine them to achieve robust, efficient adaptation. A keyword spotting system, for example, may extract compressed audio features (such as MFCCs), finetune a few parameters from a small support set, and maintain a replay buffer of past embeddings for continual refinement.</p>\n<p>Efficient adaptation and data strategies establish how a single device can learn from its user. Sharing those gains requires another decision: whether local updates contain information useful to a common model and can be combined within communication and privacy constraints. Federated learning supplies that coordination protocol. Personal state can remain local when sharing would not improve the population objective, and privacy controls must separately limit what transmitted updates disclose.</p>\n<h2 id=\"sec-24\" class=\"cs-h2\">Federated Learning Algorithms</h2>\n<p>The voice assistant of the chapter's opening, now deployed to millions of homes whose intermittently available devices contribute updates when local conditions permit, shows what local adaptation alone cannot do. One household pronounces \"data\" as \"DAY-tuh\" and another as \"DA-tuh\"; a third, a technical household, says \"machine learning\" every day, while a fourth never has. Local adaptation can specialize each model to its own household, but nothing it learns travels. If the fourth household starts using the phrase, its model must learn it from scratch, even though millions of other devices already handle it. Federation offers that transfer when the observations support a common objective. The system must decide which changes improve shared representations and which should remain personal, then evaluate whether aggregation helps the intended users.</p>\n<p>Federated learning (definition \\ref{dfn-edge-intelligence-federated-learning}) supplies that transfer while each device keeps its raw examples local. The approach turns data locality into one privacy control, not a complete privacy guarantee. A system must still treat gradients, model deltas, participation timing, device identifiers, and aggregate statistics as sensitive outputs because these signals can reveal information about local users [@kairouz2021; @zhu2019deep]. Of the three architectures in @fig-centralized-vs-decentralized, only federated learning pools experience across users without moving raw examples, and it buys that position with a protocol.</p>\n<h3 id=\"sec-25\" class=\"cs-h3\">Cross-device and cross-silo federations</h3>\n<p>Before choosing a federated optimization or privacy protocol, an architect must specify who the participants are, because a mobile cohort-sampling protocol applied to ten collaborating hospitals breaks scheduling, weighting, and fault recovery, and a consortium protocol that expects stable round membership fails on millions of intermittently connected phones. The voice assistant is cross-device, with millions of unreliable phones, whereas a group of hospitals that want to train a complication-prediction model without centralizing patient records is cross-silo, with a few reliable institutions that each hold a large dataset. That distinction changes the failure model, scheduling policy, and privacy unit before any optimizer is selected (@tbl-edge-cross-device-silo) [@kairouz2021].</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Design dimension</strong></th><th><strong>Cross-device federation</strong></th><th><strong>Cross-silo federation</strong></th></tr></thead><tbody>\n<tr><td><strong>Participants</strong></td><td>Large population of intermittently available personal devices</td><td>Small set of known organizations or sites</td></tr>\n<tr><td><strong>Round semantics</strong></td><td>Sample an eligible cohort; expect stragglers and dropouts</td><td>Coordinate a stable membership; investigate missing sites</td></tr>\n<tr><td><strong>Trust boundary</strong></td><td>Treat client software and local data as potentially compromised</td><td>Authenticate institutions, but still isolate each data custodian</td></tr>\n<tr><td><strong>Weighting default</strong></td><td>Decide whether the objective represents examples or users</td><td>Weighting follows the agreed institutional objective, not site size by default</td></tr>\n<tr><td><strong>Privacy unit</strong></td><td>Usually a user or device across its participation history</td><td>Usually a person or record within a site's data, sometimes the site itself</td></tr>\n</tbody></table></div>\n<p>: <strong>Cross-Device and Cross-Silo Federated Learning</strong>: The participant population determines scheduling, trust, weighting, and privacy semantics. A protocol designed for millions of unreliable phones is not automatically appropriate for a consortium of hospitals. {#tbl-edge-cross-device-silo tbl-colwidths=\"[18,41,41]\"}</p>\n<h3 id=\"sec-26\" class=\"cs-h3\">Learning protocols</h3>\n<p>Once the participant population is defined, a federated round must coordinate devices that hold different data distributions, connect over constrained links, and drop out unpredictably. If devices trained on unaligned starting versions and uploaded raw weight tensors whenever they came online, the coordinator would sum incompatible parameter spaces and stall on offline stragglers. Practical distributed coordination protocols must therefore solve three coupled engineering challenges at once, ensuring that local training produces compatible updates despite non-IID data distributions, that aggregation combines those updates efficiently under bandwidth constraints, and that round timing accommodates devices with heterogeneous availability patterns.</p>\n<h4 id=\"sec-27\" class=\"cs-h4\">Local training</h4>\n<p>Local training turns the device's adaptation policy into a contribution to a shared model. Every contribution needs a known starting version, a compatible parameter schema, and a declared local update rule. Otherwise, arrays with the same shape may describe changes to different models. A synchronous protocol therefore starts every participating client from the same shared version, trains on local examples under that rule, and returns the difference from the starting parameters, while personal parameters stay outside the aggregate.</p>\n<p>The process repeats with a new shared version for each accepted round. Update frequency depends on device availability, local work, and communication cost. A secure transmission channel protects the transfer, but the receiving server can still inspect the update unless the aggregation protocol separately hides individual contributions. Model compatibility and update confidentiality are therefore distinct protocol obligations.</p>\n<h4 id=\"sec-27\" class=\"cs-h4\">Federated aggregation protocols</h4>\n<p>The most widely used rule for combining client updates is federated averaging (FedAvg), which has become a canonical algorithm for federated learning [@mcmahan2017communication]. In FedAvg, each device trains its local copy of the model using SGD on its private data. The algorithm is local SGD, which synchronizes only after several local steps to save communication, run with two changes that the data center version never faces. Only a sampled subset of clients participates in each round, and each client's data is a non-IID shard of the population. The local steps that save communication therefore also pull each client toward its own optimum.</p>\n<p>↩ Local SGD and the trade-off between synchronization frequency and convergence that it exposes are established in @sec-distributed-training-systems-systems-distributed-training-efficiency-metrics-9488.</p>\n<p>Formally, let $\\ClientLocalDataset_k$ denote the local dataset on client $\\ClientIndex$, and let $\\ModelParameters_k^\\FederatedRoundIndex$ be the parameters of the model on client $\\ClientIndex$ at round $\\FederatedRoundIndex$. Each client performs $\\LocalEpochCount$ epochs of SGD on its local data, yielding an update $\\ModelParameters_k^{\\FederatedRoundIndex+1}$. The central server then aggregates these updates as: $$ \\ModelParameters^{\\FederatedRoundIndex+1} = \\sum_{k=1}^{\\ParticipatingClientCount} \\frac{\\ClientSampleCount_k}{\\RoundSampleCount} \\ModelParameters_k^{\\FederatedRoundIndex+1} $$ {#eq-fedavg-weighted-aggregation} where $\\ClientSampleCount_k = |\\ClientLocalDataset_k|$ is the number of samples on device $\\ClientIndex$, $\\RoundSampleCount= \\sum_k \\ClientSampleCount_k$ is the total number of samples across participating clients, and $\\ParticipatingClientCount$ is the number of active devices in the current round. Because every client starts from the same shared model and the weights sum to one, averaging the returned models is equivalent to adding the weighted average of the returned differences to the starting model, which is the form the local-training protocol transmits. Bare $\\LocalEpochCount$ counts local epochs; the energy quantities of @eq-edge-background-admission always carry a subscript.</p>\n<p>This formula optimizes an <em>example-weighted</em> objective, in which a client with ten times as many local examples receives ten times the influence. That choice is appropriate when every example should contribute equally, but it can let prolific users or large institutions dominate the model. A <em>user-weighted</em> objective instead assigns each participating client weight $1/\\ParticipatingClientCount$, optionally capping or normalizing each client's local contribution before aggregation. Neither choice is universally fair. The system must declare whether its unit of interest is an example, a user, an organization, or a deployment cohort, then evaluate that population rather than inherit $\\ClientSampleCount_k/\\RoundSampleCount$ as an implementation default.</p>\n<p>A deployed round wraps the averaging rule in policy that the equation leaves unstated (@fig-federated-averaging-cycle). @Eq-fedavg-weighted-aggregation fixes how completed models combine, but not which clients are invited, how long the coordinator waits, or how few completions force a round to be abandoned. Those protocol choices decide which contributions enter the sum. A client that misses the deadline contributes nothing, and its examples are absent from $\\RoundSampleCount$ for that round. Over-selection and its population-coverage trade-off are developed in @sec-edge-intelligence-client-scheduling-f675.</p>\n<p>This basic structure introduces a number of design choices and trade-offs. The number of local epochs $\\LocalEpochCount$ sets the balance between computation and communication. A larger $\\LocalEpochCount$ reduces communication frequency but risks divergence if local data distributions vary too much. The selection of participating clients affects convergence stability and fairness. In real-world deployments, not all devices are available at all times, and hardware capabilities may differ substantially, requiring robust participation scheduling and failure tolerance.</p>\n<p>⇄ <strong>Contrast:</strong> Federated rounds over intermittent wide-area clients contrast with the synchronous AllReduce collectives on low-latency cluster fabrics established in @sec-communication-collective-operations-collective-operations-allreduce-algorithms-7545.</p>\n<h4 id=\"sec-27\" class=\"cs-h4\">Time to target under client drift</h4>\n<p>A federated deployment must reach a quality target within its time, energy, and participation budgets. More local training can reduce how often clients communicate, but it also changes their updates and the time each selected cohort takes to finish. The engineering comparison is therefore time to an agreed quality target, not communication rounds alone.</p>\n<p>##### What the FedAvg controls count {#sec-edge-intelligence-convergence-rate-fundamentals-bfef}</p>\n<p>FedAvg exposes the number of participating clients $\\ParticipatingClientCount$, local epochs $\\LocalEpochCount$, and communication rounds $\\FederatedRoundCount$ as controls [@mcmahan2017communication]. Their product $\\ParticipatingClientCount \\LocalEpochCount \\FederatedRoundCount$ counts client-epochs when participation is fixed, which makes it a tally of the work a run performs rather than a measure of its progress. Clients can have different dataset sizes, and equal client-epoch counts can process different examples or produce conflicting updates, so two runs with the same $\\ParticipatingClientCount \\LocalEpochCount \\FederatedRoundCount$ can end at very different quality. A convergence result is useful only when its assumptions match the optimizer, client sampling, and data distributions.</p>\n<p>##### Non-IID data impact {#sec-edge-intelligence-noniid-data-impact-d8b9}</p>\n<p>Non-IID data is where federated averaging departs from the data center version of local SGD. Each local step moves a client toward the optimum of its own shard. After many local steps the client models sit near different optima, and their weighted average lands at a point that need not minimize the population objective. This client drift grows with the number of local steps and with how far the client distributions differ, and it degrades federated averaging relative to i.i.d. baselines [@li2020; @zhao2018federated]. It therefore eats into the benefit of fewer communications exactly where communication is most expensive. How strongly depends on the partition, update rule, participation policy, and local step size. No universal heterogeneity score predicts a round count across applications, which is why @sec-edge-intelligence-quantifying-heterogeneity-practice-eece measures the trade-off rather than computing it.</p>\n<p>When statistical heterogeneity causes FedAvg to diverge or stall, two foundational algorithmic extensions address the root cause of client drift:</p>\n<ol class=\"cs-list\">\n<li><strong>FedProx</strong> [@li2020] adds a proximal penalty proportional to $\\|\\ModelParameters - \\GlobalModelParameters^{\\FederatedRoundIndex}\\|^2$ to each client's local loss function. This penalty constrains local updates to remain in the neighborhood of the current global model $\\GlobalModelParameters^{\\FederatedRoundIndex}$, stabilizing convergence under statistical heterogeneity and permitting devices to execute variable numbers of local epochs without destabilizing the server aggregate.</li>\n<li><strong>SCAFFOLD</strong> [@kairouz2021] corrects the local update direction directly using control variates. It maintains a server control variate and per-client control variates that estimate the difference between client-local and global gradient directions, applying an additive correction to each local SGD step. Each step subtracts the client's own control variate and adds the server's, so the client moves along the estimated global direction rather than the direction its local data favors. This correction counters client drift under heterogeneous local data, although it roughly doubles the communication volume per round by transmitting control variates alongside model parameters. Each client's control variate is useful only when that client returns, so the method suits cross-silo federations better than cross-device rounds that rarely sample the same device twice.</li>\n</ol>\n<p>##### Measuring the local-work trade-off {#sec-edge-intelligence-quantifying-heterogeneity-practice-eece}</p>\n<p>Compare candidate local-epoch settings under the same initialization, data partition, participation policy, and held-out quality target. For each setting $\\LocalEpochCount$, record the first validated round $\\FederatedRoundCount(\\LocalEpochCount)$ that reaches the target and the elapsed duration $\\RoundDuration(\\LocalEpochCount)$ of each completed round, including client selection, local work, transfer, aggregation, and any waiting. The observed time to target is</p>\n<p>$$ \\TimeToTarget(\\LocalEpochCount) = \\sum_{\\CompletedRoundIndex=1}^{\\FederatedRoundCount(\\LocalEpochCount)} \\RoundDuration(\\LocalEpochCount). $$</p>\n<p>Each $\\RoundDuration(\\LocalEpochCount)$ is one instance of the round budget sketched at the opening of the chapter. Read through the Fleet Law, it is the local training on the slowest client the round still awaits, plus the upload, plus the wait for enough reports, less whatever overlaps. The communication piece is easy to estimate. Over a constrained mobile uplink of <code>[EdgeRoundUploadTime.uplink_range_str]</code>, the chapter's reference adapter update of <code>[EdgeAdaptationTierProfile.federated_lora_update_mb_str]</code> takes about <code>[EdgeRoundUploadTime.upload_slow_min_str]</code> to upload at the low end and about <code>[EdgeRoundUploadTime.upload_fast_s_str]</code> at the high end. That cost recurs in every one of the $\\FederatedRoundCount(\\LocalEpochCount)$ rounds. A setting of $\\LocalEpochCount$ that halves $\\FederatedRoundCount(\\LocalEpochCount)$ therefore removes half of the cumulative upload time. It pays off only if the extra local training it adds to each round, on the slowest awaited client, costs less than the uploads it removes. Client drift keeps that comparison from being settled on paper, because more local steps can also raise $\\FederatedRoundCount(\\LocalEpochCount)$, and only measured runs can rank the settings.</p>\n<p>A useful experiment log records local epochs, completed clients, rounds to target, elapsed time, transmitted bytes, and device energy. If a run never reaches the quality target within the budget, report that outcome rather than extrapolating an invented convergence curve. Repeated runs and cohort-level validation distinguish a stable improvement from a fortunate sample of participating devices.</p>\n<p>##### Communication-computation trade-off {#sec-edge-intelligence-communicationcomputation-tradeoff-6e31}</p>\n<p>@Fig-comm-compute-tradeoff draws the two opposing paths of local work $\\LocalEpochCount$ as a timeline of rounds. Each round's width is its duration $\\RoundDuration(\\LocalEpochCount)$, each row's round count is $\\FederatedRoundCount(\\LocalEpochCount)$, and each row ends at its time to target $\\TimeToTarget(\\LocalEpochCount)$. Drift adds a round to the large-$\\LocalEpochCount$ row, and the moderate row finishes first. The large-$\\LocalEpochCount$ row needs half the rounds of the small-$\\LocalEpochCount$ row yet finishes last, so a setting that requires fewer rounds can still prolong total wall-clock duration. A setting remains admissible only if its total consumption also fits within client energy and fleet-coverage budgets.</p>\n<p>The operating point depends on the deployment. Larger local updates can amortize transfer overhead, but they also change drift, completion time, and which clients finish. The network alone can move the optimum, as a cost model in relative units shows (@fig-fl-communication-computation). Its minimum $\\LocalEpochCount^*$ shifts from $\\LocalEpochCount=10$ on the fast-network curve to $\\LocalEpochCount=40$ on the slow-network curve because amortizing expensive transfers justifies more local work. These curves are not measured convergence results. A deployment must establish whether additional local work actually reduces time to target after drift and client completion are counted, and adaptive epoch policies need the same outcome and coverage checks as fixed settings.</p>\n<p>##### Diagnosing a missed target {#sec-edge-intelligence-federated-learning-work-93a2}</p>\n<p>Federated convergence results depend on the update rule, objective, sampling policy, and assumptions about client data [@kairouz2021]. Heterogeneity, participation, and local sample counts are therefore inputs to a feasibility assessment, not universal pass/fail thresholds. A deployment must demonstrate that its chosen configuration reaches the declared quality target within time and device budgets, with evaluation that represents the intended population.</p>\n<p>When a configuration misses that target, the measured failure guides the next experiment. Conflicting local updates motivate testing less local work, adding proximal regularization (FedProx), incorporating control variates (SCAFFOLD), or switching to personalization. Long waits motivate scheduling or asynchronous alternatives, subject to privacy-protocol compatibility. Sparse local evidence motivates bounded adaptation and stronger validation. None of these changes replaces observations from absent cohorts; each must be reevaluated for quality, resource cost, and population coverage.</p>\n<p>The aggregation rule specifies how compatible local models produce a shared model. The measured time to target establishes whether a configuration reaches its objective within budget. A controlled lab can hold participant availability and network conditions steady. A phone fleet cannot, so the implementation must define how selection, deadlines, and failures change the set of updates that actually enters each aggregate. These protocol decisions connect learning behavior to fleet orchestration.</p>\n<h2 id=\"sec-27\" class=\"cs-h2\">Federated Learning Systems at Scale</h2>\n<p>A round selects a cohort from the deployment population, but some selected devices overheat, lose Wi-Fi, enter power-saving mode, or power off before returning an update. A fleet of millions of smartphones need not participate in one round for these failures to matter. Turning the FedAvg protocol into a production fleet system requires deciding which clients are eligible and how long to wait, compressing updates to fit constrained uplinks, separating personal state from shared weights, enforcing cryptographic and statistical privacy bounds, and reconciling asynchronous updates across heterogeneous hardware.</p>\n<h3 id=\"sec-28\" class=\"cs-h3\">Client scheduling</h3>\n<p>The first decision in any round is which devices to invite. Sampling devices uniformly at random without checking their power and network state would interrupt users mid-task, whereas accepting updates only from plugged-in flagship phones on fast Wi-Fi trains a global model skewed toward affluent, overnight-charging cohorts. Because real-world client availability shifts continuously with battery state, charging habits, and network coverage, client scheduling governs both the completion speed and the population coverage of distributed learning.</p>\n<p>At a baseline level, federated ML systems define eligibility criteria for participation. A mobile deployment may require devices to be plugged in, connected to Wi-Fi, and idle to limit interference with foreground work and battery use. The chosen criteria determine which subset of the total population is considered \"available\" for a training round; they are deployment policy rather than requirements of federated learning itself.</p>\n<p>Beyond these operational filters, devices also differ in their hardware capabilities, data availability, and network conditions. Some smartphones contain many recent examples relevant to the current task, while others have outdated or irrelevant data. Network bandwidth and upload speed may vary widely depending on geography and carrier infrastructure. As a result, uniform random selection from the eligible pool does not guarantee coverage of the full deployment population; eligibility has already excluded some devices and their data.</p>\n<p>Availability-driven selection introduces participation bias, the fleet-level consequence of the admission test in @eq-edge-background-admission (principle \\ref{pri-participation-selects-population}). Clients with favorable conditions, such as frequent charging, high-end hardware, and consistent connectivity, pass admission and participate repeatedly, while others are systematically underrepresented. This can skew the resulting model toward behaviors and preferences of a privileged subset of the population, raising both fairness and generalization concerns.</p>\n<p>Participation bias becomes severe when a small eligible cohort supplies most completed updates while other cohorts rarely participate. The skew is measured per cohort as a coverage ratio, the cohort's share of completed updates divided by its share of the deployed population. A ratio near one means the cohort is represented in proportion to its size, and a ratio well below one means the shared model learns that cohort's behavior at less than its population weight. Completion logs supply the numerator and the deployment inventory the denominator, so the ratio can be computed without inspecting any update. The admission test and the round deadline both remove constrained devices faster than capable ones. Uniform selection among admitted devices passes the resulting skew through unchanged, so a budget cohort can fall from a fifth of the fleet to a sliver of the completed updates (@fig-participation-coverage-funnel).</p>\n<p>Low coverage also feeds itself, because models become more strongly optimized for users with high-end devices and stable connectivity, potentially degrading performance for resource-constrained users who need adaptation the most. A keyboard prediction model might become biased toward the typing patterns of users with flagship phones who charge overnight, missing important linguistic variations from users with budget devices or irregular charging patterns.</p>\n<p>The order of these decisions limits what any remedy can do. Fleet orchestration admits only feasible allocations before a fairness policy divides them (principle \\ref{pri-feasibility-before-fairness}), and a federated scheduler inherits the same order with a sharper consequence. Its eligibility filter fixes the candidate pool, so a fairness policy can redistribute rounds only among devices the admission test already accepted; a device that never qualifies is invisible to it.</p>\n<p>Scheduling must therefore balance completion speed with population coverage. Stratified or quota-based sampling can prioritize underrepresented groups among eligible devices, while cumulative participation records can guide later invitations. Weighting methods require estimates of the population and selection process; they cannot recover observations from a cohort that never participates. Buffered asynchronous aggregation [@fedbuff], whose mechanism @sec-edge-intelligence-asynchronous-device-synchronization-348e describes, staleness-aware methods [@rodio2024], and fairness-oriented weighting [@fedstaleweight] offer additional controls. Their effectiveness must be checked through completed participation and cohort quality, rather than inferred from the scheduling rule alone. Example weighting in the aggregate (@eq-fedavg-weighted-aggregation) also gives large local datasets more influence whether or not they represent the target population any better.</p>\n<p>Scheduling must also bound how long a round waits on its slowest participants. Network latency, battery depletion, or background process contention can make some devices (stragglers) take 10$\\times$ longer than the median, and the round cannot aggregate until enough updates arrive.</p>\n<p>To reduce waiting for stragglers, production federated learning (FL) systems employ <strong>over-selection</strong>. The server selects a candidate pool size $\\CandidateClientCount$ larger than the target number of updates $\\TargetUpdateCount$ (the production system of @bonawitz2019towards selects about 130 percent of the target, $\\CandidateClientCount \\approx 1.3 \\times \\TargetUpdateCount$). When enough valid reports arrive, the server can form an aggregate from $\\TargetUpdateCount$ completed updates rather than wait for every selected device. Completion then depends on how quickly the target number of valid reports arrives, but over-selection alone does not guarantee that the target is reached. A round deadline and an explicit acceptance or abandonment rule handle insufficient completion. Secure aggregation adds a participation floor and dropout recovery (@sec-edge-intelligence-federated-privacy-a1ed); selecting the fastest reports must remain compatible with that protocol. Accepting the first reports to arrive discards those of the slowest selected devices, which are disproportionately the constrained cohorts that admission already thinned, so over-selection with a round deadline can concentrate the participation bias just described. Shorter rounds must therefore be evaluated against cohort coverage and wall-clock time to the declared quality target. Because these scheduling decisions set convergence rate, model generalization, energy consumption, and user experience together, poor scheduling produces excessive stragglers, overfitting to narrow client segments, or wasted computation.</p>\n<h3 id=\"sec-29\" class=\"cs-h3\">Bandwidth-aware update compression</h3>\n<p>Many of the stragglers that miss a round deadline fail on the network transfer rather than on local computation: transmitting full-precision weights or gradients over an asymmetric mobile uplink can exhaust a client's connectivity window or battery allowance before its update ever reaches the coordinator. Update compression therefore begins with a bottleneck diagnosis: when transfer is limiting, the design decision is which information to quantize, sparsify, or keep local. The smaller payload must then be evaluated against encoding cost, update error, and the rounds required to reach the quality target.</p>\n<p>: <strong>Wireless upload asymmetry</strong>: Federated updates use the uplink, whose available throughput can differ substantially from the downlink and vary with coverage and contention. Transfer time depends on encoded update size and effective uplink goodput; energy also depends on radio state and transfer duration. Low-power links may add duty-cycle constraints. Compression is useful when these costs bind the update budget, but its necessity depends on the payload, link, and permitted synchronization interval.</p>\n<p>The compression decision separates into three levers, each changing a different part of the communication bottleneck: model compression reduces bits per update, selective sharing reduces which parameters travel, and architectural partitioning keeps some state local. Model compression methods reduce the wire footprint of transmitted updates through quantization, sparsification, or subsampling. Instead of sending full-precision gradients, a client transmits 8-bit quantized updates or communicates only the top-$\\RetainedGradientElementCount$ gradient elements with highest magnitude, the same encodings that cluster training applies to its collective payloads. At the edge they bind in a different place. They act on a slow, asymmetric uplink rather than a fabric, under secure aggregation that must still combine the encoded updates, and inside a per-round communication total (@eq-edge-federated-communication-volume) that also counts downloads and retries. These transformations are communication mechanisms, not privacy mechanisms; a smaller embedding, sparse update, or low-precision gradient may still expose membership, attributes, or reconstructable features.</p>\n<p>: <strong>Gradient sparsification</strong>: Selecting the largest 1--10 percent of gradient elements by magnitude reduces transmitted value count by 10--100$\\times$ before coordinate indices and other metadata are included. Sparsified SGD and deep gradient compression retain untransmitted residuals for later updates rather than assuming that small components can be discarded permanently [@stich2018sparsified; @lin2018deep]. Wire-byte savings depend on the encoding, while convergence depends on the residual handling, optimizer, and compression schedule; a value-count reduction alone establishes neither.</p>\n<p>↩ Gradient quantization, top-$\\Glyph{k}$ sparsification, and error feedback that carries unsent updates forward are established in @sec-communication-collective-operations-collective-operations-gradient-compression-7a5c. Convergence depends on the optimizer and compression assumptions.</p>\n<p>Selective update sharing further reduces communication by transmitting only subsets of model parameters or updates. In layer-wise selective sharing, clients update only certain layers, typically the final classifier or adapter modules, while keeping the majority of the backbone frozen. This reduces the update payload and limits which shared representations can change, but the trainable subset can still overfit nonrepresentative client data.</p>\n<p>Architectural partitioning requires specifying what crosses the boundary. A personal/shared parameter partition keeps local modules private while aggregating selected shared parameters. Split learning instead divides execution between client and server, exchanging intermediate activations and backward gradients at the cut. These designs have different traffic and exposure patterns; neither guarantees a communication reduction or privacy merely by dividing the model.</p>\n<p>These approaches can use the FedAvg aggregation protocol (@sec-edge-intelligence-federated-aggregation-protocols-5d37) only when their encoding and shared parameter schema support weighted aggregation. Under secure aggregation, which sums masked updates without inspecting them, weighted aggregation also requires every client to share one quantization scale and one coordinate template for sparse values (@sec-edge-intelligence-federated-privacy-a1ed). Local-only parameters must stay outside the shared aggregate altogether.</p>\n<p>Whatever the encoding, the total communication volume for round $\\CompletedRoundIndex$ is</p>\n<p>$$ \\RoundCommunicationVolume= \\RoundDownloadVolume+ \\RoundUploadVolume+ \\RoundProtocolVolume+ \\RoundRetryVolume, $$ {#eq-edge-federated-communication-volume}</p>\n<p>@Eq-edge-federated-communication-volume makes download, upload, protocol, and retry traffic explicit. The download distributes model state, the upload carries client updates, protocol traffic covers authentication and cryptographic setup, and retries account for failed or repeated transfers. Optimizing only $\\RoundUploadVolume$ can therefore move rather than remove the bottleneck. Additional local computation amortizes network transfers, and each communication-efficient alternative to it carries its own cost. Compression may degrade gradient fidelity, selective updates can limit model capacity, and split architectures complicate coordination. Summed over a training run, the upload term alone can exceed the raw data that federation was meant to keep local, even when each update is far smaller than that data.</p>\n<p>↪ The break-even condition under which encoding and decoding time costs less than the transfer time compression saves is developed, with a worked example, in @sec-appdx-comm-foundations-compression.</p>\n<p><strong>Problem</strong>: A team is designing a federated camera-personalization system that learns from <code>[FederatedSavings.fs_raw_data_mb_str]</code> of compressed user images per week. Compare one upload of those images with one compressed model-update uplink round.</p>\n<p><strong>Math</strong>: Bandwidth efficiency is the ratio of raw data volume to model update size.</p>\n<ol class=\"cs-list\">\n<li><strong>Raw data upload</strong>: <code>[FederatedSavings.fs_raw_data_mb_str]</code>/week.</li>\n<li><strong>One federated uplink round</strong>: A compressed model update (5M params) is <code>[FederatedSavings.fs_update_mb_str]</code>.</li>\n<li><strong>One-round uplink reduction</strong>: <code>[FederatedSavings.fs_raw_data_mb_str]</code>/<code>[FederatedSavings.fs_update_mb_str]</code> = <code>[FederatedSavings.fs_reduction_mult_str]</code>.</li>\n</ol>\n<p><strong>Systems insight</strong>: For this scenario, one <code>[FederatedSavings.fs_update_mb_str]</code> uplink is <code>[FederatedSavings.fs_reduction_mult_str]</code> smaller than one <code>[FederatedSavings.fs_raw_data_mb_str]</code> raw-data upload. That ratio is not the end-to-end communication saving of a training run: after roughly <code>[FederatedSavings.fs_reduction_mult_str]</code> uplink rounds, cumulative update uploads alone equal the raw-data volume, before counting global-model downloads, retries, or protocol overhead. The verdict therefore turns on the round schedule. A deployment that runs one round per day uploads seven updates per week of data, far below the break-even count, and saves most of the uplink traffic. One that runs a round every hour uploads 168 updates per week, more than the break-even count, and moves more bytes than shipping the images would. Per-round traffic must be multiplied by the expected round count before federation can claim a bandwidth saving.</p>\n<p>The local-work schedule and update encoding jointly determine communication cost. @Fig-gradient-compression compares uncompressed 32-bit values (Panel A) with uniform 8-bit quantization (Panel B), which gives a $4\\times$ reduction in value bytes before scales and other metadata are counted. Top-$\\Glyph{k}$ sparsification with retained error feedback (Panel C) must encode coordinate identities as well as selected values. Error feedback retains one residual value per update coordinate between transmissions. Its storage depends on the update size and residual precision and must fit the device allowance alongside training and replay state. The receiving path must reconstruct or aggregate these encodings consistently, with separate compatibility requirements when secure aggregation hides individual updates.</p>\n<p>The quantization panel (Panel B) is labeled \"zero client state\" because it keeps no persistent error-feedback residual; encoding buffers, scales, and temporary workspace still enter the device budget. Compression is useful when its reduction in total communication outweighs encoding work and any extra rounds needed to reach the quality target. A smaller upload helps a round only if transfer was what made clients miss the deadline or excluded a cohort, and the round's completion logs show which. Smaller payloads can let clients on slow or congested uplinks finish before their resource window closes, so compression is judged by completed participation and cohort outcomes, not by bytes saved alone. Even when transfer becomes feasible, the shared model may still fail to capture local variation.</p>\n<h3 id=\"sec-30\" class=\"cs-h3\">Federated personalization</h3>\n<p>Compressing updates lets more devices finish a round, but clients that complete compatible updates can still pull the shared model in opposite directions when a dialect phrase, a regional keyboard shortcut, or an individual's wrist-worn sensor placement conflicts with the population mean. A single global model may serve the average user adequately while concealing persistent accuracy losses for specific cohorts. Personalized federated learning retains shared representation learning while allowing selected parameters or models to specialize locally, trading added local state, training cost, and overfitting risk on sparse user data against per-user quality.</p>\n<p>Let $\\ModelParameters_k$ denote the model parameters on client $\\ClientIndex$, and $\\GlobalModelParameters$ the aggregated global model. For $\\ParticipatingClientCount$ clients, counted as in @eq-fedavg-weighted-aggregation, traditional FL seeks to minimize a global objective: $$ \\min_\\ModelParameters\\sum_{k=1}^{\\ParticipatingClientCount} \\ClientObjectiveWeight_k \\LossFunction_k(\\ModelParameters) $$ where $\\LossFunction_k(\\ModelParameters)$ is the local loss on client $\\ClientIndex$, and $\\ClientObjectiveWeight_k$ is a weighting factor (e.g., proportional to local dataset size). This formulation optimizes the weighted average loss of a shared model $\\ModelParameters$; it does not guarantee acceptable performance for every client. Local loss landscapes $\\LossFunction_k$ can differ across clients, reflecting non-IID data distributions and varying task requirements.</p>\n<p>Personalization modifies this objective to allow each client to maintain its own adapted parameters $\\ModelParameters_k$, optimized with respect to both the global model and local data: $$ \\min_{\\ModelParameters_1, \\ldots, \\ModelParameters_{\\ParticipatingClientCount}} \\sum_{k=1}^{\\ParticipatingClientCount} \\left( \\LossFunction_k(\\ModelParameters_k) + \\PersonalizationPenaltyWeight\\cdot \\GlobalDeviationPenalty(\\ModelParameters_k, \\GlobalModelParameters) \\right) $$</p>\n<p>Here, $\\GlobalDeviationPenalty$ penalizes deviation from the global model, for example with the squared distance that FedProx adds to each local loss, and $\\PersonalizationPenaltyWeight$ controls the strength of that penalty. The per-client parameters $\\ModelParameters_k$ are thus state that the plain federated objective does not have, held near the shared model by the penalty rather than trained on local data alone. The displayed objective describes local specialization around a given global reference; a complete protocol must additionally specify how that reference is trained and refreshed. The penalty trades local fit against proximity to the shared model, without guaranteeing improvement for every client.</p>\n<p>In a wearable health monitor that classifies physical activities from physiological signals, this objective separates shared motion features from individual gait signatures, resting baselines, and sensor placements. Finetuning the final classification layer or low-rank adapters around the global reference $\\GlobalModelParameters$ addresses those user-specific differences, provided evaluation establishes that the local examples actually improve accuracy on rare activity classes with little supervision.</p>\n<p>Several personalization strategies address the trade-offs between compute overhead, information exposure, and adaptation speed. One widely used approach is local finetuning, in which each client downloads the latest global model and performs a small number of gradient steps using its local data. This method avoids transmitting those examples during adaptation, but the resulting local state and any later update remain privacy-sensitive. It may also yield suboptimal results when the global model is poorly aligned with the client's data distribution or when the local dataset is extremely limited.</p>\n<p>Another effective technique involves personalization layers, where the model is partitioned into a shared backbone and a lightweight, client-specific head, typically the final classification layer [@arivazhagan2019federated]. One such method, FedPer, has clients train both the shared base and their personal head, but only the shared base participates in server aggregation; the head remains local. A separate head-only adaptation policy can freeze a downloaded backbone to reduce local training cost when the relevant variation lies mainly in output categories or decision boundaries.</p>\n<p>Clustered federated learning offers an alternative by grouping clients according to similarities in their data or performance characteristics, and training separate models for each cluster. This strategy can enhance accuracy within homogeneous subpopulations, though it introduces additional system complexity and may require exchanging metadata to determine group membership.</p>\n<p>Rather than maintaining separate cluster models, meta-learning approaches, such as model-agnostic meta-learning (MAML), aim to produce a single global model initialization that can be quickly adapted to new tasks with a few local updates [@finn2017model]. A meta-learned initialization is especially useful when clients have limited data or operate in environments with frequent distributional shifts.</p>\n<p>: <strong>MAML (model-agnostic meta-learning)</strong>: @finn2017model optimize for a model initialization from which one or a few gradient steps can yield good performance on a new task, with experiments including one-shot and few-shot settings. Meta-training is more expensive than ordinary finetuning because it differentiates through the adaptation process, but deployment adaptation can be limited to a small number of local updates. This makes MAML relevant for edge scenarios where inference compute is cheap but training data is scarce.</p>\n<p>Each strategy occupies a different point in the personalization trade-off space. Local finetuning, personalization layers, clustered federated learning, and meta-learning differ in compute overhead, information exposure, and adaptation latency (@tbl-personalization-strategies). The mechanism determines what state is shared; a privacy guarantee requires separately specified controls and assumptions.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Strategy</strong></th><th><strong>Personalization mechanism</strong></th><th><strong>Compute overhead</strong></th><th><strong>Privacy preservation</strong></th><th><strong>Adaptation speed</strong></th></tr></thead><tbody>\n<tr><td><strong>Local Finetuning</strong></td><td>Gradient descent on local loss postaggregation</td><td>Low to Moderate</td><td>Raw examples stay local; adapted state remains sensitive</td><td>Fast (few steps)</td></tr>\n<tr><td><strong>Personalization Layers</strong></td><td>Split model: shared base + user-specific head</td><td>Moderate</td><td>Narrows shared state; does not guarantee privacy</td><td>Fast (train small head)</td></tr>\n<tr><td><strong>Clustered FL</strong></td><td>Group clients by data similarity, train per group</td><td>Moderate to High</td><td>Group membership and updates can leak attributes</td><td>Medium</td></tr>\n<tr><td><strong>Meta-Learning</strong></td><td>Train for fast adaptation across tasks/devices</td><td>High (meta-objective)</td><td>Depends on meta-training and adaptation protocol</td><td>Very Fast (few-shot)</td></tr>\n</tbody></table></div>\n<p>: <strong>Personalization Trade-Offs</strong>: Federated learning strategies balance personalization with compute, information exposure, and adaptation latency. Data locality narrows exposure but does not by itself provide a privacy guarantee. {#tbl-personalization-strategies}</p>\n<p>Selecting an on-device personalization strategy requires balancing adaptation capacity against memory residency. Three fine-tuning paradigms differ in structural footprint (@fig-personalization-arch). Full fine-tuning updates every backbone layer (Column A), head-only adaptation freezes the feature extractor (Column B), and parameter-efficient adapters sit beside frozen backbone blocks (Column C).</p>\n<p>The dashed backward-pass arrows in @fig-personalization-arch are the activation term of @eq-edge-adaptation-peak-memory drawn as distance. Adapters at early layers in Column C pull the backward path through the later backbone, whose saved state must be retained or recomputed, while head-only adaptation in Column B ends it at the head, as in the wake-word case of @sec-edge-intelligence-fewshot-learning-data-streaming-566e. Placement sets the dependency path, and the execution schedule sets how much of that state stays resident. Keeping the personal head or adapter on the device also narrows what crosses the device boundary, but the shared backbone updates that still leave the client remain derived from private local examples and require explicit privacy protection.</p>\n<h3 id=\"sec-31\" class=\"cs-h3\">Federated privacy</h3>\n<p>Even when personal parameters and raw training examples never leave the phone, an adversary or curious server that inspects an uploaded gradient or weight delta $\\FiniteChange\\ModelParameters$ can reconstruct typed text, recover facial features, or determine whether a specific phrase appeared in a user's local dataset. Model inversion attacks and membership inference attacks exploit the fact that transmitted updates encode the very examples that produced them.</p>\n<p>: <strong>Model inversion attack</strong>: Reconstructs training data from model outputs or gradients by optimizing inputs that maximize confidence scores [@fredrikson2015; @zhu2019deep]. In federated learning, gradient updates can leak more information than model outputs alone because they expose training-step information directly. Defenses such as gradient perturbation, secure aggregation, and differential privacy add protocol, utility, communication, or compute trade-offs whose magnitude depends on the threat model and deployment; @sec-security-privacy-gradient-inversion-risks-d2c1 develops the threat model for these attacks.</p>\n<p>Two protective measures address that leakage. <strong>Secure aggregation</strong> protocols reveal a combined result while hiding individual updates beyond what that result itself reveals, subject to the protocol's assumptions about collusion and participating clients. Differential privacy, a formal bound on how much any one protected user's or record's inclusion can change a released result, is obtained by clipping each contribution and adding noise calibrated to that bound. The deployment must specify which unit receives that protection.</p>\n<p>: <strong>Secure aggregation</strong>: Cryptographic protocol where client pairs exchange random masks that cancel in the server-side sum, revealing only the aggregate gradient without exposing individual contributions [@bonawitz2017]. Production-scale federated systems such as Gboard combine secure aggregation with eligibility checks, drop-out handling, and round scheduling [@bonawitz2019towards]. The communication expansion and minimum-participation requirements depend on protocol parameters and the security model, so aggregation systems must wait for enough eligible devices before releasing a round.</p>\n<p>These controls solve different problems. Secure aggregation limits what the coordinator learns about each submitted update, whereas differential privacy bounds how much a declared privacy unit can affect a released result. A deployment therefore needs a privacy accounting log that records the unit of protection, clipping rule, noise mechanism, sampling assumptions, $(\\PrivacyBudget,\\PrivacyAdditiveSlack)$ expenditure for every release, and cumulative composition across training and federated analytics [@abadi2016deep; @kairouz2021]. Clipping bounds each contribution before noise is calibrated. The parameters $\\PrivacyBudget$ and $\\PrivacyAdditiveSlack$ describe the permitted change in output probabilities when the protected user or record is included or removed; composition accounts for repeated releases involving that unit. Resetting a round counter does not reset privacy loss for a user who participates again.</p>\n<p>↪ The composition rules that turn a privacy accounting log's per-release entries into one cumulative privacy budget are developed in @sec-security-privacy-privacy-budget-composition-edbe.</p>\n<p>@Fig-secure-agg models this cryptographic boundary through pairwise zero-sum masking. Clients A and B negotiate a shared random mask $\\PairwiseMaskSecret$ via Diffie-Hellman key agreement, which lets the two clients derive the same secret from public values that the server relays but cannot use to compute it. They perturb their local updates into pseudo-random vectors ($\\FirstClientMaskedUpdate = \\FiniteChange\\FirstClientModelParameters+ \\PairwiseMaskSecret$ and $\\SecondClientMaskedUpdate = \\FiniteChange\\SecondClientModelParameters- \\PairwiseMaskSecret$) before crossing into the server domain. When the aggregation server sums the received vectors, the symmetric masks cancel ($\\PairwiseMaskSecret - \\PairwiseMaskSecret = 0$), yielding the exact unmasked aggregate $\\FiniteChange\\FirstClientModelParameters+ \\FiniteChange\\SecondClientModelParameters$. This two-client illustration assumes both clients complete the exchange and neither reveals its mask to the server. It demonstrates cancellation, not a complete protocol for collusion resistance or dropout recovery.</p>\n<p>A real round has many clients, and some drop out after agreeing on masks but before uploading. Each dropped client leaves its pairwise masks uncancelled in the sum. The full protocol therefore has every client split the secret seeds of its masks into shares held by the other clients, and any threshold number of those shares can rebuild a seed [@bonawitz2017]. After the upload deadline, surviving clients send the shares of the dropped clients' seeds, and the server regenerates and subtracts the dangling masks. Recovery therefore costs an extra message round and computation that grows with the number of dropouts, and it succeeds only if at least the threshold number of clients survive; otherwise the round is abandoned. Over-selection adds to this cost. A client that completed key agreement but whose report the coordinator discards once the target count arrives is a dropout to the protocol, so every discarded report adds recovery work, and the clients kept must still clear the threshold.</p>\n<p>That threshold is one reason for a participation floor. The other is the sum itself, because an aggregate over a few clients reveals too much about each of them. The coordinator must therefore invite enough clients that the expected survivors clear the floor, and a cohort that falls short is held for a later round rather than aggregated.</p>\n<p>Masking also constrains how clients encode their updates (@sec-edge-intelligence-bandwidthaware-update-compression-7730). With cleartext uploads, the server can dequantize each client's tensor with that client's scale factor and scatter sparse index-value pairs into a dense buffer before summing. Under secure aggregation the masks are added in modular integer arithmetic, so each upload is a fixed-point integer vector, and the server sums these masked vectors element by element without inspecting individual uploads. Clients that quantize updates must therefore quantize to a shared fixed-point scale so their masked integers represent the same unit at every coordinate, and clients that sparsify updates must project onto a shared coordinate template or sketch rather than uploading client-specific index lists that would fail to align and would reveal which parameters changed.</p>\n<p>Secure aggregation also creates a robustness conflict. Byzantine-resilient rules such as Krum, coordinate-wise filtering, or per-client anomaly inspection need access to individual updates, while secure aggregation deliberately hides those updates [@blanchard2017machine; @bonawitz2017]. A system cannot claim both arbitrary per-client inspection and conventional secure aggregation over the same messages. It must instead validate clients before masking, use attested execution and bounded local updates, compute only aggregation-compatible checks, or adopt a protocol designed to evaluate approved robust statistics without revealing raw client contributions.</p>\n<p>↩ Byzantine failures, in which a worker stays alive but returns wrong results, and aggregation rules such as Krum and trimmed mean that bound their influence are established in @sec-fault-tolerance-reliability-reliability-byzantine-failures-8a24.</p>\n<p>Secure aggregation and differential privacy can protect different boundaries, but their composition must follow the threat model. If a trusted server adds noise after receiving an exact aggregate, the privacy guarantee applies to the released noisy result; it does not hide that exact aggregate from the server. A protocol designed for distributed noise can instead let the server receive only a noisy aggregate. Clipping, noise calibration, dropout assumptions, and repeated-release accounting must match the chosen protocol. Neither mechanism establishes that local data or updates are trustworthy.</p>\n<p>Consider architecting a federated learning system for a fleet of 10 million mobile devices. The data is highly non-IID (users have distinct, clustered typing patterns), and the network environment is constrained (<code>[EdgeRoundUploadTime.uplink_range_str]</code>). Before choosing optimizations for this scenario, classify the local bottlenecks and state which system constraint dominates each decision.</p>\n<p>Consider three design decisions:</p>\n<ol class=\"cs-list\">\n<li>Aggregation: Select plain FedAvg, reduced local epochs, or personalization/clustering for the non-IID population, and justify how the choice controls client drift.</li>\n<li>Privacy: Decide whether the deployment needs formal differential-privacy noise or whether secure aggregation and data minimization are sufficient for the stated threat model. Using the clipping and noise described in this section, explain how noise can affect utility and rounds to the same quality target, and what measurements would establish that cost.</li>\n<li>Communication: Choose between gradient quantization (e.g., 8-bit) and structured sparsity under constrained bandwidth, and justify the bandwidth/accuracy trade-off.</li>\n</ol>\n<h3 id=\"sec-32\" class=\"cs-h3\">Large-scale device orchestration</h3>\n<p>Because privacy mechanisms hide individual updates without verifying their integrity, a fleet coordinator must pair those cryptographic and statistical bounds with runtime orchestration across untrusted, intermittently available hardware. A round that selects a million phones overnight will see some fraction overheat, lose connectivity, or be unplugged before they report, and a few may submit corrupted or deliberately malicious updates. Coordinating that population requires protocols that handle Byzantine clients, network partitions that temporarily cut participants off, and constrained communication. These challenges differ from controlled data center training, where high-bandwidth networks and managed infrastructure narrow the trust and availability envelope.</p>\n<h4 id=\"sec-33\" class=\"cs-h4\">Asynchronous device synchronization</h4>\n<p>Federated learning inherits failures from distributed systems and machine learning, but its coordination objective is not consensus, the problem of making replicated servers agree on one ordered log of operations. Federated clients agree on no such log. A coordinator instead decides which stochastic client updates are eligible, how stale updates are weighted, and which aggregation rule can tolerate faulty participants without letting them steer the model. Devices crash, lose power, or disconnect during rounds, while compromised clients can submit poisoned updates crafted to push the shared model toward an attacker's goal. Robust aggregation can reduce the influence of some faulty participants, but its assumptions, compute cost, and compatibility with secure aggregation must be explicit.</p>\n<p>The trust chain begins before aggregation. A production coordinator authenticates the device and application instance, verifies the signed model and training-policy version, checks eligibility and freshness, binds the returned update to that version and round nonce, and records whether the update passed protocol-level bounds. Hardware-backed attestation can strengthen claims about code identity on supported devices, but it cannot prove that local examples are benign or representative. The resulting update-integrity record supports rejection, rollback, and incident analysis without treating device identity as evidence that the gradient is correct.</p>\n<p>Network partitions are the harder case. Unlike a data center network, a federated fleet must absorb clients that stay offline for hours or days while traveling, out of coverage, or powered down. Asynchronous coordination protocols keep training moving despite missing participants, but they must balance staleness (accepting outdated contributions) against freshness (prioritizing recent but possibly sparse updates). Buffered asynchronous aggregation [@fedbuff] shows the mechanism. It removes the round barrier, letting each client train whenever its admission test passes and upload when done, while the server accumulates arriving updates in a buffer and applies their aggregate once a fixed number have arrived. Each update is down-weighted by its staleness, the number of server versions published since the client downloaded its starting model, so a slow client still contributes without dragging the shared model back toward an old state.</p>\n<p>Conventional pairwise secure aggregation (@sec-edge-intelligence-federated-privacy-a1ed) does not fit this buffer. Its masks cancel only among the clients fixed at key agreement, whereas the buffer fills with whichever clients finish. Staleness weighting breaks the masks as well. Weighting a masked update on the server also scales its masks, so they no longer cancel, and the client cannot apply the weight before masking because its staleness is known only when the update arrives. A buffered design therefore needs a secure-aggregation protocol built for it.</p>\n<p>↩ Gradient staleness, the delay between the model version a worker computed against and the version its update modifies, and its effect on convergence under bounded and fully asynchronous synchronization are established in @sec-distributed-training-systems-systems-staleness-impact-bsp-vs-ssp-vs-asp-e153.</p>\n<p>Recovery must distinguish coordinator state from device-local state. The coordinator checkpoints the global model and the optimizer and protocol state needed to resume accepted progress; this does not require a simultaneous checkpoint on every device. An incomplete round needs an explicit acceptance or abandonment rule, followed by evaluation of the population represented by its completed updates. State reconciliation identifies a returning device's base version and determines which shared state it must download and which personal state remains compatible. Server-side load balancing can redistribute coordination work, but replacing an unavailable client with a faster one also changes the local data contributing to training. Whereas convergence guarantees for synchronous training assume that every participant completes each round, a federated coordinator must treat stragglers and dropouts as the normal case and state what its convergence argument assumes about them.</p>\n<p>: <strong>Straggler problem</strong>: In data center training, stragglers slow synchronous progress; in federated learning, the problem is amplified by heterogeneous hardware, intermittent connectivity, and eligibility windows [@bonawitz2019towards; @kairouz2021]. Solutions like asynchronous aggregation and bounded staleness (ignoring updates computed against a model more than a fixed number of rounds old) improve throughput but introduce a fairness trade-off: aggressive straggler mitigation biases models toward users with high-end devices, potentially degrading performance for the most constrained users who need personalization most.</p>\n<h4 id=\"sec-33\" class=\"cs-h4\">Heterogeneity management at fleet scale</h4>\n<p>Million-device orchestration is a tiering decision, in which the system decides which clients can train, which can only report lightweight updates, and how much bias that selection introduces. The difficulty is that hardware capabilities, network conditions, data distributions, and availability patterns vary simultaneously, challenging traditional distributed machine learning assumptions about homogeneous participants operating under similar conditions.</p>\n<p>Illustrative peak compute ratings differ by about <code>[EdgeFedNpuRecap.compute_ratio_mult_str]</code> between flagship smartphones rated at <code>[EdgeFedNpuRecap.mobile_npu_tops_str]</code> and, below Archetype C's phone-class clients, IoT microcontrollers rated at <code>[EdgeFedNpuRecap.iot_compute_tops_str]</code>. These ratings do not translate into a training-speed ratio, because supported precision, backward operators, memory traffic, and sustained execution determine update time. Memory spans the same <code>[EdgeDeviceSpectrum.memory_ratio_mult_str]</code> range from microcontroller SRAM to flagship phone RAM met in @sec-edge-intelligence-model-constraints-9232, and at fleet scale that range decides which update state each tier can retain at all. Energy budgets further restrict when that work can run. Background adaptation in this example targets roughly <code>[EdgeFedPowerEnvelopeRecap.background_range_str]</code>, while phones may sustain <code>[EdgeFedPowerEnvelopeRecap.sustained_range_str]</code> for foreground ML workloads and burst higher briefly. Network throughput, latency, and interruption patterns must likewise be measured for the participating clients before selecting update frequency and compression.</p>\n<p>Measured scores show a spread of the same order among phones alone, without counting microcontrollers. The AI Benchmark from ETH Zurich runs a fixed suite of quantized and floating-point inference workloads on each phone processor through its Android acceleration path [@ignatov2019aibenchmark; @ethz2026aibenchmark]. Among processors released from <code>[MobileAISpread.fleet_first_str]</code> on, which a client fleet can still contain, the scores span about <code>[MobileAISpread.fleet_spread_mult_str]</code>, from the <code>[MobileAISpread.fleet_lo_name_str]</code> (<code>[MobileAISpread.fleet_lo_year_str]</code>) to the <code>[MobileAISpread.fleet_hi_name_str]</code> (<code>[MobileAISpread.fleet_hi_year_str]</code>), and @fig-mobile-ai-spread plots every processor in the ranking. Even flagships of the same generation differ by <code>[MobileAISpread.gen_spread_mult_str]</code>, with the <code>[MobileAISpread.gen_lo_name_str]</code> scoring that far below the <code>[MobileAISpread.gen_hi_name_str]</code>, largely because each score reflects the processor's software path as well as its silicon. The Tensor G4 result runs through Android's generic neural-network interface, while the leaders use their vendors' own runtimes. These are inference scores, not training speeds, but they bound the problem from the side that matters for scheduling. No single local-work quota fits devices that differ by two orders of magnitude in measured throughput.</p>\n<p>Tiered participation can assign different amounts of local work while preserving a compatible shared-update contract. A capable phone may complete more steps, while a constrained client contributes a smaller update or a separately defined aggregate statistic. These outputs are not interchangeable simply because they come from the same fleet. More work on strong devices also cannot replace the observations held by weak devices, so the policy must evaluate both computational contribution and population coverage.</p>\n<p>The scale challenges extend beyond device heterogeneity to coordination overhead. Federated learning does not run a consensus protocol among millions of clients, nor does hierarchical aggregation perform local consensus. Hierarchical aggregation reduces fan-in through regional aggregators, which validate an eligible cohort and combine its updates before forwarding a partial aggregate; agreement on an ordered replicated log, if needed for the coordinator's own metadata, remains a separate control-plane service. Edge infrastructure can provide aggregation points, but each added tier creates another trust boundary and another place where weighting, clipping, privacy accounting, and failure recovery must remain consistent.</p>\n<p>Tiering interacts with the participation bias analyzed under client scheduling (@sec-edge-intelligence-client-scheduling-f675). Capability-based selection shortens rounds but concentrates completed updates on strong devices, so stratified sampling across tiers must be paired with per-cohort evaluation of completed participation and model quality. Availability also has a daily rhythm; devices that charge overnight in one time zone form a different cohort from those available during another zone's working hours.</p>\n<p>Orchestration brings client scheduling, update compression, personalization, privacy, and tiering into a coherent policy for a single federated round. Deployed systems, however, do not stop after one round, and their devices keep applying local and federated updates week after week.</p>\n<h2 id=\"sec-33\" class=\"cs-h2\">Continual Adaptation Under Edge Budgets</h2>\n<p>A keyboard model that adapts each night for a year passes through hundreds of admitted update windows, and each window moves it a little further from the version that was validated at release. Every update the chapter has built so far was judged one at a time, by whether it fit the memory budget, passed the admission test, and improved a local metric. Repeated across a deployment's lifetime, those individually acceptable updates compound. Earlier changes alter what later updates start from, the replay buffer decides which old observations still count, and participation decides which devices shape the next shared version.</p>\n<p>The mechanisms that keep this trajectory stable are the ones already introduced, now applied over time. Selective updates bound how far any one window can move the model, and they save work only when the execution path can skip it. Replay protects earlier behavior at the cost of retained examples and additional training. Opportunistic admission delays learning until device conditions permit it. Each needs a resource budget and an outcome check on retained behavior alongside the newest data. The long-lived stream that drives this learning is mostly unlabeled, which sets the first design question.</p>\n<h3 id=\"sec-34\" class=\"cs-h3\">Learning from unlabeled sensor streams</h3>\n<p>A camera stream running continuously at <code>[EdgeSensorStreamVolume.camera_fps_str]</code> frames per second produces roughly <code>[EdgeSensorStreamVolume.frames_per_day_str]</code> frames daily before retention filtering. An accelerometer sampling at <code>[EdgeSensorStreamVolume.accel_hz_str]</code> Hz generates <code>[EdgeSensorStreamVolume.readings_per_day_str]</code> readings, almost none of them accompanied by a user label. Cameras, accelerometers, location sensors, and touch interactions all supply data that can support self-supervised learning, turning continual learning into a storage and scheduling decision. The engineering question is which traces encode stable structure worth learning from and which should expire before they crowd out model state, replay buffers, or user-facing storage.</p>\n<p>Learning from such traces without labels requires the supervision to come from the data's own structure. Contrastive learning is the common way to manufacture it on a sensor stream, training an encoder so that the embeddings of designated positive pairs, two samples that should mean the same thing, lie close together while those of designated negative pairs lie far apart. Nearby camera frames or augmented views of one frame can supply positives when they preserve the task-relevant content; scene changes can invalidate that assumption. Different frames or replay entries can supply negatives, but may depict the same underlying event. The pair-selection policy therefore defines a learning signal that needs validation. Other devices' samples are not automatically available under a federated data-locality policy, and stored pairs or representations compete with replay and model state for memory.</p>\n<h3 id=\"sec-35\" class=\"cs-h3\">Continual adaptation and catastrophic forgetting</h3>\n<p>Once a device extracts update signals from those unlabeled sensor streams and implicit interactions week after week, the dominant risk shifts from finding supervision to preserving prior competence. A model that adapts continually to recent summer lighting, a new work commute, or a shift in user vocabulary can overwrite the weights it needed for winter weather or older commands if each update moves parameters purely to minimize recent loss. When a deployment uses continual adaptation to address changing environments, user behavior, or task requirements, each update must balance new evidence against previously learned behavior. This is the stability-plasticity trade-off: models must remain stable enough to preserve useful knowledge while plastic enough to learn new patterns.</p>\n<p>Continual learning on edge devices faces several interconnected challenges. Catastrophic forgetting (@sec-edge-intelligence-experience-replay-737e) is magnified when devices cannot store or revisit historical training data. Task interference compounds it when several learning objectives compete for limited parameter capacity, and distribution shift between pretraining and local deployment demands continued adaptation without eroding the model's core representations. Restricted device memory rules out the comprehensive replay buffers that centralized infrastructure can afford.</p>\n<p>Three families of mechanisms manage the stability-plasticity trade-off during continual learning. Elastic weight consolidation [@kirkpatrick2017] mitigates catastrophic forgetting by penalizing changes to weights important for previous tasks, where a weight's importance reflects how sharply the earlier tasks' loss rises when that weight moves. Experience replay (@sec-edge-intelligence-experience-replay-737e) maintains stability during adaptation by interleaving new training with replayed examples from previous tasks. Progressive neural architectures allocate new capacity for new tasks rather than forcing all knowledge into fixed-capacity networks [@rusu2016progressive]. That last option is attractive when interference is severe, but it consumes additional memory and therefore fits only devices with enough spare capacity.</p>\n<p>: <strong>EWC (elastic weight consolidation)</strong>: Estimates each weight's importance with a diagonal approximation to the Fisher information, a measure of how sensitive the earlier tasks' loss is to that weight, and uses those estimates to weight a penalty on changes from previously learned parameters [@kirkpatrick2017]. In addition to current parameters, a basic implementation stores importance scores and reference parameter values. Retaining separate penalties for earlier tasks can increase that state further. Compared with replay, EWC trades stored examples for parameter-sized statistics; which uses less memory depends on model size, retained history, precision, and the penalty implementation.</p>\n<p>The earlier mechanisms bound each step without guaranteeing the trajectory. Meta-learned initializations (@sec-edge-intelligence-federated-personalization-3c73) and few-shot adaptation (@sec-edge-intelligence-fewshot-learning-data-streaming-566e) reach useful local behavior in few updates. Restricting updates to bias terms, adapters, or heads (@sec-edge-intelligence-model-adaptation-6a82) keeps the base parameters intact, while useful pretrained representations reduce what the device must learn [@bommasani2021opportunities]. Even a single update to a head or adapter can alter predictions on earlier tasks, and a year of individually small updates can accumulate into significant behavioral drift. The acceptance test for each window must therefore measure retained capability alongside improvement on the new data, against a recoverable baseline, because neither a small update count nor a frozen backbone is a stability guarantee.</p>\n<p>Once the update footprint is bounded, the runtime must decide when the update can execute and whether it should be shared. The admission condition in @eq-edge-background-admission already governs when a continual update may run; what changes over a long deployment is that each admitted window also moves the device further from its last validated state. When the device also shares updates, the compression and selective transmission of @sec-edge-intelligence-bandwidthaware-update-compression-7730 keep that repeated traffic inside the bandwidth and energy budgets [@konevcny2016federated].</p>\n<p>Stability then becomes a state-management problem. Replay buffers, support sets, adaptation logs, and model update metadata must be protected against unauthorized access or tampering because they encode the local evidence that shaped the model. Lightweight encryption or hardware-backed secure storage can reduce that exposure, but security controls do not prove that adaptation remains beneficial. Lightweight validation techniques, including confidence scoring, drift detection heuristics [@gama2014], and shadow model evaluation, monitor adaptation dynamics and can hold an update for validated review before severe degradation occurs. Robust rollback procedures require a trusted baseline checkpoint that can be restored quickly, especially in safety-important and regulated domains where failure recovery must be provable.</p>\n<p>Privacy and compliance requirements close the loop. User consent, data minimization, retention limits, and the right to erasure must be designed into the adaptation pipeline rather than added after deployment. Meeting regulatory obligations at scale demands on-device learning workflows in which the model can adapt in place while the operator can still explain, bound, and reverse each change. Because a fleet applies these rules on flagship phones, budget phones, and microcontroller sensors at once, the pillars and their stability controls must be assembled into one policy whose terms change with the device that runs it.</p>\n<h2 id=\"sec-36\" class=\"cs-h2\">Integrating the Edge Intelligence Pillars</h2>\n<p>Consider the voice assistant from the opening of this chapter, now deployed across <code>[EdgeAdaptationTierProfile.fleet_devices_million_str]</code> that range from flagship phones to budget handsets. The chapter built model adaptation, data efficiency, and federated coordination as separate pillars, and treated separately, each solves its own constraint while leaving the others free to misbehave. An adapter rank chosen without regard to replay memory can crowd out the buffer that protects earlier behavior, and an update format chosen without regard to aggregation can produce arrays no coordinator can combine. The integration that works makes one per-tier policy decide how much a device may adapt, how much it may remember, and how it may participate in the fleet, because all three draw on the same memory, energy, and connectivity budget.</p>\n<p>The model adaptation layer starts with candidate policies for the scenario's device tiers. Flagship phones (Tier 1) representing <code>[EdgeAdaptationTierProfile.flagship_share_pct_str]</code> of the deployment receive LoRA adapters of rank <code>[EdgeAdaptationTierProfile.flagship_lora_rank_str]</code>. Mid-tier devices (Tier 2), comprising <code>[EdgeAdaptationTierProfile.mid_tier_share_pct_str]</code>, receive rank <code>[EdgeAdaptationTierProfile.mid_tier_lora_rank_str]</code> adapters. Budget devices, the remaining <code>[EdgeAdaptationTierProfile.budget_share_pct_str]</code>, use bias-only updates under a <code>[EdgeAdaptationTierProfile.budget_device_memory_limit_gb_str]</code> memory limit. These assignments apply the device-tier framework of @sec-edge-intelligence-performance-vs-resource-tradeoffs-2be2. Budget phones receive the Tier 3 mechanism because the memory granted to background adaptation, not installed RAM, sets their tier. The voice assistant keeps one adaptation per user on a latency-sensitive speech path, so it uses mergeable LoRA on both capable tiers rather than the switchable residual adapters that suited the multi-context workload. These assignments specify an initial policy, not a demonstrated fit. Profiling must include the base model, activations, optimizer state, runtime, and foreground reserve, while local validation determines whether each update space captures useful voice variation.</p>\n<p>The data efficiency layer allocates part of the same device budget to experience replay, with candidate buffers of <code>[EdgeAdaptationTierProfile.budget_replay_buffer_mb_str]</code> on budget devices and <code>[EdgeAdaptationTierProfile.flagship_replay_buffer_mb_str]</code> on flagship models. Buffer coverage and retention tests determine whether these allocations preserve earlier behavior. The policy targets initial adaptation within <code>[EdgeAdaptationTierProfile.few_shot_interactions_range_str]</code>, addressing the cold-start problem of limited evidence for a new user. That target requires enough valid feedback, since a handful of ambiguous interactions supervises nothing. Later streaming updates are admitted only when both learning evidence and device resources permit them.</p>\n<p>The federated coordination layer combines explicitly compatible shared state. Different adapter ranks and bias-only policies do not produce interchangeable arrays, so the coordinator needs separate compatible groups or a defined mapping to common parameters. Even equal-rank LoRA factors require a stated aggregation rule because each client's effective weight update is the product of its up-projection and down-projection matrices. Averaging the two factor matrices separately across clients and then multiplying the averages does not give the average update. The product of the averages contains cross-terms that pair one client's up-projection with another client's down-projection, combinations that no device ever trained. Averaging the multiplied weight updates instead preserves the exact mean update, but a sum of several low-rank products generally has higher rank, so it must be folded into the base weights or truncated back to the target rank before the next round. Tier-specific personal state can remain local. The scenario's <code>[EdgeAdaptationTierProfile.federated_lora_update_mb_str]</code> adapter payload is smaller than the <code>[EdgeLoraParameterEfficiency.fp16_weight_footprint_gb_str]</code> full-model payload, but downloads, repeated rounds, and protocol overhead still enter the communication budget. Each participating device must pass the energy, thermal, and foreground-latency admission tests. Raw audio can remain local while derived updates and participation metadata remain sensitive. Secure aggregation, privacy accounting, access controls, and retention policies must cover that shared state.</p>\n<p>These layers only work as a system when the integration policy protects against capability mismatch, component failure, resource conflicts, and untested emergent behavior. Four edge-learning integration controls answer those risks one for one in @tbl-edge-integration-controls: hierarchical capability matching, graceful degradation, explicit priority policy, and performance validation.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Integration risk</strong></th><th><strong>Control</strong></th><th><strong>Why it matters</strong></th></tr></thead><tbody>\n<tr><td>Capability mismatch</td><td>Hierarchical capability matching</td><td>Deploys more sophisticated techniques on capable devices while preserving basic functionality across the full device spectrum.</td></tr>\n<tr><td>Component failure</td><td>Graceful degradation</td><td>Keeps local adaptation useful when connectivity is poor or battery constraints force the system into a minimal adaptation mode.</td></tr>\n<tr><td>Resource conflict</td><td>Explicit priority policy</td><td>Prevents model adaptation and replay buffers from competing for the same memory, energy, or latency budget without a predefined owner.</td></tr>\n<tr><td>Emergent behavior</td><td>Performance validation</td><td>Tests combinations of device tier, network state, and adaptation policy because integrated systems fail in ways individual techniques do not expose.</td></tr>\n</tbody></table></div>\n<p>: <strong>Edge-Learning Integration Controls</strong>: A tiered edge-learning deployment needs explicit controls for capability matching, graceful degradation, resource conflicts, and validation across device and network combinations. {#tbl-edge-integration-controls}</p>\n<p>The same reasoning reduces to three questions (@fig-tiered-adaptation). The first asks how much adaptation the local change needs, the second whether a larger update is needed for the quality target and fits the measured device budget, and the third whether the updates are valuable across devices. The flowchart's branch labels describe adaptation demand, not the Tier 1--3 device classes. Budget phones, held to the Tier 3 mechanism, sit in the lightweight branch, and the other Tier 1 and Tier 2 phones sit in the moderate branch. Wall-powered edge servers, which this phone fleet does not include, are candidates for the larger-update branch. The voice-assistant policy therefore spans the lightweight and moderate branches, with budget phones held to the lightweight branch by a memory limit that the flowchart does not draw.</p>\n<p>The chapter built three pillars for on-device learning: model adaptation (bias-only updates, adapters, full fine-tuning), data efficiency (few-shot, experience replay, compressed representations), and federated coordination (aggregation, client scheduling, secure aggregation). The decision framework in @fig-tiered-adaptation maps each technique to device-class capability and coordination pathway. Test integration of the three pillars across the same deployment.</p>\n<ul class=\"cs-list\">\n<li>[ ] Device-tier capability matching: For a fleet with microcontroller wake-word sensors, smartphones, and wall-powered edge servers, map each device class to the branch of @fig-tiered-adaptation it can afford and state what fails when one technique is pushed across all three classes.</li>\n<li>[ ] Fairness in federated participation: When 90 percent of a federated round's compute comes from the top 10 percent of devices by capability, distinguish compute share from aggregation weight, identify the population-coverage risk, and select a scheduling or weighting control from the federated coordination pillar.</li>\n<li>[ ] Drift detection without labels: For a deployed personalization model with no ground-truth labels at the edge, describe how the device can detect enough local distribution shift to warrant a federated round using only signals available to the on-device inference path.</li>\n<li>[ ] Secure aggregation's participation floor: With a secure-aggregation floor of 100 devices and only 30 active devices in a given hour, determine the system response and identify which pillar must compensate.</li>\n<li>[ ] Observable signals and hidden state: Separate the signals a central operator can observe from the device state that must remain hidden, and locate the catastrophic forgetting risk in that split.</li>\n</ul>\n<p>The hardest edge-learning failures appear when the pillars interact rather than when any one fails alone. An adapter can fit memory yet overfit sparse local data, a replay buffer can stabilize learning yet leak sensitive history, and a federated round can improve the global model while amplifying participation bias. These interactions decide when on-device learning is appropriate and when a simpler strategy is safer.</p>\n<p>Centralized training can standardize hardware, curate data, and validate a model before release; a tiered policy instead ships to millions of devices whose runtimes, update histories, and connectivity differ, and it keeps changing the model after release. Shipping it turns each tier assignment into a release artifact that must be versioned, validated without central labels, and rolled back when an adapted model degrades.</p>\n<h2 id=\"sec-37\" class=\"cs-h2\">Production Integration</h2>\n<p>A prototype can fine-tune an adapter on one Raspberry Pi under controlled conditions, where the engineer controls the input stream, inspects every loss curve, and reflashes weights by hand if an update diverges. Deploying that same adaptation policy across <code>[EdgeAdaptationTierProfile.fleet_devices_million_str]</code> turns local learning into a production operations problem across devices whose runtimes, resource budgets, and update histories differ. The release contract must therefore govern not just a static set of initial weights, but what each device may learn in the field, how unlabeled local changes are gated, and how a trusted baseline is restored when adaptation fails.</p>\n<h3 id=\"sec-38\" class=\"cs-h3\">MLOps integration challenges</h3>\n<p>In a traditional cloud pipeline, the release artifact is a single immutable model binary; once millions of devices begin updating adapters offline on different schedules, the initially released weights no longer describe the behavior running in the field. Integrating on-device learning into machine learning operations (MLOps), the practices that version, deploy, monitor, and roll back production models, expands the scope of release engineering because backbones, adapters, update policies, and local histories evolve independently across heterogeneous hardware. Existing integration tests, version registries, and monitoring remain necessary, but they must now track and bound the permitted adaptation process alongside the initial model.</p>\n<p>An edge learning lifecycle splits five stages between the cloud and the device (@fig-edge-mlops-pipeline). Centralized base-model pretraining (Stage 1), per-tier hardware compression (Stage 2), and staged over-the-air rollouts (Stage 3) originate in the cloud, while local adaptation executes on-device under the released update policy (Stage 4). Aggregate telemetry (Stage 5) supplies evidence for deciding whether cloud retraining is warranted. The telemetry needs its own privacy controls; aggregation alone does not establish a privacy guarantee, and a detected change must be distinguished from a quality regression before triggering a new training cycle.</p>\n<h4 id=\"sec-39\" class=\"cs-h4\">Deployment pipeline transformations</h4>\n<p>A release that enables local learning includes an adaptation policy alongside model artifacts. For example, the voice-assistant policy of @sec-edge-intelligence-pillar-integration-7e21 assigns bias-only updates to budget devices and different LoRA ranks to mid-tier and flagship phones. These are conditional assignments: model footprint, runtime support, and live admission tests determine whether a device may execute them. CI/CD must therefore validate the selection logic and permitted update behavior across device configurations in addition to the initial weights.</p>\n<p>Versioning must preserve relationships among those artifacts. A local adapter belongs to a particular base model, training policy, and representation schema; a replay buffer may also depend on the encoder that produced its features. Federated round identifiers record which shared version produced a returned contribution. Updating the base therefore requires a decision to retain, migrate, retrain, or discard dependent local state. A newer version number alone does not establish compatibility, and rollback must restore a compatible set of artifacts rather than independently selecting older files.</p>\n<h4 id=\"sec-39\" class=\"cs-h4\">Continuous training orchestration</h4>\n<p>Continuous training on devices combines fleet-level round or release schedules with local admission decisions. A coordinator can request work, but a device trains only when its resource and availability tests pass. The orchestrator must therefore track eligible work and compatible state without assuming simultaneous execution across clients. Because devices run different base versions at once and may reconnect after days or weeks offline, a returned update must identify its base version. The coordinator can then reject the update, apply a stated staleness policy, or request new training from the current base (@sec-edge-intelligence-asynchronous-device-synchronization-348e). Per-device adapters and replay buffers carry their own version tags and need not be merged into the shared model.</p>\n<p>Resource-aware scheduling applies @eq-edge-background-admission at fleet scale, where federated rounds usually add idle, charging, and unmetered-network requirements on top of the local admission test. A daily energy cap bounds cumulative learning cost across many admitted windows. Admission also has a runtime half. Bias updates in early layers require backward computation through later operations; head-only adaptation confines that computation to the head. Either path competes with inference for compute, memory bandwidth, and thermal headroom on a shared SoC. Users judge the device by its quality of service (QoS), so the runtime gives inference priority and throttles or revokes a training window as foreground latency approaches its deadline. At the microcontroller extreme, measured update energy and available reserves determine how much learning a duty-cycled or harvested-power budget can support.</p>\n<p>: <strong>Microcontroller power budget</strong>: In an illustrative operating point, 10 mW of active training for 10 seconds consumes 0.1 J. The number of updates that fit that session requires a measured time or energy per update. Battery lifetime additionally depends on usable capacity under the actual load, sleep power, radio activity, conversion losses, and duty cycle; nameplate capacity alone does not establish continuous-training lifetime.</p>\n<p>When a representative central validation set is unavailable, federated evaluation can aggregate metrics computed on local held-out data. Update magnitudes provide an optimization diagnostic, but small changes can reflect stalled learning rather than acceptable quality. Participation audits must accompany outcome measurements so that apparent progress is not confined to an overrepresented cohort.</p>\n<h4 id=\"sec-39\" class=\"cs-h4\">Monitoring system evolution</h4>\n<p>Traditional monitoring aggregates metrics from centralized inference servers that see every request, whereas an adaptive fleet's monitor sees only what devices report about models that may differ on every device. Fleet telemetry for edge devices, including federated analytics that report aggregate or differentially private summaries, is one of the fleet release controls in @sec-edge-intelligence-fleet-release-controls-5e1a. Adaptation adds local model states that the operator may not observe centrally. Monitoring must distinguish a change in behavior from a change in quality. Unlabeled signals can identify divergence, while deciding whether the adapted model is better requires validated outcome evidence.</p>\n<p>Drift detection presents additional challenges without access to ground truth labels. While traditional monitoring compares model predictions against labeled validation sets maintained on centralized infrastructure, on-device systems must detect drift using only the indirect local signals available during deployment. Confidence calibration compares output probabilities with eventual outcomes whenever labels exist; without verified outcomes, confidence shifts merely flag an altered score distribution. In parallel, input distribution monitoring applies statistical tests to detect when runtime feature distributions diverge from pretraining data without requiring labels. Task performance proxies use implicit feedback such as user corrections or session abandonment, though only after validating the causal link to task quality and accounting for how model suggestions alter subsequent user behavior. Finally, shadow baseline comparisons run a frozen base model alongside the adapted one; @sec-edge-intelligence-validation-strategy-adaptation-ab3d develops why that comparison measures divergence rather than quality.</p>\n<p>↪ Covariate shift, label shift, and concept drift, and why input monitors can stay silent under pure concept drift, are developed in @sec-robust-ai-distribution-shift-concept-drift-55e2.</p>\n<p>Cohort evaluation must separate contribution from benefit. A device that never trains can still download an improved shared model, but its users' data may be poorly represented among the completed updates. Participation metrics reveal that coverage gap; per-cohort quality measurements establish whether it harms those users. A favorable global average cannot substitute for either measurement.</p>\n<h4 id=\"sec-39\" class=\"cs-h4\">Validation strategy adaptation</h4>\n<p>Traditional validation measures model quality directly against a held-out test set with known ground truth, whereas on-device learning has to validate adapted models where their inputs live, within privacy and resource limits, and usually without labels. Shadow model evaluation maintains multiple model variants on each device and compares their behavior. Devices can run a frozen, last-known-good model beside a locally adapted version and measure prediction divergence, confidence shifts, latency, and resource use on the same input stream. Without labels or a validated outcome proxy, these comparisons detect change, not performance degradation: agreement can hide a shared error, and disagreement does not reveal which model is correct. A shadow comparison can therefore suspend an update for further evaluation, but automatic rollback requires labeled outcomes, a validated behavioral invariant, or a proxy whose relationship to task quality has been established for the deployment.</p>\n<p>The comparator can therefore act only as a gate, never as a judge (@fig-shadow-validation). The live input stream is mirrored to the frozen baseline and the adapted candidate, and the comparator tracks their disagreement, confidence shift, and resource deltas. When disagreement exceeds a tolerance $\\ResponseThreshold$, the gate holds the candidate out of service; validated outcome evidence then either clears it or confirms the regression that justifies rollback.</p>\n<p>Confidence-based gates provide another change signal when labels are unavailable. Even a calibrated model's confidence is interpretable only relative to the population and task on which calibration was measured. A drop can reflect distribution shift, ambiguity, or a changed score scale; stable confidence can coexist with overconfident errors. Systems may use confidence to trigger investigation or halt adaptation conservatively, but they should not call the adapted model worse without delayed labels, randomized evaluation, trusted user corrections, or another validated outcome signal.</p>\n<p>Federated A/B testing randomly assigns devices to treatment and control adaptation policies, balanced across device tiers, and compares privacy-preserving aggregates of adaptation success rate, time to improvement, and final quality. A strategy that wins is then released through the staged rollout process that fleet operations owns. Because aggregated validation signals are themselves releases, they need data minimization, secure aggregation where appropriate, a declared privacy unit, and privacy accounting across repeated rounds. Even then, a population summary can miss a failure confined to a few users. Local gates and population summaries therefore provide different evidence, and evaluating an adaptive fleet requires measuring adaptation benefit, resource cost, and cohort coverage together.</p>\n<p>↪ Staged rollout, which widens a release's exposure only after each stage performs acceptably, is developed in @sec-ml-operations-scale-staged-rollout-strategies-2d1f.</p>\n<h4 id=\"sec-39\" class=\"cs-h4\">Fleet release controls</h4>\n<p>The preceding controls act on one adapted device or one federated round. Operating the whole population as one fleet adds three interacting constraints beyond those of any single device, so they form one operational design problem. Each constraint calls for its own platform control (@tbl-ops-scale-edge-fleet-controls), including hardware-in-the-loop validation and federated analytics.</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Edge fleet constraint</strong></th><th><strong>Why it appears</strong></th><th><strong>Platform control</strong></th></tr></thead><tbody>\n<tr><td>Extreme version skew</td><td>Rollouts can take weeks or months because devices are offline, on low battery, or on restricted networks. At any time, 50 model versions may remain active.</td><td>Maintain backward-compatible data pipelines and serving contracts for models deployed months earlier.</td></tr>\n<tr><td>Device-aware validation</td><td>Accuracy gates do not reveal whether a model exceeds a phone's memory budget or triggers thermal throttling on its system-on-chip (SoC); microcontroller-class targets below Archetype C tighten the budget to about 1&amp;nbsp;MB.</td><td>Add hardware-in-the-loop validation on physical or emulated target devices before promotion.</td></tr>\n<tr><td>Privacy-limited telemetry</td><td>Raw predictions cannot stream back continuously because privacy rules and bandwidth costs constrain observability.</td><td>Use federated analytics: devices compute local statistics such as error rates or drift, then transmit permitted aggregate health signals under explicit privacy and retention controls.</td></tr>\n</tbody></table></div>\n<p>: <strong>Edge Fleet Controls</strong>: Edge operations couple rollout latency, device heterogeneity, and privacy-limited observability. The operations platform must reconstruct global fleet health from partial signals while preserving compatibility with many active model versions. {#tbl-ops-scale-edge-fleet-controls}</p>\n<p>Version skew and device-aware validation follow from the state an adapted fleet carries. A device that reconnects after weeks offline may still run a release several versions old, together with adapters and replay buffers tied to that base, so data pipelines and serving contracts must stay compatible across every active version rather than only the newest. A cloud accuracy gate says nothing about the tests of @eq-edge-adaptation-peak-memory and @eq-edge-background-admission, whose outcomes depend on each target's runtime, operator placement, and thermal behavior. Hardware-in-the-loop validation therefore runs the candidate release, including its update path, on physical or emulated devices from each tier, and promotion waits until those tests pass there.</p>\n<p>Federated health signals inherit the participation bias that @sec-edge-intelligence-client-scheduling-f675 identified for federated training. A device reports its local error rate or drift statistic only when its admission policy allows the work and its connectivity allows the upload, so the devices that report most are the well-charged, well-connected, newer ones. The fleet's health dashboard then describes the admitted population rather than the deployed one, the same skew the participation selection principle (\\ref{pri-participation-selects-population}) names for training. A staged edge rollout can look healthy because the devices most likely to fail, older hardware and thermally constrained phones, are also the least likely to report. The platform therefore tracks reporting coverage per device class and cohort alongside the health signals themselves, and holds promotion when a cohort's coverage falls too low for its signal to count as evidence.</p>\n<h4 id=\"sec-39\" class=\"cs-h4\">Performance evaluation in dynamic environments</h4>\n<p>Deciding what those release gates and cohort reports should measure goes beyond static inference benchmarks, which characterize latency, throughput, energy efficiency, and accuracy for a fixed model, whereas on-device learning requires additional measurements of adaptation quality and training efficiency across successive updates to explain whether local learning is worth its resource cost. Sample efficiency measures the examples needed to reach a declared quality improvement under a fixed evaluation protocol. Gaining two percentage points from 100 local samples rather than 500 is an advantage when collecting useful samples is the binding constraint. Fewer samples need not mean faster or cheaper adaptation, because the more sample-efficient method may perform more work per example or retain more state; elapsed time, peak memory, and energy complete the comparison.</p>\n<p>Because a sample-efficient update can still exceed hardware limits, device-envelope fit tests whether the improvement stays inside resource budgets. Memory-constrained convergence evaluates validation loss under a fixed RAM budget, such as \"convergence within <code>[EdgeDeviceSpectrum.mcu_sram_kb_str]</code> training footprint,\" while energy-per-update measures millijoules consumed per gradient step. An illustrative background envelope of <code>[EdgeAdaptationPowerMetrics.background_range_str]</code> corresponds to <code>[EdgeAdaptationPowerMetrics.background_energy_per_hour_str]</code> while active. Battery impact depends on duty cycle, usable battery capacity, foreground demand, and charging state. Time-to-adaptation extends the same idea to scheduling by measuring wall-clock time from new data to measurable improvement, including waiting for idleness, charging status, and thermal headroom rather than only raw accelerator throughput.</p>\n<p>Even an update that fits the device envelope must still prove its value to the user, so personalization quality evaluates whether adaptation improves the intended behavior while retaining earlier capabilities. Per-user performance delta compares the adapted model with the global baseline on user-specific holdout data; acceptance requires a declared improvement threshold and reported uncertainty. Privacy must be assessed under the specified disclosure policy and guarantee, rather than treated as an unspecified unit of exposure. Catastrophic forgetting measures degradation on the original task after adaptation. Its acceptable magnitude is application-specific, and accuracy changes must distinguish percentage points from relative percent.</p>\n<p>When devices coordinate through the federated protocols examined in @sec-edge-intelligence-federated-learning-6e7e, evaluation expands from the device to the population. Communication efficiency relates quality improvement to total transmitted bytes; compression gains depend on the model, optimizer, data heterogeneity, and encoding [@konevcny2016federated; @kairouz2021]. Comparisons should also report bytes and elapsed time to the same quality target. Straggler policies change both waiting time and the cohort that contributes. Participation count, cohort coverage, and outcome uncertainty must therefore be evaluated together, without assuming that one participation threshold determines stability across all policies.</p>\n<p>A system that infers quickly but adapts slowly, or adapts efficiently but ends at poor accuracy, still fails its deployment, so these training metrics and operational controls extend inference benchmarks and established MLOps practice to distributed, heterogeneous learning. Together they detect, hold, and reverse an adaptation that misbehaves, though they do not remove the underlying conditions that make adaptive fleets misbehave, from heterogeneous hardware and non-IID data to slow drift and adversarial clients.</p>\n<h2 id=\"sec-39\" class=\"cs-h2\">Engineering Challenges and Mitigations</h2>\n<p>A billion-user predictive text model that learns from live keyboard inputs can be poisoned if a coordinated group of malicious users repeatedly types a specific slur and those local updates enter the global federated aggregate. The release gates and runtime monitors of @sec-edge-intelligence-production-integration-beb5 bound resource contention and flag gross regressions, and the tiered integration policy bounds where each pillar may act, yet neither erases the field conditions that let an adapting fleet degrade or conceal an attack. Those failure surfaces form a coupled chain across the deployment. Hardware and software fragmentation changes which devices can participate, skewed participation distorts the non-IID data distribution the fleet learns from, implicit feedback loops let local models drift silently between audits, and post-release weight changes strain regulatory traceability and safety fallbacks. Because each blind spot hides the next, engineering mitigations must progress from device and data heterogeneity through silent drift and compliance recovery to the combined control path that defends against coordinated poisoning (@sec-edge-intelligence-foundations-robust-ai-systems-3fde).</p>\n<h3 id=\"sec-40\" class=\"cs-h3\">Device and data heterogeneity management</h3>\n<p>An adaptation policy that passes lab tests on one reference smartphone can produce divergent weights, crash on unsupported kernels, or stall indefinitely across a production fleet whose OS versions, driver stacks, floating-point implementations, and charging habits differ. Heterogeneity determines which devices can train, which can validate, and which can only contribute lightweight signals. Tier assignment already gives each hardware class its own model format and update policy, so the management problem here is reproducibility across devices whose software stacks, connectivity, and power availability diverge.</p>\n<p>Software heterogeneity is what makes even a correct assignment hard to reproduce. Devices may run different versions of operating systems, kernel-level drivers, and runtime libraries. Some environments support optimized ML runtimes like TensorFlow Lite Micro or ONNX Runtime Mobile, while others rely on custom inference stacks or restricted APIs. These discrepancies can lead to subtle inconsistencies in behavior, especially when models are compiled differently or when floating-point precision varies across platforms.</p>\n<p>Connectivity and uptime add the scheduling dimension. Some devices are intermittently connected, plugged in only occasionally, or operating under strict bandwidth constraints. Others have continuous power and reliable networking, but still prioritize user-facing responsiveness over background learning. These differences complicate coordinated learning because update eligibility changes with the device's current state rather than with its hardware tier alone.</p>\n<p>System fragmentation makes reproducibility and testing a fleet property rather than a lab property. With such a wide range of execution environments, consistent model behavior is difficult to guarantee and failures are difficult to reproduce. Monitoring, validation, and rollback therefore become more important, while also becoming harder to implement uniformly across the fleet.</p>\n<p>The consequence is visible in a mobile-keyboard deployment. One device might provide <code>[EdgeAdaptationTierProfile.smartphone_ram_gb_str]</code> of RAM and a supported accelerator path, while another has <code>[EdgeAdaptationTierProfile.budget_keyboard_phone_ram_gb_str]</code>, a slower update path, and intermittent connectivity. These differences affect update duration and completion frequency. Adjusting schedules, model formats, and compression can broaden participation, but whether the improvement is equitable shows up only in outcome measurements across those device cohorts, because respecting each device's budget is not the same as delivering equal benefit.</p>\n<h3 id=\"sec-41\" class=\"cs-h3\">Non-IID data distribution challenges</h3>\n<p>Those hardware and participation differences across device cohorts are compounded by statistical skew in what each cohort actually observes. A federated round whose global validation loss improves steadily can still degrade next-word accuracy for an entire regional dialect or budget-handset cohort because no central shuffle can equalize non-IID client distributions. In production, non-IID data becomes an evaluation and control problem. Evaluation must cover the intended deployment population through a representative central test set or distributed held-out data, and aggregate quality needs cohort-level checks because a population average can conceal a persistent local failure. The mitigation should follow the observed failure rather than the generic label \"non-IID,\" and each of four common observations points to a bounded control and a release criterion (@tbl-edge-noniid-control).</p>\n<div class=\"table-wrap\"><table class=\"cipher-table\">\n<thead><tr><th><strong>Observed evidence</strong></th><th><strong>Likely failure</strong></th><th><strong>Control to test</strong></th><th><strong>Release criterion</strong></th></tr></thead><tbody>\n<tr><td>Cohort metrics diverge while aggregate quality improves</td><td>Population underrepresentation</td><td>Stratified sampling or capped importance weights</td><td>Worst-cohort metric improves without unacceptable aggregate loss</td></tr>\n<tr><td>More local steps increase update disagreement and rounds to target</td><td>Client drift</td><td>Reduce local steps, add proximal regularization (FedProx), incorporate control variates (SCAFFOLD), or adapt the server optimizer</td><td>Wall-clock time and bytes to target decrease on representative cohorts</td></tr>\n<tr><td>One global model leaves stable, distinct clusters underserved</td><td>Multimodal client objectives</td><td>Clustered models or shared backbone with local heads</td><td>Each cluster has enough support and outperforms the global baseline</td></tr>\n<tr><td>Heavy users dominate the aggregate</td><td>Objective-weight mismatch</td><td>Replace example weighting with user weighting or cap per-user contribution</td><td>Evaluation matches the declared user- or example-level objective</td></tr>\n</tbody></table></div>\n<p>: <strong>Non-IID Control Decisions</strong>: Non-IID data is not one scalar condition. The system should connect measured cohort skew or update conflict to a specific control and validate the result against the declared population objective. {#tbl-edge-noniid-control tbl-colwidths=\"[24,24,28,24]\"}</p>\n<h3 id=\"sec-42\" class=\"cs-h3\">Failure modes and prevention mechanisms</h3>\n<p>Beyond skewing cohort averages, uncurated local learning can corrupt a model on a single device: a keyboard prediction system that trains on all user inputs without separating intended words from corrections can incorporate recurring typos as valid suggestions and progressively degrade its own predictions. Because such failures in on-device learning emerge slowly, locally, and often without centralized evidence [@kairouz2021], unbounded adaptation drift can pull a deployed model far from its intended behavior before aggregate telemetry moves. This risk becomes acute in health monitoring applications where gradual changes in user baselines could be learned as \"normal,\" potentially causing the system to miss anomalies that a static model would have detected.</p>\n<p>Beyond individual device drift, the participation bias described under client scheduling (@sec-edge-intelligence-client-scheduling-f675) can amplify itself over time. Users whose models improve less engage less, which further reduces their representation in later rounds [@wang2021field]. The failure is slow and invisible in aggregate metrics, which is why cohort-level evaluation must accompany every accepted round.</p>\n<p>These systematic biases interact with data quality issues to create autocorrection feedback loops, particularly in text-based applications. When systems cannot distinguish between intended inputs and corrections, they may develop unexpected behaviors. Frequently corrected domain-specific terminology might be incorrectly learned as errors, leading to inappropriate suggestions in professional contexts. This problem compounds the drift issue, because models adapt to individual quirks and can simultaneously reinforce their own mistakes when users accept autocorrections without realizing the system learns from those interactions.</p>\n<p>These failure modes connect individual drift, population bias, and data-quality degradation. Federated-learning surveys identify heterogeneity, participation bias, privacy, and optimization instability as deployment risks [@li2020; @kairouz2021]. In response, successful systems can bound adaptation, stratify sampling, distinguish corrections from reliable labels, and use shadow comparisons to identify changes that warrant validated evaluation.</p>\n<h3 id=\"sec-43\" class=\"cs-h3\">Compliance, security, and recovery risks in production</h3>\n<p>Even when technical safeguards bound drift and sampling skew, post-release weight updates still face external governance constraints whenever a system operates in a regulated domain. When a medical wearable, financial fraud detector, or vehicle controller adapts its weights after release, the deployed model diverges from the artifact that passed regulatory review. An unverified local update can invalidate the audit trail, absorb poisoned inputs, or violate data-erasure rules. In domains where compliance, auditability, and regulatory approval are required, on-device learning creates a direct tension between local autonomy and operational control.</p>\n<p>A centrally managed training pipeline can record a common release's data, checkpoints, and evaluation results. On-device learning distributes the update history across local models and observations that may remain private. Traceability therefore depends on what the adaptation protocol records: the base version, permitted update policy, validation result, and available recovery point. The operator can retain control over those boundaries without collecting every local training example.</p>\n<p>This autonomy creates a validation gap. Evidence collected for the released model does not automatically establish the behavior of each adapted version. When inputs and update histories remain local, the deployment needs a defined set of local acceptance checks and a way to report failures within its privacy constraints. An adapted model can leave its validated operating range before aggregate monitoring detects the change, so the update policy must specify when to reject a candidate or restore the trusted baseline.</p>\n<p>Delayed detection complicates recovery, especially while a device is offline. A trusted baseline must remain available independently of the adapted candidate, and the restore policy must account for compatible preprocessing, adapters, and runtime state. Restoring weights alone may leave the faulty update trigger or contaminated replay data in place. Recovery therefore includes deciding which adaptation state to retain, quarantine, or reset before learning resumes.</p>\n<p>Every recovery path in this section assumes that something safe keeps operating while an adapted model is suspect or being restored. When perception and control loops rely on local models, that something is often a human supervisor, and a human fallback is not a safety mechanism unless the fallback itself is engineered as part of the system. A fatal 2016 crash under driver-assistance automation shows what happens when it is assumed instead.</p>\n<p><strong>Context</strong>: A 2015 Tesla Model S was using Traffic-Aware Cruise Control and Autosteer when it collided with a crossing semitrailer near Williston, Florida, on May 7, 2016 [@ntsb2017tesla]. The driver remained responsible for supervision.</p>\n<p><strong>Mechanism</strong>: The NTSB attributed the crash to the truck driver's failure to yield and the car driver's inattention associated with overreliance on automation. The automation's operational design contributed by permitting prolonged disengagement and use inconsistent with the manufacturer's guidance.</p>\n<p><strong>Impact</strong>: The car passed beneath the semitrailer, and its driver died.</p>\n<p><strong>Fix</strong>: The NTSB issued safety recommendations addressing automation safeguards and oversight. For an edge-system designer, the corresponding requirement is to make operational limits and the supervision contract enforceable rather than assume a human will recover from every local failure.</p>\n<p><strong>Systems lesson</strong>: Fast local execution is insufficient if the combined sensing, automation, and human-supervision system lacks a reliable fallback. Although this vehicle did not learn on the device, the lesson carries over to edge learning. A fallback contract is validated against fixed model behavior, and local adaptation changes that behavior after release, so every accepted update must leave the operational limits and the validated recovery path intact.</p>\n<p>Protecting the recovery path also requires securing the local state that triggers or feeds adaptation. Because on-device learning relies on device-specific data streams where central monitoring is limited, adversaries can tamper with replay buffers or inject poisoned examples during adaptation to push models into unsafe or biased states, while unauthorized access to stored feature embeddings or few-shot examples can leak personal information. The immediate design obligation is therefore to treat model state, replay buffers, and adaptation triggers as security-sensitive assets with local integrity checks, encrypted storage, and conservative update policies before adaptation begins.</p>\n<p>Privacy and data-protection regulations compound these local state obligations. While keeping raw observations on the device reduces transmission exposure, adaptation still stores and processes personal sensor traces and behavioral logs locally, invoking requirements for user consent, retention limits, auditability, and the GDPR's right to erasure. Because a user's data can influence adapted weights and cached representations in ways that are difficult to trace and reverse individually, compliant edge pipelines pair encrypted storage and retention windows with user-controlled reset mechanisms that purge local adaptation state and restore the validated baseline.</p>\n<p>Distributed adaptation also complicates debugging and failure analysis [@kairouz2021]. A deployment must assign responsibility for detecting regressions, suspending learning, restoring a baseline, and investigating failures before release. Local data drift, poor initialization, and faulty safeguards can produce similar symptoms, so the version and validation records must support diagnosis within the permitted disclosure limits. Autonomous execution does not remove the need for an accountable recovery process. Addressing these deployment and compliance risks requires tooling, protocols, and design practices that extend the ability to explain, bound, and reverse local adaptation (@sec-edge-intelligence-lifelong-adaptation-without-forgetting-9200) to external requirements for traceability, reproducibility, and user protection.</p>\n<h3 id=\"sec-44\" class=\"cs-h3\">Poisoned updates and the combined control path</h3>\n<p>Poisoning, inversion, drift, and validation failures also occur in centralized ML systems, but local adaptation makes them harder to observe, attribute, and roll back across a heterogeneous fleet. The billion-user keyboard model poisoned by a coordinated group of users shows why. The malicious updates arrive as ordinary contributions from authenticated devices, secure aggregation hides each one from inspection, and the shift they cause can stay below what a population average reveals. Defending against such poisoned updates is one of three obligations that local adaptation adds, alongside limiting what updates disclose and detecting local shift that population averages hide.</p>\n<p>↪ Data poisoning as a threat model, including poisoned contributions to federated training, is developed in @sec-security-privacy-data-poisoning-351f.</p>\n<p>The edge architecture must therefore bind adaptation range, update integrity, privacy accounting, robust aggregation, validation evidence, and rollback into one control path. These mechanisms do not substitute for one another. Secure aggregation hides individual contributions, robust statistics limit some malicious influence, and validated outcomes establish whether behavior improved.</p>\n<p>Traced through the slur attack, each control acts at a different point. Bounded local updates, checked before masking, cap how far any one device can push the shared model, although a coordinated group can still add many bounded pushes in the same direction. The masked sum keeps the coordinator from learning what each device typed, but it also keeps the coordinator from singling out the attackers' updates, so no per-client filter can remove them after masking. The change can surface in cohort-level evaluation and in shadow comparison against the frozen baseline, where the adapted model starts suggesting the slur, provided the evaluated inputs include the contexts the attack targets; a slur suggested only after a rare prefix can stay below the disagreement tolerance. When the comparison does flag it, the gate holds the candidate and fleet promotion waits; validated outcome evidence then confirms the regression and justifies rollback to the last compatible set of base model, adapters, and policy.</p>\n<p>: <strong>Byzantine fault tolerance in federated learning (FL)</strong>: Named after the Byzantine Generals Problem [@lamport1982byzantine], this property enables useful aggregation despite malicious or faulty participants; how many faulty participants a rule such as Krum or trimmed mean tolerates depends on that rule's own conditions, which @sec-fault-tolerance-reliability-reliability-byzantine-failures-8a24 states. These defenses can increase communication and compute overhead because they require extra validation, robust statistics, or redundant participation.</p>\n<h2 id=\"sec-45\" class=\"cs-h2\">Fallacies and Pitfalls</h2>\n<p>Each stage of that control path exists because edge learning fails whenever a team treats on-device adaptation as a drop-in extension of cloud inference or centralized training. For example, a team that ports a cloud-trained recommendation model to a mobile app and assumes that successful inference also permits local fine-tuning quickly hits the training amplification wall. The first update can exceed the app's memory allowance as gradients and saved activations accumulate; a configuration that fits can still consume more energy than the background policy permits. These distinct failures motivate the following fallacies and pitfalls:</p>\n<p><strong>Fallacy</strong>: <em>On-device learning provides the same adaptation capabilities as cloud-based training.</em></p>\n<p>Teams expect local learning to match centralized training's model improvements, ignoring the device's resource constraints. Full-model training adds activations, gradients, and optimizer state to the weights; the configurations in @sec-edge-intelligence-quantifying-training-overhead-edge-devices-3e4c require <code>[EdgeTrainingMemoryStack.range_mult_str]</code> the inference weights alone, depending on the model and execution schedule. Local datasets are typically small, biased, and nonrepresentative, while compute budgets remain orders of magnitude below cloud GPUs. A smartphone with <code>[EdgeAdaptationTierProfile.smartphone_ram_gb_str]</code> RAM and a sustained power budget of <code>[EdgeMobilePowerEnvelope.sustained_range_str]</code> cannot replicate the adaptation achieved by data center systems with terabytes of memory and kilowatts of power. Effective on-device learning requires designing adaptation strategies that provide meaningful improvements within these constraints rather than attempting to replicate cloud-scale learning capabilities.</p>\n<p><strong>Pitfall</strong>: <em>Assuming federated learning automatically preserves privacy without additional safeguards.</em></p>\n<p>Practitioners believe that keeping data on local devices inherently provides privacy protection, ignoring what can be inferred from model updates. Gradient and parameter updates leak significant information about local training data through various inference attacks, while device participation patterns reveal sensitive information about users and activities. Stronger privacy preservation requires additional mechanisms. Differential privacy provides a tunable probabilistic bound on how much the output distribution can change because of one individual's data, while secure aggregation protocols prevent parameter inspection during server-side coordination through zero-sum cryptographic masking (@fig-secure-agg) [@bonawitz2017]. Data locality alone is insufficient for privacy protection.</p>\n<p><strong>Fallacy</strong>: <em>Resource-constrained adaptation always produces better personalized models than generic models.</em></p>\n<p>This belief assumes that any local adaptation is beneficial regardless of the quality or quantity of local data available. On-device learning with insufficient, noisy, or biased local data can actually degrade model performance compared to well-trained generic models (@sec-edge-intelligence-data-efficiency-c701). Small datasets may not provide enough signal for meaningful learning, while adaptation to local noise can harm generalization. Effective on-device learning systems must include mechanisms to detect when local adaptation is beneficial and fall back to generic models when local data is inadequate for reliable learning.</p>\n<p><strong>Pitfall</strong>: <em>Ignoring heterogeneity across different device types and capabilities.</em></p>\n<p>Teams design on-device learning systems assuming uniform hardware capabilities across deployment devices. Real-world deployments span diverse hardware with varying computational power, memory capacity, energy constraints, and networking capabilities. Available memory alone spans roughly <code>[EdgeDeviceSpectrum.memory_ratio_mult_str]</code> between <code>[EdgeDeviceSpectrum.mcu_sram_kb_str]</code> microcontroller SRAM and <code>[EdgeDeviceSpectrum.flagship_ram_gb_str]</code> flagship phones (@sec-edge-intelligence-managing-milliondevice-heterogeneity-86c1), and supported operators and power envelopes differ as sharply. Clock frequency or peak ratings from unrelated architectures do not convert into a common training-throughput ratio, so the comparison needs measured update cost under matched tasks and declared operating states. A learning algorithm that works well on high-end smartphones may fail catastrophically on resource-constrained IoT devices. Federated learning algorithms must account for heterogeneous clients and availability [@kairouz2021; @bonawitz2019towards], using selective participation, compression, and tiered aggregation strategies when devices have substantially different measured update costs.</p>\n<p><strong>Pitfall</strong>: <em>Underestimating the complexity of coordinating learning across distributed edge systems.</em></p>\n<p>Many teams focus on individual device optimization and treat coordination as a stateless averaging server, as if local updates arrived regularly from comparable devices. At fleet scale the aggregator is one component of a control loop that must know which devices are eligible, which model version each holds, and whether a returned update is safe to promote. A production system selects about 130 percent of its target cohort [@bonawitz2019towards] because a substantial fraction of selected devices never report. Edge orchestration (@sec-edge-intelligence-largescale-device-orchestration-1360) must also handle intermittent connectivity, varying power states, time zones, and version skew across devices that return after days offline. A design that budgets only for the averaging step leaves round deadlines, partial participation, and state reconciliation unowned, although those parts of the loop decide whether each round completes with a representative cohort.</p>\n<h2 id=\"sec-46\" class=\"cs-h2\">Summary</h2>\n<p>Edge intelligence extends the fleet to devices whose memory, power, and availability the operator cannot standardize. Sensors, microcontrollers, and smartphones contribute under different resource budgets, so a locally feasible learning policy also determines which parts of the population can participate. Archetype C (Federated MobileNet) makes that coupling concrete across all three axes of C³. Local adaptation spends the compute axis inside each phone's power and memory envelope, while adapters and update compression shrink the wide-area transfer in the Fleet Law's communication term, and over-selection with round deadlines caps the Fleet Law's synchronization term at the price of which devices are represented.</p>\n<p>Three levers make learning possible under those constraints, and each acts on a different part of the same budget. Model adaptation shrinks trainable state and, when placed well, the saved activations that dominate peak memory. Data efficiency raises the signal extracted from each scarce example and protects earlier behavior with bounded replay. Federated coordination lets compatible updates from many devices improve one shared model without centralizing raw data. None of the three moves the device's thermal, energy, or bandwidth limits; each decides how much useful learning fits inside them.</p>\n<p>At runtime, those realities become an admission decision rather than a general preference to run \"when idle.\" Background adaptation may execute only when its predicted energy and sustained power fit the current device slack and profiled worst-case interference preserves the foreground deadline. Because charging status does not eliminate heat or contention, every admitted window remains revocable as the device state changes.</p>\n<p>Local execution can meet latency, data-locality, and offline requirements, but those requirements alone do not justify local training. Adaptation must improve a validated outcome within its resource budget; federation must then preserve update compatibility, control disclosure, and evaluate the population actually represented by completed updates.</p>\n<div class=\"cs-callout\"><div class=\"cs-callout-title\">Takeaways</div>\n<ul class=\"cs-list\">\n<li><strong>The edge reverses the fleet</strong>: Data centers fight to keep many accelerators busy; edge devices fight to learn under batteries, kilobytes, thermal throttling (the device-scale counterpart of principle \\ref{pri-power-density-wall}), and intermittent links. The same Compute, Communication, Coordination constraints must account for device eligibility as well as aggregate throughput.</li>\n<li><strong>Bandwidth beats advertised TOPS</strong>: One update step of the chapter's 10M-parameter example moves about <code>[EdgeUpdateTraffic.step_traffic_mb_str]</code>, <code>[EdgeUpdateTraffic.traffic_ratio_mult_str]</code> the weight bytes read by an inference, across a phone memory interface roughly <code>[EdgeH100BwRecap.ratio_low_str]</code>--<code>[EdgeH100BwRecap.ratio_high_mult_str]</code> narrower than data-center HBM. That is the same ceiling that bounds memory-bound decode (principle \\ref{pri-autoregressive-bottleneck}). Quantization and locality help, but measured update speed depends on bytes moved and sustained bandwidth.</li>\n<li><strong>Learning multiplies the footprint</strong>: Full-model backpropagation can require <code>[EdgeTrainingMemoryStack.range_mult_str]</code> the memory occupied by inference weights alone in the chapter's configurations, depending on optimizer state, activations, and precision. Reducing trainable state helps only when the frozen model and remaining execution state also fit.</li>\n<li><strong>Background learning is conditional work</strong>: Admit an adaptation window only when @eq-edge-background-admission preserves energy, thermal, and foreground-latency budgets under worst-case measured interference. Charging alone is not sufficient.</li>\n<li><strong>Admission selects the population</strong>: Passing the admission test correlates with hardware, charging habits, and connectivity, so the shared model learns from the admitted devices rather than the deployed fleet (principle \\ref{pri-participation-selects-population}). Per-cohort participation and quality must be measured and corrected; loosening admission spends the budgets it exists to protect.</li>\n<li><strong>Each technique spends a different budget</strong>: Bias-only updates, LoRA, sparse layers, few-shot data reuse, and experience replay each spend different memory, energy, and privacy budgets. Federated coordination adds population learning only when cumulative uploads stay below the data they replace, enough clients survive to clear secure aggregation's participation floor so individual updates stay hidden, and shared state stays version-compatible.</li>\n<li><strong>Heterogeneity is normal operation</strong>: Edge fleets span microcontrollers, phones, gateways, and NPUs with uneven availability, performance, and non-IID data. Stragglers, client drift, participation bias, and privacy-preserving observability are protocol design constraints, not deployment cleanup. Once models learn after release, the release artifact is the adaptation policy, versioned against a base model that rollback can restore.</li>\n</ul>\n</div>\n<p>An edge learning policy determines both the work a device may perform and the population the fleet learns from. Tightening a resource budget can protect a user's foreground experience while excluding that user's data from shared improvement. The useful design target is therefore validated adaptation across the intended population, with local feasibility and fleet representation evaluated together.</p>\n<div class=\"cs-callout\"><div class=\"cs-callout-title\">Chapter Connection</div>\n<p>Once a model continues learning after release, what the fleet ships is no longer a fixed set of weights but an adaptation rule versioned against a base model, admitted device by device, validated through distributed outcome evidence when central labels are unavailable, and judged by which cohorts its completed updates represent. Production organizations run hundreds of models at once, many sharing features, data pipelines, and release machinery, so a change made for one can silently break another. Keeping that portfolio versioned, observable, and recoverable is a coordination problem in its own right.</p>\n</div>\n<p>↪ The control plane that versions, releases, monitors, and rolls back a portfolio of models is developed in @sec-ops-scale.</p>", "quizzes": [{"section": "The Edge Learning Paradigm", "type": "MCQ", "question": "A mobile robotics vision system must process each frame within $33\\text{ ms}$, while cloud network round-trip time is $80\\text{–}150\\text{ ms}$. Why must the foreground perception path execute locally even if model training remains in the cloud?", "choices": ["Network round-trip latency alone exceeds the foreground deadline, so a frame cannot wait for a cloud response.", "Cloud data centers are physically incapable of computing backpropagation gradients on batch sizes of one within milliseconds.", "The on-device camera sensor cannot serialize video frames into digital packets without first running an on-device forward-backward training pass.", "On-device adaptation reduces model parameter count to zero before sending updates across the cellular uplink."], "answer": "The correct answer is A. An $80\\text{–}150\\text{ ms}$ round trip cannot fit inside a $33\\text{ ms}$ foreground deadline, regardless of server compute speed. This establishes the need for local inference; it does not establish the need for local training, which requires a separate adaptation benefit and resource budget."}, {"section": "The Edge Learning Paradigm", "type": "SHORT", "question": "Before investing in an on-device gradient-based learning pipeline for a mobile news app, an ML systems architect considers feature-based personalization (local feature caching with a frozen global model) versus on-device gradient fine-tuning. Under what systems criteria is feature-based personalization preferred, and what eliminates the need for local backpropagation?", "choices": [], "answer": "Feature-based personalization is preferred when local preference vectors, interaction histories, or lookup embeddings give a frozen model the useful context it needs. Its parameters do not change, so this path avoids weight-gradient, backward-pass, and optimizer-state costs. Local feature state and inference buffers still consume resources. Compare validated personalization quality and the complete footprint against a gradient-based candidate; the chapter’s 4–12x range describes particular full-model training configurations relative to weight storage, not a universal amplification."}, {"section": "Design Constraints", "type": "MCQ", "question": "A mobile engineering team observes that fine-tuning a 10M parameter vision model on a smartphone with 8 GB of RAM causes the background training process to be killed by the operating system's out-of-memory (OOM) killer during backpropagation. Why does training memory demand spike so severely compared to inference for the exact same model?", "choices": ["The base model weights dynamically expand by $100\\times$ during the forward pass due to weight unpacking.", "Floating-point units on mobile SoCs automatically convert all INT8 weights to FP64 double precision during training.", "Training adds gradients, optimizer state, and saved backward activations to the weights; the simultaneous peak can exceed the app’s budget even when inference fits.", "The mobile operating system creates a separate virtual machine sandbox for every individual neuron in the neural network."], "answer": "The correct answer is C. Training can retain activations needed for backward computation, gradients, and optimizer state in addition to weights. Their simultaneous peak can exceed a background process budget even when total device RAM is much larger. The amplification is configuration-dependent; inference also requires activation buffers and workspace, not necessarily only one layer of activations."}, {"section": "Design Constraints", "type": "MCQ", "question": "A quantized 7B-parameter language model achieves 12 tokens/sec on a mobile SoC advertised at 45 peak TOPS. Profiling shows that low-batch decode saturates available DRAM bandwidth while arithmetic units wait. Which hardware resource is the binding constraint?", "choices": ["Insufficient CPU integer arithmetic capacity for calculating cross-entropy loss.", "Thermal throttling of the wireless 5G modem during token generation.", "Flash storage read latency when loading the token tokenizer vocabulary.", "Mobile LPDDR5/LPDDR5X memory bandwidth ($51\\text{–}77\\text{ GB/s}$), which is roughly $44\\text{–}65\\times$ lower than data-center HBM3, causing the memory streaming term $(D_{\\text{vol}} / \\text{BW})$ to dominate execution time per token."], "answer": "The correct answer is D. Low-batch autoregressive decode often streams a large weight volume per token, so limited mobile DRAM bandwidth can dominate despite high peak TOPS. The stated peak rates alone do not prove the measured bottleneck: profiling must check achieved bandwidth, operator support, and thermal limits. Tokenizer initialization and loss computation do not explain steady-state decode throughput."}, {"section": "Model Adaptation", "type": "MCQ", "question": "Why does Tiny Transfer Learning (TinyTL) freeze convolutional backbone weights and adapt biases with optional lite residual modules?", "choices": ["Freezing removes backbone weight-gradient and optimizer state; suitable activation and normalization choices also reduce saved backward state.", "Microcontroller hardware units physically short-circuit if matrix multiplications are performed in reverse during backpropagation.", "Bias parameters have mathematical properties that prevent all forms of numerical underflow in 8-bit fixed-point arithmetic.", "Training bias parameters modifies the underlying kernel weights directly through implicit singular value decomposition."], "answer": "The correct answer is A. Frozen weights need no weight gradients or optimizer state, but they remain part of the deployed model. Gradients may still traverse frozen operators, and nonlinearities can require saved state. TinyTL reduces these costs through its adaptation path and operator choices; it does not guarantee an arbitrary backbone fits microcontroller SRAM. Bias updates do not modify frozen kernels."}, {"section": "Model Adaptation", "type": "MCQ", "question": "A mobile vision engineer chooses between Low-Rank Adaptation (LoRA) and Residual Bottleneck Adapters for on-device camera personalization. The system requires zero additional inference latency during real-time 60 FPS video capture, while another use case requires hot-swapping between 10 user contexts without reloading the base model. How do LoRA and Residual Adapters compare across these requirements?", "choices": ["Residual Adapters introduce zero inference latency because they replace the backbone, while LoRA requires recomputing matrix inverses on every video frame.", "LoRA updates can be merged into compatible base weights to remove the adapter execution path, while residual adapters retain separate computation and support modular context switching.", "LoRA updates require storing 10 full copies of the 7B base model in SRAM, whereas Residual Adapters operate without trainable parameters.", "Both methods require identical memory footprints and add exactly 50 ms of inference latency per layer."], "answer": "The correct answer is B. A compatible linear LoRA update can be merged as $W_{\\text{final}}=W_{\\text{base}}+BA$, removing separate adapter operations. Residual adapters retain their own computation, whose latency must be measured. Unmerged LoRA also supports context switching; the distinction is mergeability, not exclusive access to hot-swapping. Neither method requires copies of the entire base model per context."}, {"section": "Data Efficiency", "type": "MCQ", "question": "A developer of a keyword spotting (KWS) system for smart home appliances wants users to configure custom wake words using 5 to 10 spoken samples. Why is few-shot adaptation of a classification head on top of a frozen acoustic encoder preferred over end-to-end retraining?", "choices": ["End-to-end retraining of acoustic encoders produces audio waveforms that violate device speaker impedance limits.", "Spoken custom wake words cannot be processed by neural networks unless the entire encoder architecture is expanded by $10\\times$.", "Updating only the head restricts trainable state and preserves frozen encoder representations, reducing adaptation cost and overfitting risk relative to full retraining.", "The Fourier transform algorithm only converges when supervised labels exceed 100,000 samples."], "answer": "The correct answer is C. A pretrained encoder can supply reusable acoustic features while a small head adapts to a few user examples. Freezing the encoder reduces trainable state and preserves its parameters, but does not guarantee accuracy or a particular power and memory footprint. Measure the adaptation path separately from always-on inference; speaker impedance and Fourier-transform convergence do not govern this choice."}, {"section": "Data Efficiency", "type": "MCQ", "question": "An edge health tracker adapts a continuous activity classifier to a user's walking gait over several weeks. When the user starts cycling, the device adapts its model, but suddenly misclassifies normal walking as cycling. What core failure mode has occurred, and why did it happen?", "choices": ["Overfitting on a single static batch caused by excessive L2 regularization.", "Numerical floating-point overflow in the hardware accelerometer sensor buffer.", "Model inversion attack where cycling data erased the operating system kernel.", "Catastrophic forgetting, where sequential gradient updates on new data distributions overwrite the weight configurations responsible for preserving performance on previously learned tasks."], "answer": "The correct answer is D. Catastrophic forgetting is the fundamental stability failure of sequential learning in neural networks: when a model updates parameters on a new data stream (cycling) without mechanisms to preserve prior distributions (walking), gradient steps overwrite the representations that encoded the old task. Overfitting on a single batch does not describe sequential task erosion. Sensor overflow is a hardware I/O fault, and model inversion is an adversarial privacy attack, not a continuous learning stability failure."}, {"section": "Federated Learning Algorithms", "type": "MCQ", "question": "In the Federated Averaging (FedAvg) algorithm, what is the primary algorithmic trade-off when tuning the number of local training epochs ($\\LocalEpochCount$) on client devices?", "choices": ["Increasing local work can amortize communication, but may increase client drift on non-IID data; rounds and elapsed time to the same quality target must be measured.", "Increasing $\\LocalEpochCount$ forces the central server to store full training datasets from all participating clients in server DRAM.", "Increasing $\\LocalEpochCount$ eliminates the need for clients to compute backward passes during local training.", "Increasing $\\LocalEpochCount$ increases the size (in megabytes) of the transmitted model parameter vector by a factor of $\\LocalEpochCount^2$."], "answer": "The correct answer is A. More local epochs can reduce communication frequency, but do not guarantee fewer rounds or less time to a fixed quality target. Non-IID local updates can increase client drift. Compare candidate $\\LocalEpochCount$ values under matched data and participation conditions, recording validated target quality, elapsed round times, bytes, and energy. More epochs neither transfer raw data nor change the parameter vector dimension."}, {"section": "Federated Learning Algorithms", "type": "MCQ", "question": "A mobile federated learning deployment encounters severe client drift due to extreme non-IID typing patterns across users, causing standard FedAvg to oscillate and fail to converge. Which algorithmic modification directly addresses client drift by constraining local updates to stay close to the global model?", "choices": ["Switching from 32-bit floating-point to 1-bit stochastic sign quantization without error compensation.", "Adding a proximal regularization term $\\frac{\\mu}{2} \\|w - w_t\\|^2$ to the local client objective (as in FedProx) to penalize excessive deviation from the global server model $w_t$.", "Increasing the local learning rate by $10\\times$ to accelerate convergence on outlier devices.", "Dropping the central aggregation server and allowing devices to train purely in isolation without synchronization."], "answer": "The correct answer is B. FedProx adds $\\frac{\\mu}{2}\\|w-w_t\\|^2$ to penalize departure from the current global reference. This can mitigate client drift, but does not guarantee convergence for every workload or hyperparameter choice; evaluate matched quality and resource budgets. Raising the learning rate can worsen drift, while isolated training abandons the federated objective."}, {"section": "Federated Learning Systems at Scale", "type": "MCQ", "question": "In production cross-device federated learning (such as Google Gboard), why do systems implement Over-Selection of clients (selecting $\\CandidateClientCount \\approx 1.3 \\times \\TargetUpdateCount$ devices per round) rather than selecting exactly $\\TargetUpdateCount$ devices?", "choices": ["Over-selection ensures that every mobile client receives $1.3\\times$ the monetary payment for participating.", "Over-selection forces client devices to increase their CPU clock frequencies by $30\\%$ during training.", "Selecting surplus candidates can reach the target number of valid reports earlier than waiting for every selected device, provided enough clients complete; a deadline and incomplete-round policy are still required.", "The aggregation server requires exactly $30\\%$ redundant updates to perform parity-bit error correction on the GPU memory bus."], "answer": "The correct answer is C. Over-selection accommodates dropout and slow completion. If enough valid reports arrive, the round can proceed at the target-th completion rather than waiting for the slowest selected device. A surplus pool does not guarantee that the target is reached or prevent a stalled round by itself. The coordinator also needs a deadline, acceptance or abandonment rules, and evaluation of the completed cohort. The approximate 1.3 factor is a deployment example, not a universal setting."}, {"section": "Federated Learning Systems at Scale", "type": "MCQ", "question": "How does the Secure Aggregation (SecAgg) cryptographic protocol protect individual client privacy during federated aggregation on a central server?", "choices": ["Clients transmit raw unencrypted updates, and the server permanently deletes its hard drive after every round.", "Clients train on synthetic dummy data generated by the server, ensuring real gradients are never computed.", "The server encrypts all client devices using a remote ransomware key until the global round terminates.", "Participating client pairs agree on shared pseudo-random masks that are added by one client and subtracted by the other; when the server sums all received masked updates, the masks algebraically cancel out, revealing the exact global aggregate without exposing any individual update."], "answer": "The correct answer is D. Clients establish pairwise secrets and generate opposite masks, so masks cancel when the protocol forms an authorized aggregate. Dropout recovery requires additional protocol steps. Individual-update confidentiality depends on the participant threshold and threat model; it does not make the released aggregate differentially private. Deleting a server disk after receiving raw updates offers no comparable protection."}]};
